import { Book } from "@/lib/types";

export const ezekiel: Book = {
  id: "ezekiel",
  name: "Hesekiel",
  shortName: "Hes",
  testament: "old",
  introduction: `Die Botschaft von der Herrlichkeit Gottes\nHesekiël stammte aus einer Priesterfamilie und wurde als Dreißigjähriger am Fluss Kebar in der Nähe Babylons zum Propheten berufen. Vier Jahre vorher war er mit 10.000 anderen Juden von Jerusalem aus nach Babylon verschleppt worden. Zwei Jahre vor seiner Berufung hatten die Verbannten einen Brief des Propheten Jeremia aus dem 1300 km entfernten Jerusalem erhalten, in dem sie ermutigt wurden, sich in der Gefangenschaft einzurichten, denn sie würden insgesamt 70 Jahre lang dort bleiben müssen (Jeremia 29).\n**Der Prophet Hesekiël** empfing seine Botschaft hauptsächlich in Visionen und gab sie in Gleichnisreden und –handlungen wieder. Er ist der einzige der großen Propheten, der seine Weissagungen genau datiert. Sein Dienst begann 593 v.Chr. und dauerte mindestens 22 Jahre bis 571 v.Chr.\nVor der völligen Zerstörung Jerusalems predigte er Gericht und Buße (bis Kapitel 32), danach aber wurde er zum Tröster und Prediger von Hoffnung und Zuversicht, denn bis ins letzte Detail beschrieb er Israels künftigen Ruhm und Glanz (Kapitel 33-48). Sein Leitmotiv ist die Herrlichkeit Gottes. Kein anderer Prophet benutzte so viele Bilder und visuelle Hilfsmittel wie er. Hesekiël schrieb die empfangenen Botschaften und Erfahrungen selbst nieder.\n****Wie der Prophet im Exil zuerst Gericht und Umkehr predigt, dann aber zu einem Verkündiger der Hoffnung Israels wird.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "In meinem 30. Lebensjahr*, am 5. Juli*, befand ich mich unter den Verbannten am Fluss Kebar*. Da öffnete sich der Himmel und ich sah Erscheinungen Gottes.", heading: "1-32: Gottes Herrlichkeit zieht aus\nGottes Herrlichkeit trifft den Propheten (1-3)", footnotes: ["30. Lebensjahr. Wörtlich: Im 30. Jahr. Das bezieht höchstwahrscheinlich auf das Alter Hesekiëls. In diesem Alter konnte nach 4. Mose 4,3 ein Levit seinen Priesterdienst antreten.", "Juli. Wörtlich: des 4. Monats. Zum Datum siehe unter Schaltmonat im Vorwort des Übersetzers.", "Der Kebar war ein Euphrat-Kanal in der Nähe der Stadt Nippur, südlich von Babylon. Offenbar versammelten sich die verschleppten Juden dort zum Gebet."] },
      { number: 2, text: "An diesem Tag* – es war das fünfte Jahr, nachdem König Jojachin in die Verbannung geführt* worden war –", footnotes: ["diesem Tag. Wörtlich: am 5. des Monats.", "597 v.Chr. wurde Jojachin in die Verbannung geführt. Hesekiëls Berufung fand also im Jahr 593 v.Chr. statt."] },
      { number: 3, text: "kam das Wort Jahwes zu mir, den Priester Hesekiël Ben-Busi im Land der Chaldäer am Fluss Kebar. Dort legte Jahwe seine Hand auf mich." },
      { number: 4, text: "Da sah ich plötzlich einen Sturm herantoben. Er kam aus dem Norden. Und ich sah eine mächtige Wolke, ein zusammengeballtes Feuer, das von einem strahlenden Glanz umgeben war. Mitten im Feuer glänzte es wie Gold.", heading: "Die Herrlichkeit Jahwes" },
      { number: 5, text: "Dort erblickte ich vier Lebewesen, die wie Menschen aussahen." },
      { number: 6, text: "Doch hatte jedes von ihnen vier Gesichter und vier Flügel." },
      { number: 7, text: "Ihre Beine standen gerade, aber ihre Fußballen waren wie die eines jungen Stiers. Sie funkelten wie geglättetes Kupfer." },
      { number: 8, text: "Unter ihren Flügeln hatten sie an allen vier Seiten Menschenhände. Alle vier hatten Gesichter und Flügel;" },
      { number: 9, text: "und mit den Enden der ausgespannten Flügel berührten sie sich gegenseitig. Sie konnten sich in alle Richtungen bewegen, ohne sich umzudrehen." },
      { number: 10, text: "Jedes der vier Lebewesen hatte vorn das Gesicht eines Menschen, rechts das eines Löwen, links das eines Stiers und hinten das eines Adlers." },
      { number: 11, text: "Zwei ihrer Flügel waren nach oben hin ausgespannt und berührten die des anderen Wesens. Und zwei verhüllten ihren Körper." },
      { number: 12, text: "Sie gingen, wohin der Geist es wollte, und keines von ihnen musste sich dabei umdrehen." },
      { number: 13, text: "Mitten zwischen den Lebewesen war etwas, das aussah wie brennende glühende Kohlen und wie Fackeln, deren Feuer zwischen ihnen hin und her zuckte. Das Feuer leuchtete hell, und Blitze schossen aus ihm." },
      { number: 14, text: "Auch die Lebewesen selbst liefen hin und her. Es sah aus wie ein Wetterleuchten." },
      { number: 15, text: "Als ich die Lebewesen näher betrachtete, sah ich an der Vorderseite von jedem ein Rad, das den Boden berührte." },
      { number: 16, text: "Alle Räder waren gleich gebaut und funkelten wie Edelsteine. Es sah aus, als ob ein Rad mitten im anderen wäre," },
      { number: 17, text: "sodass sie nach allen vier Richtungen laufen konnten, ohne gedreht zu werden." },
      { number: 18, text: "Ihre Felgen hatten eine gewaltige Höhe und waren furchtbar anzusehen: Sie waren alle vier voller Augen." },
      { number: 19, text: "Wenn die Lebewesen sich fortbewegten, bewegten sich auch die Räder mit ihnen, und wenn sie sich von der Erde erhoben, erhoben sich auch die Räder." },
      { number: 20, text: "Sie gingen, wohin der Geist es wollte. Die Räder hoben sich immer mit den Lebewesen, denn sie wurden von ihrem Geist bewohnt." },
      { number: 21, text: "Ganz gleich, ob sie sich bewegten oder stillstanden oder sich von der Erde erhoben – die Räder taten dasselbe, denn der Geist der Lebewesen lenkte sie." },
      { number: 22, text: "Über den Köpfen der Lebewesen war etwas ausgebreitet, das wie eine Wölbung* aussah, wie funkelndes Eis, furchteinflößend.", footnotes: ["Wölbung. Hebräisch: Rakia. Das gleiche Wort wie in 1. Mose 1,6, das etwas Festes und Dünnes bezeichnet."] },
      { number: 23, text: "Unter der Wölbung hielten die Lebewesen je zwei ihrer Flügel ausgespannt. Mit den Enden dieser Flügel berührten sie sich gegenseitig, und mit den zwei anderen verhüllten sie ihren Körper." },
      { number: 24, text: "Wenn sie sich bewegten, vernahm ich das Geräusch ihrer Flügel. Es hörte sich an wie die Brandung des Meeres, wie die Stimme des Allmächtigen, wie ein hallendes Tosen, wie der Lärm eines Heerlagers. Wenn sie stillstanden, ließen sie ihre Flügel sinken." },
      { number: 25, text: "Doch wenn sie mit gesenkten Flügeln standen, hallte eine Stimme von oberhalb der Wölbung über ihren Köpfen." },
      { number: 26, text: "Denn über der Wölbung befand sich etwas, das wie ein Saphir* aussah, wie ein Thron, und auf dem, was wie ein Thron aussah, war eine Gestalt zu erkennen, die einem Menschen glich.", footnotes: ["Saphir. Ein blauer Edelstein, der wie ein Diamant funkelt."] },
      { number: 27, text: "Oberhalb von dem, was wie seine Hüften aussah, war so etwas wie helles Gold, wie Feuer, das ringsum ein Gehäuse hat. Auch unterhalb sah ich so etwas wie ein loderndes Feuer mit einem Lichtglanz darum." },
      { number: 28, text: "Das strahlende Licht um ihn herum sah wie der Bogen aus, der am Regentag in den Wolken erscheint. So zeigte sich die Herrlichkeit Jahwes. – Als ich das sah, warf ich mich nieder auf mein Gesicht. Dann hörte ich jemand reden." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Er sagte zu mir: \"Stell dich auf deine Füße, Mensch, ich will mit dir reden!\"", heading: "Hesekiëls Berufung" },
      { number: 2, text: "Da kam der Geist in mich und stellte mich auf die Füße. Dann hörte ich ihn sagen:" },
      { number: 3, text: "\"Du Mensch, ich sende dich zum Volk Israel, zu den Stämmen, die sich gegen mich aufgelehnt haben. Sie und ihre Vorfahren sind bis heute immer wieder von mir abgefallen." },
      { number: 4, text: "Ich sende dich zu den Leuten mit dem frechen Gesicht und dem harten Herzen. Ihnen sollst du sagen: 'So spricht Jahwe, der Herr!'" },
      { number: 5, text: "Ob sie dann hören oder nicht – sie sind ja ein stures Volk –, so sollen sie doch wissen, dass es einen Propheten unter ihnen gibt." },
      { number: 6, text: "Doch du, Mensch, hab keine Angst vor ihnen! Lass dich von ihren Worten nicht einschüchtern! Auch wenn Dornen dich umgeben und du auf Skorpionen sitzt: Fürchte dich nicht vor ihren Worten und erschrick nicht vor ihren Mienen! Sie sind nun mal ein stures Volk." },
      { number: 7, text: "Du musst ihnen meine Worte sagen, ob sie hören oder nicht! Denn sie sind sehr widerspenstig. –" },
      { number: 8, text: "Doch du, Mensch, höre, was ich dir sage! Sei nicht trotzig wie dieses sture Volk! Mach deinen Mund auf und iss, was ich dir gebe!\"" },
      { number: 9, text: "Auf einmal sah ich vor mir eine ausgestreckte Hand und auf ihr eine Schriftrolle." },
      { number: 10, text: "Als er sie vor mir aufrollte, sah ich, dass sie vorn und hinten mit Klagen, Seufzern und Weherufen beschrieben war." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Da sagte er zu mir: \"Nimm diese Schriftrolle, Mensch, und iss sie auf! Dann geh los und rede zu den Leuten von Israel!\"" },
      { number: 2, text: "Ich öffnete den Mund, und er gab mir die Rolle zu essen." },
      { number: 3, text: "Dabei sagte er: \"Füll deinen Magen mit dieser Schriftrolle, Mensch, und iss sie ganz auf!\" Ich aß die Rolle. Sie schmeckte süß wie Honig." },
      { number: 4, text: "Dann sagte er zu mir: \"Geh nun zu den Israeliten und gib ihnen meine Worte weiter." },
      { number: 5, text: "Ich schicke dich ja nicht zu einem Volk mit fremder und schwieriger Sprache, sondern zu Israel." },
      { number: 6, text: "Wenn ich dich zu Völkern mit fremden und schwierigen Sprachen schicken würde – sie würden auf dich hören!" },
      { number: 7, text: "Aber die Leute von Israel werden nicht auf dich hören wollen, weil sie mich nicht hören wollen, denn sie haben eine harte Stirn und ein verstocktes Herz." },
      { number: 8, text: "Doch ich mache dein Gesicht ebenso hart wie ihres und deine Stirn wie ihre Stirn," },
      { number: 9, text: "ja noch härter, wie Diamant und Kieselstein. Hab keine Angst vor ihnen und erschrick nicht vor ihren Mienen. Sie sind ein stures Volk.\"" },
      { number: 10, text: "Weiter sagte er zu mir: \"Hör mir gut zu, Mensch, und nimm dir meine Worte zu Herzen!" },
      { number: 11, text: "Nun auf mit dir! Geh zu den Verschleppten aus deinem Volk und sag zu ihnen – ob sie es hören wollen oder nicht –: 'So spricht Jahwe, der Herr!'\"" },
      { number: 12, text: "Da hob mich der Geist hoch. Hinter mir vernahm ich ein starkes Getöse, – Gepriesen sei die Herrlichkeit Jahwes von seiner Wohnung her! –" },
      { number: 13, text: "und das Rauschen der Flügel dieser Lebewesen, die einander berührten, und das Sausen der Räder neben ihnen. Es war ein gewaltiges Dröhnen." },
      { number: 14, text: "Der Geist hob mich also hoch und nahm mich weg. Jahwes Hand lag hart auf mir, und ich fuhr dahin, erbittert in grimmigem Zorn." },
      { number: 15, text: "So kam ich zu den Verschleppten, die in Tel-Abib am Fluss Kebar wohnten, und saß sieben Tage lang verstört unter ihnen." },
      { number: 16, text: "Nach diesen sieben Tagen kam das Wort Jahwes zu mir. Er sagte:", heading: "Der Prophet als Wächter" },
      { number: 17, text: "\"Du Mensch, ich habe dich zum Wächter für die Leute von Israel bestellt. Wenn du eine Botschaft von mir bekommst, musst du sie in meinem Auftrag warnen!" },
      { number: 18, text: "Wenn ich also zu dem Schuldigen sage: 'Du musst sterben!', und du hast ihn nicht gewarnt, ihn nicht von seinen schlimmen Wegen abgebracht, du hast ihm nichts gesagt, um sein Leben zu retten – dann wird er zwar sterben, wie er es verdient hat, aber dich ziehe ich für seinen Tod zur Rechenschaft!" },
      { number: 19, text: "Warnst du den Schuldigen und er bekehrt sich nicht von seiner Gottlosigkeit und seinem unrechten Tun – dann wird er wegen seiner Schuld sterben, aber du hast dein Leben gerettet." },
      { number: 20, text: "Und wenn ein Mensch, der gottgefällig lebt, sich davon abwendet und anfängt, Unrecht zu tun, weil ich ihn auf die Probe gestellt habe, dann muss er sterben. Alles Gute, was er vorher getan hat, zählt dann nicht mehr. Hast du ihn nicht gewarnt, muss er wegen seiner Sünde sterben, aber dich ziehe ich für seinen Tod zur Rechenschaft!" },
      { number: 21, text: "Doch wenn du den Gerechten gewarnt hast, dass er sich bewährt und ohne Sünde bleibt, dann bleibt er am Leben und auch du hast dein Leben gerettet.\"" },
      { number: 22, text: "Dann legte sich die Hand Jahwes auf mich. Er befahl mir: \"Steh auf und geh in die Ebene hinaus! Dort will ich mit dir reden!\"", heading: "Der Prophet wird stumm" },
      { number: 23, text: "Ich stand auf und ging. Als ich in die Ebene kam, sah ich die Herrlichkeit Jahwes dort stehen, so wie ich sie schon am Fluss Kebar gesehen hatte. Da stürzte ich zu Boden auf mein Gesicht." },
      { number: 24, text: "Aber dann kam der Geist in mich und stellte mich wieder auf die Füße. Jahwe sagte zu mir: \"Geh in dein Haus und schließ dich ein!" },
      { number: 25, text: "Du wirst dort mit Stricken gefesselt sein, so dass du nicht mehr zu ihnen hinausgehen kannst." },
      { number: 26, text: "Ich lasse dir die Zunge am Gaumen kleben und mache dich stumm. Du sollst kein Mahner mehr für sie sein, denn sie sind ein stures Volk." },
      { number: 27, text: "Wenn ich aber mit dir rede, werde ich deine Zunge lösen. Dann sollst du ihnen sagen: 'So spricht der Herr, Jahwe!' Wer es hören will, mag hören, wer es lassen will, mag es lassen! Sie sind ein stures Volk.\"" },
    ] },
    { number: 4, verses: [
      { number: 1, text: "\"Du, Mensch, nimm dir einen Lehmziegel, leg ihn vor dich hin und ritze den Umriss der Stadt Jerusalem darauf ein.", heading: "Die Zeichen für das Ende der Stadt (4-7)\nDas Zeichen der Belagerung" },
      { number: 2, text: "Dann eröffne die Belagerung gegen die Stadt: Baue Belagerungstürme, schütte einen Wall gegen sie auf, richte ein Heerlager ein und stelle Rammböcke gegen ihre Mauern ringsum!" },
      { number: 3, text: "Nimm dir dann eine eiserne Pfanne und stelle sie als eiserne Mauer zwischen dich und die Stadt. Dann blick auf sie hin: Nun ist sie belagert, und du belagerst sie. Das soll ein Zeichen für die Leute von Israel sein.\"" },
      { number: 4, text: "\"Dann legst du dich auf deine linke Seite und nimmst die Schuld der Israeliten auf dich. Solange du so liegst, sollst du ihre Schuld tragen.", heading: "Das Zeichen des Gebundenseins" },
      { number: 5, text: "Ich habe dir nämlich die Jahre ihrer Schuld zu einer Tageszahl gemacht. 390 Tage musst du die Schuld des Hauses Israel* tragen.", footnotes: ["Haus Israel bezieht sich hier auf die zehn Stämme des Nordreiches Israel, von dem die allermeisten Bewohner vor mehr als 100 Jahren nach Assyrien verschleppt worden waren."] },
      { number: 6, text: "Wenn du damit fertig bist, legst du dich auf deine rechte Seite und trägst die Schuld des Hauses Juda, 40 Tage lang*, einen Tag für jedes Jahr. So habe ich es festgesetzt.", footnotes: ["40 Tage lang. 390+40=430 Jahre verbrachte Israel nach 2. Mose 12,40-41 in Ägypten. Ansonsten sind die Zahlen nicht sicher zu deuten."] },
      { number: 7, text: "Dabei sollst du deine Blicke und deinen bloßen Arm auf das belagerte Jerusalem richten und gegen die Stadt weissagen." },
      { number: 8, text: "Pass auf! Ich werde dich mit Stricken fesseln, dass du dich nicht von einer Seite auf die andere wälzen kannst, bis du die Tage deiner Belagerung überstanden hast.\"" },
      { number: 9, text: "\"Nimm dir jetzt Weizen, Gerste, Bohnen, Linsen, Hirse und Dinkel, schütte alles in ein einziges Gefäß und backe daraus Brot. Das ist deine Speise für die 390 Tage, in denen du auf deiner Seite liegst.", heading: "Das Zeichen der unreinen Speise" },
      { number: 10, text: "Deine Tagesration beträgt 260 Gramm* Brot, und du sollst es zu bestimmten Zeiten essen.", footnotes: ["260 Gramm. Wörtlich: 20 Schekel. Ein Schekel in Babylon wog durchschnittlich etwa 13 Gramm."] },
      { number: 11, text: "Auch das Wasser, das du trinkst, soll genau abgemessen sein: drei Becher*.", footnotes: ["drei Becher. Wörtlich: Ein Sechstel Hin, das sind 0,6 Liter."] },
      { number: 12, text: "Das Brot sollst du wie Gerstenfladen backen*. Als Brennmaterial nimm vor aller Augen Menschenkot dazu!", footnotes: ["backen. Brotfladen wurden auf erhitzten Steinen gebacken."] },
      { number: 13, text: "Denn auch die Israeliten werden bei den Völkern, unter die ich sie verstreue, ihr Brot unrein essen müssen.\"" },
      { number: 14, text: "Da sagte ich: \"Ach Herr, Jahwe, von meiner Kindheit an habe ich nichts gegessen, was unrein macht. Nie habe ich Fleisch von verendeten oder gerissenen Tieren gegessen und nie unrein gewordenes Opferfleisch angerührt.\"" },
      { number: 15, text: "Da sagte er zu mir: \"Gut, ich erlaube dir Kuhmist zu nehmen statt Menschenkot.\"" },
      { number: 16, text: "Und er fuhr fort: \"Du Mensch, hör zu! Ich zerstöre Jerusalems Vorrat an Brot*, sodass sie es abwiegen werden und mit Angst essen und das Wasser abmessen und mit Entsetzen trinken.", footnotes: ["Vorrat an Brot. Wörtlich: Ich zerbreche den Stab des Brotes.So auch Hesekiel 5,16; 14,13. In die Mitte der Brotfladen wurde schon vor dem Backen mit dem Finger ein Loch gebohrt, sodass sie anschließend auf einen Stab gesteckt aufbewahrt werden konnten."] },
      { number: 17, text: "Wegen ihrer Schuld werden sie Mangel an Brot und Wasser haben und werden einer nach dem anderen elend zugrunde gehen.\"" },
    ] },
    { number: 5, verses: [
      { number: 1, text: "\"Du, Mensch, nimm dir ein scharfes Schwert und benutze es als Rasiermesser. Schere dir damit den Kopf kahl und rasiere den Bart ab. Dann nimm dir eine Waage und teile die Haare.", heading: "Das Zeichen der geschorenen Haare" },
      { number: 2, text: "Ein Drittel verbrenne in der Stadt, wenn sie gestürmt wird. Das zweite Drittel zerhaue mit dem Schwert vor ihren Toren; und das letzte Drittel streue in den Wind! Denn ich werde ihre Einwohner mit gezücktem Schwert verfolgen." },
      { number: 3, text: "Nur ganz wenige Haare sollst du in den Zipfel deines Mantels binden." },
      { number: 4, text: "Doch auch von diesen sollst du noch einen Teil nehmen, ins Feuer werfen und verbrennen lassen. Davon wird sich das Feuer auf das ganze Haus Israel ausdehnen.\"" },
      { number: 5, text: "So spricht mein Herr Jahwe: \"Das ist Jerusalem! Ich habe die Stadt zum Mittelpunkt der Völker gemacht und Länder rings herum gesetzt.", heading: "Deutung der Zeichen" },
      { number: 6, text: "Doch ihre Bewohner lehnten sich gegen meine Rechtsbestimmungen auf und waren gottloser als die Völker; sie empörten sich gegen meine Ordnungen, schlimmer als die Länder ringsum. Sie missachteten meine Gebote und traten mein Gesetz mit Füßen." },
      { number: 7, text: "Darum, spricht Jahwe, der Herr: Weil ihr mehr getobt habt als die Völker um euch herum, weil ihr meine Gebote nicht beachtet und mein Gesetz verworfen habt, weil ihr euch nicht einmal nach den Gesetzen eurer Nachbarvölker gerichtet habt," },
      { number: 8, text: "darum werde auch ich gegen dich sein, spricht Jahwe, der Herr. Vor den Augen der Völker werde ich mein Strafgericht an euch vollziehen." },
      { number: 9, text: "Wegen der Menge deiner Abscheulichkeiten werde ich dich so bestrafen, wie ich es noch nie getan habe und auch nie wieder tun werde." },
      { number: 10, text: "Mitten in Jerusalem werden Väter ihre Söhne töten und aufessen. Und Söhne werden es mit ihren Vätern genauso tun. Ich vollziehe mein Gericht an dir und zerstreue deinen Rest in alle Winde." },
      { number: 11, text: "Darum, so wahr ich lebe, spricht Jahwe, der Herr: Weil du mein Heiligtum mit all deinen Scheusalen und Gräueln entweiht hast, werde auch ich dich kahl scheren. Mein Auge wird kein Mitleid zeigen, und ich werde dich nicht schonen." },
      { number: 12, text: "Ein Drittel von dir wird in der Stadt an Pest und Hunger sterben, ein Drittel soll vor der Stadt mit dem Schwert erschlagen werden; und ein Drittel zerstreue ich in alle Winde und verfolge sie mit gezücktem Schwert." },
      { number: 13, text: "Sie werden meinen Zorn zu spüren bekommen, und ich werde meine Wut an ihnen stillen und mich rächen. Dann, wenn ich meinen Grimm an ihnen kühle, wird man erkennen, dass ich, Jahwe, sie mit Leidenschaft gewarnt habe." },
      { number: 14, text: "Ja, ich mache dich zum Schauder und zum Schimpf für alle Völker ringsum. Und jeder, der vorbeigeht, wird dich verhöhnen." },
      { number: 15, text: "Zum Gespött und zum Hohn, zur Warnung und zum Schreckbild wirst du für die Völker ringsum sein, wenn ich mein Strafgericht an dir vollziehe, voll von grimmigem Zorn und wütender Züchtigung – ich, Jahwe, habe gesprochen –," },
      { number: 16, text: "wenn ich die bösen Pfeile des Hungers gegen dich abschieße – und ich werde sie abschießen – um euch zu verderben, und wenn ich den Hunger über euch häufe und euren Brotvorrat vernichte." },
      { number: 17, text: "Ja, ich sende Hunger über euch und dazu wilde Tiere, die euch der Kinder berauben; Pest und Blutvergießen, wenn das Schwert über euch kommt.* Ich, Jahwe, habe gesprochen.\"", footnotes: ["Hunger ... kommt. Siehe 3. Mose 26 die vier Heimsuchungen Gottes: Hunger, wilde Tiere, Pest und Schwert. So auch Hesekiel 14,21 und Offenbarung 6,7-8."] },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Gegen die Berge Israels" },
      { number: 2, text: "\"Du Mensch, blick auf die Berge Israels und künde ihnen mein Strafgericht an!" },
      { number: 3, text: "Sag zu ihnen: 'Ihr Berge Israels, hört das Wort Jahwes! So spricht Jahwe, der Herr, zu den Bergen und Hügeln, den Schluchten und Tälern:Seht, ich selbst bringe das Schwert über euch und vernichte eure Opferhöhen!" },
      { number: 4, text: "Eure Altäre sollen zerstört werden, die Räuchertische zerbrochen. Die Leichen der Erschlagenen werde ich euren Mistgötzen* vor die Füße werfen.", footnotes: ["Mistgötzen. Wörtlich: Mistkugeln, eine bewusst verächtliche Bezeichnung für die Götzenbilder."] },
      { number: 5, text: "Und ihre Knochen verstreue ich rings um eure Altäre." },
      { number: 6, text: "Wo ihr auch wohnt, werden die Städte in Trümmern liegen und die Opferhöhen zerstört sein, damit eure Altäre verwüstet und verödet sind, eure Mistgötzen zerschlagen, die Räuchertische zerbrochen und eure Machwerke ausgelöscht sind." },
      { number: 7, text: "Mitten unter euch werden die Durchbohrten liegen. Dann werdet ihr erkennen, dass ich es bin – Jahwe!" },
      { number: 8, text: "Doch einen Rest werde ich am Leben lassen. Einige von euch werden dem Schwert entkommen und zerstreut unter fremden Völkern leben." },
      { number: 9, text: "Dort werden sie dann an mich denken und begreifen, dass ich ihr verhurtes Herz zerbrochen habe und ihre Augen, die lüstern nach den Mistgötzen schielten. Dann werden sie sich ekeln vor sich selbst, wegen all der abscheulichen Dinge, die sie getan haben." },
      { number: 10, text: "Dann wird man erkennen, dass ich, Jahwe, keine leeren Worte machte, als ich ihnen dieses Unheil androhte.'" },
      { number: 11, text: "So spricht Jahwe, der Herr: 'Schlag die Hände zusammen und stampfe mit dem Fuß auf den Boden und schreie:Weh über all die bösen Gräuel des Hauses Israel! Denn sie müssen fallen durch Schwert, Hunger und Pest!" },
      { number: 12, text: "Wer fern ist, wird an der Pest sterben, wer in der Nähe ist, durchs Schwert, und wer dann noch übrig geblieben und mit dem Leben davongekommen ist, wird verhungern!So werde ich meinen Grimm an ihnen auslassen," },
      { number: 13, text: "damit ihr erkennt, dass ich, Jahwe, es bin. Die Erschlagenen werden mitten unter ihren Mistgötzen liegen, rings um ihre Altäre, auf jedem hohen Hügel und Berggipfel, unter jedem grünen Baum und jeder Terebinthe, überall, wo sie ihren Mistgötzen den Opferrauch aufsteigen ließen." },
      { number: 14, text: "Ich strecke meine Hand gegen sie aus und mache ihr Land zur Wildnis und zur Wüste, ihr ganzes Land von der Steppe im Süden bis nach Ribla*. Sie sollen erkennen, dass ich bin, der ich bin – Jahwe!'\"", footnotes: ["Ribla lag am Orontes, etwa 105 km nördlich von Damaskus."] },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Ankündigung des Gerichts" },
      { number: 2, text: "\"Du Mensch! So spricht Jahwe, der Herr, zum Land Israel: 'Das Ende kommt! Über das ganze Land bricht das Ende herein!" },
      { number: 3, text: "Jetzt kommt das Ende über dich! Ich lasse meinen Zorn gegen dich wüten und richte dich für deine Vergehen. Deine Gräueltaten zahle ich dir heim." },
      { number: 4, text: "Mir werden keine Tränen wegen dir kommen, ich werde kein Mitleid mit dir haben, sondern ich bringe deine Vergehen über dich. Du sollst die Folgen deiner Gräuel fühlen! Und ihr sollt erkennen, dass ich, Jahwe, es bin.'" },
      { number: 5, text: "So spricht Jahwe, der Herr: 'Unheil über Unheil, – da, es ist gekommen!" },
      { number: 6, text: "Ein Ende kommt! Es kommt das Ende, es erwacht. Pass auf, es kommt auf dich zu!" },
      { number: 7, text: "Es kommt, es bricht über dich herein, Bewohner des Landes. Es kommt die Zeit, nah ist der Tag: Tumult, und nicht Jubel in den Bergen!" },
      { number: 8, text: "Bald schütte ich meinen Grimm über dich aus und kühle meinen Zorn an dir. Ich richte dich für deine Vergehen. Deine Gräueltaten zahle ich dir heim!" },
      { number: 9, text: "Mir werden keine Tränen wegen dir kommen, ich werde kein Mitleid mit dir haben, sondern ich bringe deine Vergehen über dich. Du sollst die Folgen deiner Gräuel fühlen! Und ihr sollt erkennen, dass ich, Jahwe, einer bin, der schlägt." },
      { number: 10, text: "Seht, da ist der Tag! Da, er kommt! Es bricht über dich herein. Es sprosst der Stab, es blüht der Frevel," },
      { number: 11, text: "die Gewalttat erhebt sich und wird zum Zepter des Bösen. Nichts bleibt von ihnen, von ihrer Menge und ihrem Gepränge, und keine Klage ist um sie." },
      { number: 12, text: "Die Zeit kommt, der Tag ist da! Wer etwas kauft, soll sich nicht freuen, und der Verkäufer soll nicht traurig sein, denn Zornglut kommt über die ganze lärmende Menge." },
      { number: 13, text: "Der Verkäufer wird das Verkaufte auch im Erlassjahr* nicht wiedererlangen, und wenn er noch so lange leben sollte. Denn die Vision richtet sich gegen sie alle und verändert sich nicht. Und weil sie alle schuldig sind, wird keiner sein Leben retten.*", footnotes: ["Erlassjahr. Siehe 3. Mose 25,8-15.", "Der Verkäufer ... retten. Einige Worte der letzten drei Sätze geben im Zusammenhang keinen Sinn, deshalb bleibt die Deutung unsicher."] },
      { number: 14, text: "Man stößt ins Horn und macht alles bereit, doch keiner zieht in den Kampf, denn meine Zornglut kommt über all ihre Menge." },
      { number: 15, text: "Draußen das Schwert, drinnen Hunger und Pest. Wer auf dem Feld ist, stirbt durch das Schwert, wer in der Stadt ist, den fressen Hunger und Pest." },
      { number: 16, text: "Und wenn Versprengte auf die Berge entkommen, werden sie dort wie Tauben in den Schluchten sein: Alle jammern über ihre Schuld." },
      { number: 17, text: "Alle Hände werden schlaff und alle Knie werden weich." },
      { number: 18, text: "Sie ziehen den Trauersack an, und ein Schauder hüllt sie ein. Alle Gesichter sind verstört und alle Köpfe kahl." },
      { number: 19, text: "Ihr Silber und Gold werfen sie wie Unrat auf die Gassen; es kann sie an jenem Tag nicht retten vor dem grimmigen Zorn Jahwes. Sie können damit ihren Bauch nicht füllen, ihren Hunger nicht stillen, denn es war der Anstoß zu ihrer Schuld." },
      { number: 20, text: "Sie waren stolz auf ihren kostbaren Schmuck und haben ihre abscheulichen Götzen und ihre gräulichen Bilder daraus gemacht. Darum habe ich ihn für sie zum Ekel gemacht." },
      { number: 21, text: "Darum gebe ich alles den Fremden zur Beute, den Frevlern der Erde gebe ich es preis, damit sie alles entweihen." },
      { number: 22, text: "Und ich wende mein Gesicht ab und lasse sie auch mein Heiligtum entweihen, dass Räuber eindringen können und es schänden." },
      { number: 23, text: "Fertige die Kette an! Denn das Land ist voll von Mord und Totschlag, und in der Stadt regiert die Gewalt." },
      { number: 24, text: "Ich führe die schlimmsten Völker herbei, dass sie ihre Häuser besetzen. Ich mache dem Hochmut der Mächtigen ein Ende und entweihe alles, was ihnen heilig ist!" },
      { number: 25, text: "Dann bekommen sie Angst und suchen nach Sicherheit, doch es wird sie nicht geben." },
      { number: 26, text: "Ein Unglück folgt dem anderen, und eine Schreckensnachricht jagt die nächste. Nun suchen sie Visionen beim Propheten. Doch auch der Priester verlor das Gesetz, und die Ältesten wissen keinen Rat." },
      { number: 27, text: "Der König wird trauern, der Fürst sich in Entsetzen hüllen, und zittern werden die Hände des Volkes. Ich behandle sie, wie es ihrem Verhalten entspricht, ich richte sie nach ihrem eigenen Recht. Sie sollen erkennen, dass ich, Jahwe, es bin.'\"" },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Es war im 6. Jahr unserer Verbannung, am 5. September.* Ich saß gerade mit den Ältesten von Juda zusammen in meinem Haus, da legte Jahwe, der Herr, seine Hand auf mich.", heading: "Die Herrlichkeit geht verloren (8-11)\nGötzendienst im Tempel Jahwes", footnotes: ["September. Wörtlich: 6. Monat. Im Jahr 592 v.Chr. In Jerusalem regierte König Zidkija (2. Könige 24,18-20)."] },
      { number: 2, text: "Ich blickte auf und sah eine Gestalt, die aussah wie ein Mann. Unterhalb von dem, was wie seine Hüften aussah, war Feuer. Nach oben hin strahlte es wie helles Gold." },
      { number: 3, text: "Sie streckte so etwas wie eine Hand nach mir aus und packte mich bei den Haaren. So hob mich der Geist in einer göttlichen Vision hoch in die Luft und brachte mich nach Jerusalem, an den Eingang des nördlichen Tors zum inneren Vorhof, wo das Götzenbild stand, das Eifersucht erregte*.", footnotes: ["Götzenbild ... erregte. Vermutlich war es eine Statue der kanaanäischen Fruchtbarkeitsgöttin Aschera, die Jahwe zur Eifersucht reizen musste."] },
      { number: 4, text: "Dort sah ich den Gott Israels in seiner Herrlichkeit, so wie ich ihn in der Ebene gesehen hatte." },
      { number: 5, text: "Er sagte zu mir: \"Blick nach Norden, Mensch!\" Ich schaute in diese Richtung und sah nördlich vom Tor, das zum Altar führt, neben dem Eingang das Götzenbild der Eifersucht stehen.", heading: "Das Götzenbild der Eifersucht" },
      { number: 6, text: "\"Siehst du, was sie tun, Mensch?\" sagte er zu mir. \"Widerliche Dinge treiben die Leute von Israel hier, damit ich mich von meinem Heiligtum entferne. Aber du wirst noch schlimmere Abscheulichkeiten sehen.\"" },
      { number: 7, text: "Er brachte mich zum Eingang des Vorhofs. Dort sah ich ein Loch in der Mauer.", heading: "Die Bilderkammer" },
      { number: 8, text: "\"Durchbrich die Wand, Mensch!\", sagte er zu mir. Ich tat es und stieß auf eine Tür." },
      { number: 9, text: "\"Geh hinein\", sagte er, \"und schau dir an, was für schlimme Gräuel sie hier treiben!\"" },
      { number: 10, text: "Ich ging hinein und sah überall an den Wänden die Bilder von Kriechtieren und abscheulichem Viehzeug eingemeißelt, all die Götzen des Hauses Israel." },
      { number: 11, text: "Siebzig Männer von den Ältesten Israels standen davor, und Jaasanja Ben-Schafan war mitten unter ihnen. Alle hatten Räucherpfannen in der Hand, und der Duft einer Weihrauchwolke stieg empor." },
      { number: 12, text: "\"Siehst du, Mensch, was die Ältesten von Israel hier im Finstern tun und jeder in seiner Bilderkammer zu Hause? Sie denken: 'Jahwe sieht es nicht, Jahwe hat das Land verlassen!'" },
      { number: 13, text: "Aber du wirst sehen, dass sie noch schlimmere Abscheulichkeiten begehen.\"" },
      { number: 14, text: "Dann brachte er mich zum Nordtor des inneren Vorhofs im Haus Jahwes. Dort saßen Frauen, die den Tammuz* beweinten.", heading: "Verehrung des Tammuz", footnotes: ["Tammuz war ein babylonischer Vegetationsgott, dessen Tod man alljährlich zur großen Hitze betrauerte, um im Frühling seine Auferstehung zu feiern."] },
      { number: 15, text: "Er sagte zu mir: \"Hast du das gesehen, Mensch? Ich werde dir zeigen, dass sie noch mehr und schlimmere Abscheulichkeiten begehen.\"" },
      { number: 16, text: "Dann brachte er mich in den inneren Vorhof. Vor dem Eingang des Tempelhauses, zwischen dem Brandopferaltar und der Vorhalle, standen etwa 25 Männer mit dem Rücken zum Tempel Jahwes. Sie hatten ihre Gesichter nach Osten gerichtet und warfen sich nieder, um die Sonne anzubeten.", heading: "Verehrung des Sonnengottes" },
      { number: 17, text: "Er sagte zu mir: \"Hast du es gesehen, Mensch? War es dem Haus Juda nicht genug, diese Abscheulichkeiten hier zu verüben? – Sie haben ja schon das Land mit Unrecht erfüllt. – Müssen sie mich immer mehr reizen und mir auch noch die Weinrebe unter die Nase* halten?", heading: "Götzendienst im ganzen Land", footnotes: ["Weinrebe unter die Nase. Vielleicht eine sprichwörtliche abergläubische Redewendung."] },
      { number: 18, text: "Jetzt kenne ich keine Rücksicht mehr. Mein Auge wird kein Mitleid zeigen, und ich werde sie nicht verschonen. Auch wenn sie mir laut in die Ohren schreien, werde ich nicht auf sie hören.\"" },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Dann rief er mit gewaltiger Stimme vor meinen Ohren: \"Kommt herbei, ihr Strafrichter der Stadt! Jeder bringe sein Todeswerkzeug mit!\"", heading: "Das Gericht über Jerusalem" },
      { number: 2, text: "Da kamen sechs Männer durch das nördliche Tempeltor; jeder hatte sein Todeswerkzeug in der Hand. In ihrer Mitte befand sich ein Siebter, der mit Leinen bekleidet war und Schreibzeug am Gürtel hatte. Sie stellten sich neben den Bronzealtar." },
      { number: 3, text: "Die Herrlichkeit des Gottes Israels hatte sich inzwischen von dem Cherub erhoben, über dem sie ruhte, und war an den Eingang vom Tempel getreten. Er rief dem Mann mit dem Schreibzeug am Gürtel zu:" },
      { number: 4, text: "\"Geh mitten durch die Stadt, mitten durch Jerusalem, und mach ein Zeichen auf die Stirn der Männer, die über die Gräueltaten in ihrer Mitte seufzen und stöhnen!\"" },
      { number: 5, text: "Ich hörte auch, wie er zu den anderen sagte: \"Geht hinter ihm her durch die Stadt und schlagt zu! Euer Auge soll kein Mitleid zeigen, ihr dürft sie nicht verschonen!" },
      { number: 6, text: "Erschlagt die Greise und die Jugendlichen, die Kinder und die Frauen! Rührt aber keinen an, der das Kennzeichen hat! Beginnt hier in meinem Heiligtum!\" Da begannen sie bei den Ältesten, die vor dem Tempel standen." },
      { number: 7, text: "Dabei sagte Jahwe zu ihnen: \"Füllt die Vorhöfe mit Erschlagenen und besudelt den Tempel mit ihnen! Dann geht in die Stadt und macht dort weiter!\" Sie taten es." },
      { number: 8, text: "Als sie so die Menschen erschlugen und nur mich verschonten, warf ich mich nieder und schrie: \"Ach Herr, Jahwe, willst du in deinem Zorn über Jerusalem denn den ganzen Rest Israels vernichten?\"" },
      { number: 9, text: "Da sagte er zu mir: \"Die Schuld dieser Leute von Israel und Juda ist entsetzlich groß. Sie haben das ganze Land mit Bluttaten und die Stadt mit Unrecht gefüllt. Sie sagen: 'Jahwe hat das Land ja verlassen, er sieht uns nicht mehr!'" },
      { number: 10, text: "Darum werde auch ich kein Mitleid zeigen und sie nicht verschonen. Nein, ich will ihr Verhalten auf sie selbst zurückfallen lassen!\"" },
      { number: 11, text: "Da kam der Mann, der mit Leinen bekleidet war und Schreibzeug am Gürtel hatte, zurück und meldete: \"Ich habe deinen Befehl ausgeführt.\"" },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Oberhalb der Wölbung, die über den Köpfen der Cherubim war, sah ich so etwas wie einen Thron, der einem Saphir glich.", heading: "Gott verlässt die Stadt" },
      { number: 2, text: "Der, der auf ihm saß, sagte zu dem in Leinen gekleideten Mann: \"Geh zwischen die Räder unter den Cherubim, nimm von dort zwei Hände voll glühender Kohlen und streue sie über die Stadt!\" Der Mann ging vor meinen Augen hinein." },
      { number: 3, text: "Die Cherubim standen rechts vom Tempel, und die Wolke erfüllte den ganzen inneren Vorhof." },
      { number: 4, text: "Da erhob sich die Herrlichkeit Jahwes von dem Cherub und trat an die Schwelle des Tempelhauses. Die Wolke erfüllte das ganze Haus, und der Vorhof leuchtete im Glanz der Herrlichkeit Jahwes." },
      { number: 5, text: "Das Rauschen der Cherubimflügel wurde bis zum äußeren Vorhof gehört. Es klang wie die Stimme des allmächtigen Gottes, wenn er spricht." },
      { number: 6, text: "Als dann der in Leinen gekleidete Mann auf seinen Befehl hin zwischen die Räder unter den Cherubim trat," },
      { number: 7, text: "streckte einer der Cherubim die Hand nach dem Feuer aus, das zwischen ihnen war, und legte die Glut in die Hände des Mannes. Der nahm sie und ging hinaus." },
      { number: 8, text: "Unter den Flügeln der Cherubim war nämlich etwas sichtbar geworden, das wie eine Menschenhand aussah." },
      { number: 9, text: "Ich sah auch vier Räder neben den Cherubim, ein Rad neben jedem Cherub. Die Räder funkelten wie Edelsteine." },
      { number: 10, text: "Alle waren gleich gebaut. Es sah aus, als ob ein Rad mitten im anderen wäre," },
      { number: 11, text: "sodass sie nach allen vier Richtungen laufen konnten, ohne gedreht zu werden. Die Räder rollten immer in die Richtung des vordersten." },
      { number: 12, text: "Jeder Cherub war ganz mit Augen bedeckt: Rücken, Hände, Flügel; auch die Räder," },
      { number: 13, text: "die vor meinen Ohren Galgal* genannt wurden.", footnotes: ["Galgal. Das heißt soviel wie \"wirbelnde Räder\" oder \"Wirbelwind\"."] },
      { number: 14, text: "Jeder hatte vier verschiedene Gesichter. Beim ersten blickte das Cherubgesicht nach vorn, beim zweiten das Menschengesicht, beim dritten das Löwengesicht und beim vierten das Adlergesicht." },
      { number: 15, text: "Dann begannen sich die Cherubim zu erheben. Es war das Lebewesen, das ich am Fluss Kebar gesehen hatte.*", footnotes: ["gesehen hatte. Siehe Hesekiel 1."] },
      { number: 16, text: "Wenn die Cherubim sich fortbewegten, bewegten sich auch die Räder mit ihnen, und wenn sie sich mit ihren Flügeln von der Erde erhoben, erhoben sich auch die Räder." },
      { number: 17, text: "Wenn sie anhielten, blieben auch die Räder stehen. Die Räder hoben sich immer mit ihnen, denn sie wurden vom Geist des Lebewesens bewohnt." },
      { number: 18, text: "Dann verließ die Herrlichkeit Jahwes die Schwelle des Tempelhauses und stellte sich über die Cherubim." },
      { number: 19, text: "Diese breiteten vor meinen Augen ihre Flügel aus, erhoben sich samt den Rädern von der Erde und stellten sich außen an den Eingang des östlichen Tores vom Tempelbezirk. Über ihnen thronte Jahwe in seiner Herrlichkeit." },
      { number: 20, text: "Es war das Lebewesen, das ich unter dem Gott Israels am Fluss Kebar gesehen hatte. Ich erkannte, dass es Cherubim waren." },
      { number: 21, text: "Jeder von ihnen hatte vier Gesichter und vier Flügel und so etwas wie Menschenhände unter den Flügeln." },
      { number: 22, text: "Auch ihre Gesichter waren dieselben, die ich am Fluss Kebar gesehen hatte. Wohin sie auch gingen, in jede Richtung blickte eins ihrer Gesichter." },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Dann nahm mich der Geist und brachte mich zum östlichen Tor des Tempelbezirks. Vor dem Tor standen 25 Männer. Unter ihnen erkannte ich Jaasanja Ben-Assur und Pelatja Ben-Benaja, führende Männer der Stadt.", heading: "Gottes Gericht über die Führer Jerusalems" },
      { number: 2, text: "Jahwe sagte zu mir: \"Du Mensch, das sind die Männer, die in der Stadt Unheil ersinnen und böse Pläne schmieden," },
      { number: 3, text: "die sagen: 'So schnell müssen wir keine Häuser bauen! Die Stadt ist der Topf, und wir sind das Fleisch darin!'*", footnotes: ["... Fleisch darin. Mit dem Sprichwort drücken die zurückgebliebenen Jerusalemer ihre Überlegenheit gegenüber den Weggeführten aus."] },
      { number: 4, text: "Darum tritt als Prophet gegen sie auf, Mensch, und weissage!\"" },
      { number: 5, text: "Da kam der Geist Jahwes über mich. Er sagte zu mir:\"Sag: 'So spricht Jahwe: Ich weiß, wie ihr redet und was eure Pläne sind." },
      { number: 6, text: "Ihr habt viele erschlagen, ihr habt die Straßen der Stadt mit Erschlagenen gefüllt!" },
      { number: 7, text: "Darum spricht Jahwe, der Herr: Die Erschlagenen auf euren Straßen, die ihr hingestreckt habt, die sind das Fleisch im Topf der Stadt. Aber euch werde ich aus ihr vertreiben!" },
      { number: 8, text: "Vor dem Schwert fürchtet ihr euch, durch das Schwert werdet ihr sterben, spricht Jahwe, der Herr." },
      { number: 9, text: "Und ich vertreibe euch aus der Stadt. Ich gebe euch in die Gewalt von Fremden und vollziehe so mein Strafgericht an euch!" },
      { number: 10, text: "Durchs Schwert müsst ihr fallen, an Israels Grenze lasse ich euch hinrichten. Ihr sollt erkennen, dass ich bin, der ich bin – Jahwe!" },
      { number: 11, text: "Ihr bleibt nicht in der Stadt wie das Fleisch im Topf. An der Grenze Israels werde ich euch richten!" },
      { number: 12, text: "Ihr werdet erkennen, dass ich es bin – Jahwe, dessen Ordnungen ihr nicht beachtet und dessen Gebote ihr nicht befolgt habt. Ihr habt ja nach den Gesetzen eurer Nachbarvölker gelebt.'\"" },
      { number: 13, text: "Während ich dies weissagte, starb Pelatja Ben-Benaja. Da warf ich mich nieder, das Gesicht auf dem Boden und rief laut: \"Ach Herr, Jahwe! Willst du auch den Rest Israels vernichten?\"" },
      { number: 14, text: "Da kam das Wort Jahwes zu mir:" },
      { number: 15, text: "\"Du Mensch, von deinen Brüdern sagen die Bewohner Jerusalems, ja von deinen Brüdern und Verwandten und von allen Israeliten, die in die Verbannung geführt wurden: 'Sie sollen bleiben, wo sie sind, weit weg von Jahwe! Das Land gehört jetzt uns!'" },
      { number: 16, text: "Darum sprich: 'So spricht Jahwe, der Herr: Ja, ich habe sie weit weg unter fremde Völker versprengt, doch in den Ländern, wohin sie gekommen sind, bin ich ein wenig zum Heiligtum für sie geworden.'" },
      { number: 17, text: "Darum sprich: 'So spricht Jahwe, der Herr: Ich sammle euch aus den Völkern wieder ein, ich führe euch aus den Ländern, in die ihr zerstreut worden seid, wieder zusammen und gebe euch das Land Israel." },
      { number: 18, text: "Und wenn sie dorthin zurückkehren, werden sie alle seine abscheulichen Götzen beseitigen." },
      { number: 19, text: "Ich werde ihnen ein einiges Herz geben und einen neuen Geist, und ich entferne das versteinerte Herz aus ihrer Brust und gebe ihnen ein Herz aus Fleisch und Blut," },
      { number: 20, text: "damit sie nach meinen Weisungen leben und meine Gebote beachten und befolgen. Sie sollen mein Volk werden, und ich, ich werde ihr Gott sein." },
      { number: 21, text: "Doch jenen, die ihr Herz an ihre Götzen gehängt haben und die ihren Gräueln nachfolgen, lasse ich ihr Tun auf sie selbst zurückfallen', spricht Jahwe, der Herr.\"" },
      { number: 22, text: "Dann schwangen die Cherubim ihre Flügel, und die Räder erhoben sich mit ihnen. Über den Cherubim war die Herrlichkeit des Gottes Israels." },
      { number: 23, text: "So verließ die Herrlichkeit Jahwes die Stadt und stellte sich auf den Berg im Osten Jerusalems." },
      { number: 24, text: "Mich aber nahm der Geist Gottes und brachte mich zu den Verbannten nach Babylonien zurück. Dann verschwand die Vision," },
      { number: 25, text: "und ich berichtete den Verbannten alles, was Jahwe mich hatte sehen lassen." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Das unaufhaltsame Gottesgericht (12-24)\nZeichen für die Verbannung" },
      { number: 2, text: "\"Du Mensch, du lebst mitten unter einem widerspenstigen Volk. Diese Leute haben Augen, sehen aber nicht, sie haben Ohren, hören aber nicht, denn sie sind ein Volk voller Sturheit." },
      { number: 3, text: "Schnüre dir ein Bündel, Mensch, wie es Verbannte mit sich tragen, und zieh damit vor ihren Augen am hellen Tag an einen anderen Ort, als ob du in die Verbannung ziehen würdest. Vielleicht sehen sie es ja, denn sie sind ein stures Volk." },
      { number: 4, text: "Trag dein Bündel wie Verbannungsgepäck vor ihren Augen am hellen Tag hinaus. Und am Abend zieh vor ihren Augen weg, so wie man in die Verbannung zieht." },
      { number: 5, text: "Brich vor ihren Augen ein Loch durch die Wand und zwänge dich dadurch hinaus." },
      { number: 6, text: "Dann nimm dein Bündel auf die Schulter und geh in der Dunkelheit fort. Verhülle dein Gesicht, damit du das Land nicht siehst! Denn ich habe dich zu einem Zeichen für das Haus Israel gemacht.\"" },
      { number: 7, text: "Ich machte es wie befohlen. Ich schnürte ein Bündel, wie es Verbannte mit sich tragen, und trug es am hellen Tag hinaus. Am Abend durchbrach ich mit eigener Hand die Mauer und zwängte mich hinaus. In der Dunkelheit hob ich das Bündel auf die Schulter und ging damit fort." },
      { number: 8, text: "Am Morgen kam das Wort Jahwes zu mir:" },
      { number: 9, text: "\"Du Mensch\", sagte er, \"hat nicht das Volk Israel, dieses sture Volk, zu dir gesagt: 'Was machst du da?'" },
      { number: 10, text: "Sag zu ihnen: 'So spricht Jahwe, der Herr: Dieses Wort wird auf dem Fürsten Jerusalems und auf den Leuten Israels dort lasten.'" },
      { number: 11, text: "Sprich: 'Ich bin ein Zeichen für euch. Was ich getan habe, wird mit ihnen geschehen: In die Verbannung, in die Gefangenschaft werden sie ziehen." },
      { number: 12, text: "Und ihr Fürst wird sein Bündel auf die Schulter nehmen und fortziehen. Sie werden die Mauer durchbrechen, um sich hindurchzuzwängen. Dann wird er sein Gesicht verhüllen, weil er das Land mit eigenen Augen nicht wiedersehen wird.'" },
      { number: 13, text: "Aber ich werfe mein Fangnetz über ihn, damit er sich in meinen Schlingen fängt,* und bringe ihn nach Babylon ins Land der Chaldäer. Aber auch das wird er nicht sehen; und dort wird er sterben.", footnotes: ["Schlingen fängt. Das erfüllte sich am 18. Juli 586 v.Chr., sechs Jahre nach dieser Weissagung, siehe 2. Könige 25,3-7; Jeremia 39,4-7."] },
      { number: 14, text: "Und sein Gefolge und alle seine Truppen werde ich in alle Winde zerstreuen. Mit gezogenem Schwert treibe ich sie auseinander." },
      { number: 15, text: "Dann wird man erkennen, dass ich bin, der ich bin – Jahwe, wenn ich sie in fremde Länder versprenge und unter fremde Völker zerstreue." },
      { number: 16, text: "Nur einige von ihnen lasse ich dem Schwert, dem Hunger und der Pest entkommen, damit sie unter den Völkern von all ihren Gräueltaten erzählen können, damit auch diese erkennen, dass ich bin, der ich bin – Jahwe!\"" },
      { number: 17, text: "Das Wort Jahwes kam zu mir. Er sagte:" },
      { number: 18, text: "\"Du Mensch, iss dein Brot mit Zittern und trink dein Wasser mit Angst und Beben!" },
      { number: 19, text: "Und dann sage deinen Landsleuten: 'So spricht Jahwe, der Herr, von denen, die in Jerusalem und Israel geblieben sind: In Angst werden sie ihr Brot essen und mit Entsetzen ihr Wasser trinken, denn ihr Land wird wegen der Gewalttat seiner Bewohner verwüstet und seines Reichtums beraubt daliegen." },
      { number: 20, text: "Die bewohnten Städte werden verwüstet und das Land zur Einöde. Dann werdet ihr erkennen, dass ich es bin – Jahwe!'\"" },
      { number: 21, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Gegen die Skeptiker" },
      { number: 22, text: "\"Mensch, was habt ihr da für ein Sprichwort im Land Israel? Ihr sagt: 'Die Tage ziehen sich hinaus, die Visionen erfüllen sich nie.'" },
      { number: 23, text: "Darum sag zu ihnen: 'So spricht Jahwe, der Herr: Ich werde diesem Gerede ein Ende machen! Man soll es nicht mehr als Sprichwort in Israel gebrauchen!' Sag zu ihnen: 'Die Tage sind nah gekommen, der Inhalt jeder Vision trifft ein!'" },
      { number: 24, text: "Künftig wird es keine nichtige Vision und keine schmeichlerischen Wahrsagungen in Israel mehr geben." },
      { number: 25, text: "Denn ich, Jahwe, ich rede, und was ich sage, trifft ein! Es lässt nicht lange auf sich warten. Du wirst es erleben, du Haus der Sturheit, dass ich etwas sage und es auch tue, spricht Jahwe, der Herr.\"" },
      { number: 26, text: "Das Wort Jahwes kam zu mir. Er sagte:" },
      { number: 27, text: "\"Du Mensch, das Haus Israel sagt: 'Die Vision, die der hat, erfüllt sich noch lange nicht, er weissagt von einer fernen Zeit.'" },
      { number: 28, text: "Darum sag zu ihnen: 'So spricht Jahwe, der Herr: Keins meiner Worte wird mehr hinausgeschoben werden. Was ich sage, wird auch geschehen, spricht Jahwe, der Herr.'\"" },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Gegen falsche Propheten" },
      { number: 2, text: "\"Weissage, Mensch, gegen die Propheten Israels, die nach eigenem Gutdünken prophezeien: 'Hört das Wort Jahwes!'" },
      { number: 3, text: "So spricht Jahwe, der Herr: 'Weh den Propheten der Schande, die ihren Einfällen folgen und nichts gesehen haben!" },
      { number: 4, text: "Wie Füchse in Trümmern sind deine Propheten, Israel." },
      { number: 5, text: "Ihr seid nicht in die Bresche gesprungen, ihr habt die Mauer um das Haus Israel nicht gesichert, damit es im Kampf besteht an meinem Tag!'" },
      { number: 6, text: "Sie schauen Hirngespinste, verkünden falsche Orakel und sagen: 'So spricht Jahwe!', obwohl Jahwe sie gar nicht gesandt hat. Und dann erwarten sie auch noch, dass er ihr Wort eintreffen lässt." },
      { number: 7, text: "'Habt ihr nicht Trugbilder geschaut und falsche Vorhersagen verkündet, als ihr sagtet: 'So spricht Jahwe!', wo ich doch gar nicht geredet habe?'\"" },
      { number: 8, text: "Darum, so spricht Jahwe, der Herr: \"Weil ihr Trugbilder erzählt und Täuschungen schaut, sollt ihr mich kennenlernen!\", spricht Jahwe, der Herr." },
      { number: 9, text: "\"Ich werde gegen die Propheten vorgehen, die Trugbilder schauen und falsche Orakel verkünden! Sie haben nichts mehr im Kreis meines Volkes zu suchen, sie werden nicht mehr im Verzeichnis Israels geführt und nie mehr ins Land Israel zurückkehren. Dann werdet ihr erkennen, dass ich, Jahwe, der Herr bin." },
      { number: 10, text: "Deshalb, weil sie mein Volk in die Irre führen und sagen: 'Schalom!', obwohl doch kein Frieden ist, und weil sie Lehm daran schmieren, wenn mein Volk eine Wand aus Steinen baut," },
      { number: 11, text: "deshalb sage zu den Lehmstreichern: 'Sie soll fallen! Ein Platzregen kommt, und ich lasse ein Hagelwetter niedergehen und den Sturm wüten.'" },
      { number: 12, text: "Ist die Mauer gefallen, wird man dann nicht über euch spotten: 'Wo ist nur der schöne Lehmstrich geblieben?'" },
      { number: 13, text: "Darum spricht Jahwe, der Herr: 'Ich lasse einen Sturm losbrechen in meinem Grimm, ein Wolkenbruch kommt durch meinen Zorn und ein verheerender Hagelschlag." },
      { number: 14, text: "Ich selbst breche die Mauer ab, die ihr mit Lehm verschmiert habt. Ich lasse sie einstürzen, sodass ihr Grund bloßgelegt ist und ihr unter ihren Trümmern begraben seid. Dann werdet ihr erkennen, dass ich es bin – Jahwe," },
      { number: 15, text: "wenn ich meinen Grimm an der Mauer auslasse und an denen, die sie mit Lehm verschmieren. Dann werde ich zu euch sagen: 'Die Mauer ist hin und die Lehmstreicher sind es auch'," },
      { number: 16, text: "die Propheten Israels, die über Jerusalem weissagten und Friedensvisionen hatten, obwohl doch kein Friede da ist, spricht Jahwe, der Herr.\"" },
      { number: 17, text: "\"Du Mensch, wende dich gegen die Frauen deines Volkes, die nach ihrem Gutdünken weissagen, und weissage Folgendes gegen sie:", heading: "Gegen falsche Prophetinnen" },
      { number: 18, text: "'So spricht Jahwe, der Herr: Weh den Frauen, die Bannbänder für Handgelenke nähen und Zauberschleier jeder Größe, um Menschen zu fangen. Ja, Menschenleben wollt ihr fangen in meinem Volk und euer eigenes Leben retten." },
      { number: 19, text: "Für ein paar Hände voll Gerste und einige Bissen Brot entweiht ihr mich bei meinem Volk, indem ihr Menschen, die nicht sterben sollten, dem Tod ausliefert und Menschen am Leben erhaltet, die nicht weiterleben sollten, und indem ihr mein Volk, das so gern auf Lügen hört, anlügt.'" },
      { number: 20, text: "Darum spricht Jahwe, der Herr: 'Ich werde gegen eure Bannbänder vorgehen, mit denen ihr Seelen wie Vögel fangt, und werde sie euch von den Armen reißen. Ich lasse die Seelen los, die ihr fangt, dass sie wegfliegen können." },
      { number: 21, text: "Ich zerfetze eure Zauberschleier und befreie mein Volk aus eurer Gewalt, dass es nicht mehr eure Jagdbeute wird. Ihr sollt erkennen, dass ich bin, der ich bin – Jahwe!" },
      { number: 22, text: "Weil ihr das Herz des Gerechten, den ich selber nicht krank machen wollte, mit Lügen verzagt macht, und weil ihr den Gottlosen unter euch ermutigt, damit er sein böses Treiben nicht aufgibt und so sein Leben rettet," },
      { number: 23, text: "deshalb werdet ihr keine Hirngespinste mehr schauen und nicht länger Wahrsagerei treiben! Ich werde mein Volk aus eurer Gewalt befreien, und ihr werdet erkennen, dass ich bin, der ich bin – Jahwe!'\"" },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Einige von den Ältesten Israels kamen zu mir und setzten sich vor mich hin.", heading: "Gegen die Götzendiener" },
      { number: 2, text: "Da kam das Wort Jahwes zu mir. Er sagte:" },
      { number: 3, text: "\"Du Mensch, diese Männer haben ihre Götzen ins Herz geschlossen, sie haben sich den Stolperstein für ihre Schuld gerade vor Augen gestellt. Soll ich mich da etwa von ihnen befragen lassen?" },
      { number: 4, text: "Darum antworte ihnen:'So spricht Jahwe, der Herr: Jeder von Israel, der sein Herz den Götzen öffnet, der sich den Stolperstein für seine Schuld gerade vor Augen stellt und dann zum Propheten kommt, der wird die Antwort von mir selbst erhalten, die er gemäß der Menge seiner Götzen verdient." },
      { number: 5, text: "Damit werde ich Israel am Herzen packen, weil sie sich von mir abgewandt haben wegen ihrer Götzen.'" },
      { number: 6, text: "Darum sage den Israeliten: 'So spricht Jahwe, der Herr: Kehrt um! Kehrt euch von euren Götzen ab, wendet das Gesicht von diesen Gräueln weg!'" },
      { number: 7, text: "Denn jeder Israelit und auch jeder Fremde in Israel, der sich von mir trennt und seine Götzen im Herzen hochkommen lässt, der sich den Stolperstein für seine Schuld gerade vor Augen stellt und dann zum Propheten kommt, um mich für sich zu befragen, der wird die Antwort von mir selbst, von Jahwe, erhalten." },
      { number: 8, text: "Ich gehe gegen solch einen Menschen vor, damit er allen zur Warnung dient. Sein Unglück wird sprichwörtlich sein, denn ich rotte ihn aus meinem Volk aus. So werdet ihr erkennen, dass ich bin, der ich bin – Jahwe!" },
      { number: 9, text: "Und wenn der Prophet sich verleiten lässt und ihm doch eine Weisung erteilt, dann habe ich, Jahwe, diesen Propheten verleitet. Ich werde meine Hand gegen ihn erheben und ihn aus meinem Volk Israel verstoßen und vernichten." },
      { number: 10, text: "Alle beide müssen die Folgen ihrer Schuld tragen: der Fragende und der Prophet, der ihm antwortet." },
      { number: 11, text: "So soll das Volk Israel gewarnt sein, damit es nicht mehr von mir wegläuft und sich nicht mehr durch seine Verfehlungen besudelt. Dann werden sie mein Volk sein und ich, ich werde ihr Gott sein, spricht Jahwe, der Herr.\"" },
      { number: 12, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Das unerbittliche Gericht Gottes" },
      { number: 13, text: "\"Du Mensch, wenn ein Land sich gegen mich versündigt und mir die Treue bricht, und wenn ich dann seinen Brotvorrat vernichte und den Hunger ins Land schicke, an dem Mensch und Tier zugrunde gehen," },
      { number: 14, text: "und wenn dann Noah, Daniel und Hiob unter ihnen wären, dann würden diese drei Männer wegen ihrer Rechtschaffenheit nur ihr eigenes Leben retten, spricht Jahwe, der Herr." },
      { number: 15, text: "Oder wenn ich Raubtiere gegen das Land losließe, sodass es entvölkert und öde wird, weil wegen der Tiere niemand mehr durchreisen könnte," },
      { number: 16, text: "und dann diese drei Männer unter ihnen wären – so wahr ich lebe, spricht Jahwe, der Herr –, sie könnten nicht einmal ihre Söhne und Töchter retten, sondern allein sich selbst. Und das ganze Land würde entvölkert." },
      { number: 17, text: "Oder wenn ich das Schwert über dieses Land bringen und ihm befehlen würde, Mensch und Tier darin auszurotten," },
      { number: 18, text: "und dann diese drei Männer unter ihnen wären – so wahr ich lebe, spricht Jahwe, der Herr –, sie könnten nicht einmal ihre Söhne und Töchter retten, sondern allein sich selbst." },
      { number: 19, text: "Oder wenn ich die Pest in jenes Land schicke und meinen Grimm als Blutregen darüber ausgieße, um Mensch und Tier darin auszurotten," },
      { number: 20, text: "und Noah, Daniel und Hiob wären unter ihnen – so wahr ich lebe, spricht Jahwe, der Herr –, sie könnten nicht einmal ihre Söhne und Töchter retten. Nur ihr eigenes Leben könnten sie wegen ihrer Gerechtigkeit retten." },
      { number: 21, text: "Und nun sage ich, Jahwe, der Herr: 'Ja, ich werde meine vier Geißeln – Schwert und Hunger, Raubtiere und Pest – auf Jerusalem loslassen, um Mensch und Tier darin zu vernichten!" },
      { number: 22, text: "Doch einige lasse ich in der Stadt übrig, Männer und Frauen. Sie werden weggeführt und kommen zu euch. Dann werdet ihr sehen, was das für Leute sind und wie schlimm sie es treiben. Das wird euch trösten, wenn ihr an das Unheil denkt, das ich über Jerusalem habe kommen lassen und überhaupt alles, was ich über die Stadt gebracht habe." },
      { number: 23, text: "Ja, das wird euch Trost verschaffen, wenn ihr seht, wie schlimm sie es treiben. Dann werdet ihr erkennen, dass ich das alles nicht ohne Ursache getan habe, spricht Jahwe, der Herr.'\"" },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Jerusalem – nutzloses Rebholz" },
      { number: 2, text: "\"Du Mensch, / was hat das Holz der Rebe dem Unterholz voraus, / das zwischen den Waldbäumen wächst?" },
      { number: 3, text: "Fängt man etwas damit an? / Nimmt man es als Pflock / und hängt ein Gerät daran auf?" },
      { number: 4, text: "Nein, es ist für das Feuer bestimmt! / Seine Enden hat das Feuer gefressen / und seine Mitte ist schon versengt. / Taugt es noch zu einer Arbeit?" },
      { number: 5, text: "Schon als es noch heil war, / konnte man nichts daraus machen. / Wie viel weniger jetzt, / wo es vom Feuer angefressen ist. / Wozu soll man es denn noch gebrauchen?" },
      { number: 6, text: "Darum spricht Jahwe, der Herr: / Wie ich das Holz des Weinstocks, / das doch nicht besser als Unterholz ist, / dem Feuer zum Fraß vorwarf, / so gebe ich die Bewohner Jerusalems hin." },
      { number: 7, text: "Ich wende mein Gesicht gegen sie. / Das Feuer wird sie fressen, / auch wenn sie ihm schon entkommen sind. / Und wenn ich das tue, / erkennt ihr, / dass ich, Jahwe, / gegen sie bin." },
      { number: 8, text: "Zur Wüste mache ich ihr Land, / denn sie haben mir die Treue gebrochen\", / spricht Jahwe, der Herr." },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Jerusalem – die treulose Frau" },
      { number: 2, text: "\"Du Mensch, halte der Stadt Jerusalem ihre Gräueltaten vor" },
      { number: 3, text: "und sage:'So spricht Jahwe, der Herr, zu Jerusalem: Du stammst aus dem Land der Kanaaniter. Ein Amoriter* war dein Vater, eine Hetiterin* deine Mutter.", footnotes: ["Amoriter kann sowohl für einen einzelnen Stamm als auch für alle Bewohner Kanaans stehen. Es waren semitische Einwanderer aus der Arabischen Wüste, die um 2000 v.Chr. ins Kulturland eindrangen.", "Die Hetiter waren eine kleinasiatische Völkergruppe, die weder in Sprache noch in Herkunft eine erkennbare Einheit bildeten."] },
      { number: 4, text: "Und so erging es dir bei deiner Geburt: Man schnitt dir nicht die Nabelschnur ab, man hat dich nicht gebadet und mit Salz eingerieben und dich nicht in Windeln eingepackt." },
      { number: 5, text: "Niemand hatte Mitleid mit dir, niemand hat dich entsprechend versorgt. Man warf dich hinaus aufs freie Feld – so verabscheut warst du bei deiner Geburt." },
      { number: 6, text: "Da kam ich vorbei und sah dich zappeln in deinem Blut. Als du so dalagst, sagte ich zu dir: Du sollst leben! Ja, zu dir in deinem Blut sagte ich: Du sollst leben" },
      { number: 7, text: "und wachsen wie eine Blume auf dem freien Feld. So blühtest du auf und wurdest zu einer höchst anmutigen Frau. Deine Brüste wölbten sich, das Schamhaar sprosste, aber du warst nackt und bloß." },
      { number: 8, text: "Als ich wieder vorbeikam, sah ich, dass die Zeit der Liebe für dich gekommen war. Da breitete ich meinen Mantel über dir aus und bedeckte deine Blöße. Ich schwor dir Treue und schloss den Bund der Ehe mit dir. So wurdest du mein." },
      { number: 9, text: "Ich badete dich und wusch dein Blut von dir ab. Dann salbte ich dich mit Öl" },
      { number: 10, text: "und zog dir ein bunt gewirktes Kleid an. Ich gab dir Sandalen aus Tachasch-Leder*, band dir ein Kopftuch aus allerfeinstem Leinen um und hüllte dich in Seide ein.", footnotes: ["Tachasch-Leder. Weichgegerbtes Leder aus Tümmler- oder Dachshäuten."] },
      { number: 11, text: "Dann legte ich dir Schmuck an: Spangen für das Handgelenk, eine Kette um den Hals," },
      { number: 12, text: "einen Ring an deine Nase und auch Ringe für die Ohren, dazu einen kostbaren Reif an die Stirn." },
      { number: 13, text: "So warst du mit Gold und Silber geschmückt, trugst Kleider aus feinstem Leinen, Seide und bunt gewebten Stoffen. Du hattest Gebäck aus feinem Mehl mit Honig und Öl. Und du warst überaus schön, tauglich zu einer Königin." },
      { number: 14, text: "Der Ruf deiner Schönheit, die durch meinen Schmuck vollkommen wurde, ging durch alle Welt', spricht Jahwe, der Herr." },
      { number: 15, text: "'Aber du hast auf deine Schönheit vertraut, hast deinen Ruhm missbraucht und dich zur Hure gemacht. Jeden, der vorüberkam, locktest du mit deinen Reizen, jedem botest du dich an." },
      { number: 16, text: "Auf den Höhen, wo man Götzen verehrt, hast du deine bunten Kleider ausgebreitet und hurtest herum, wie es niemals vorgekommen ist und auch nie wieder geschehen wird." },
      { number: 17, text: "Dann nahmst du mein Geschenk, den prächtigen Schmuck aus Gold und Silber, und machtest Männerbilder daraus und hurtest mit ihnen." },
      { number: 18, text: "Du hülltest sie in deine bunten Kleider ein und botest ihnen mein Öl und meinen Weihrauch an." },
      { number: 19, text: "Und das Gebäck aus feinem Mehl mit Honig und Öl, das ich dir gegeben hatte, brachtest du zu ihnen, um sie zu erfreuen. So weit kam es', spricht Jahwe, der Herr." },
      { number: 20, text: "'Dann nahmst du sogar deine Söhne und Töchter, die du mir geboren hattest, und hast sie geschlachtet, ihnen zum Fraß." },
      { number: 21, text: "War es nicht genug mit deiner Hurerei, dass du auch noch meine Söhne schlachten und als Opfer für deine Götzen verbrennen musstest?" },
      { number: 22, text: "Und bei all deinen Gräueltaten und deiner Prostitution hast du nicht an deine Jugendzeit gedacht, als du nackt und zappelnd in deinem Blut dalagst." },
      { number: 23, text: "Und nach all deiner Bosheit – wehe, wehe dir, spricht Jahwe, der Herr –" },
      { number: 24, text: "hast du dir auf jedem freien Platz ein Hurenlager aufgeschlagen und eine Stätte für den Götzendienst errichtet." },
      { number: 25, text: "An jeder Straßenecke hast du so eine Stätte gebaut. Du hast deine Schönheit schändlich missbraucht und deine Beine für jeden gespreizt, der vorüberkam. Deine sexuelle Unmoral wurde immer größer." },
      { number: 26, text: "Du hurtest mit deinen Nachbarn, den Ägyptern mit dem großen Glied, du tatest es, um mich zu kränken." },
      { number: 27, text: "Da strafte ich dich und nahm dir einen Teil von dem, was ich dir gab. Ich lieferte dich der Gier der Philisterinnen aus, die dich hassten und sich für deine Unmoral schämten." },
      { number: 28, text: "Doch du hattest immer noch nicht genug und triebst es mit den Assyrern, und auch das reichte dir noch nicht." },
      { number: 29, text: "Dann liefst du den chaldäischen Krämern nach, und auch da bekamst du nicht genug." },
      { number: 30, text: "Du branntest darauf, dich hinzugeben, triebst es schlimmer als jede Prostituierte', spricht Jahwe, der Herr." },
      { number: 31, text: "'An jeder Straßenecke hast du dein Hurenlager aufgeschlagen, deine Stätte für den Götzendienst auf jedem freien Platz errichtet. Dabei hast du noch nicht einmal Geld für Sex verlangt." },
      { number: 32, text: "Fremde Männer hast du statt deines Ehemanns genommen." },
      { number: 33, text: "Alle Huren bezahlt man, doch du hast deine Liebhaber mit Geschenken gelockt, damit sie von überall herkamen, um es mit dir zu treiben." },
      { number: 34, text: "So machtest du das Gegenteil von dem, was andere Prostituierte tun. Anderen läuft man nach und gibt ihnen Geld, doch du bezahltest noch für deinen Liebesdienst. So sehr schlugst du aus der Art.'" },
      { number: 35, text: "Darum, du Hure, vernimm das Wort Jahwes!" },
      { number: 36, text: "So spricht Jahwe, der Herr:'Weil du deinen Wert verschleudert hast, weil du dich vor deinen Liebhabern und deinen abscheulichen Götzen nackt ausgezogen und weil du ihnen deine Kinder geopfert hast," },
      { number: 37, text: "darum rufe ich jetzt deine Liebhaber zusammen, die, denen du gefielst, und auch die, die du verabscheut hast.' Wenn sie von überall her zusammengelaufen sind, decke ich deine Scham vor ihnen auf, dass alle deine Blöße sehen." },
      { number: 38, text: "Dann richte ich dich, wie es das Gesetz für eine Ehebrecherin und Mörderin vorschreibt, und ich lasse mit Grimm und Eifer das Blutgericht an dir vollstrecken." },
      { number: 39, text: "Ich liefere dich ihnen aus, dass sie dein Hurenlager einreißen und deine Höhen für den Götzendienst zerstören, dir deinen Schmuck nehmen, die Kleider vom Leib reißen und dich nackt und bloß liegenlassen." },
      { number: 40, text: "Sie werden eine Volksversammlung gegen dich einberufen, dich zu Tode steinigen und mit ihren Schwertern zerstückeln." },
      { number: 41, text: "Vor den Augen vieler Frauen werden deine Häuser niedergebrannt. Sie sehen, wie man das Urteil an dir vollstreckt. Dann ist es aus mit deiner Hurerei, und du wirst keinem mehr den Hurenlohn bezahlen." },
      { number: 42, text: "Und wenn ich meinen Zorn an dir gestillt habe, wird meine Eifersucht aufhören, gegen dich zu wüten. Ich werde Ruhe finden und dir nicht mehr grollen." },
      { number: 43, text: "Weil du deine Jugendzeit vergessen und mich mit all dem gereizt hast, habe auch ich dich die Folgen tragen lassen, spricht Jahwe, der Herr, damit du nach all deinen Gräueln nicht noch weitere Schandtaten verübst." },
      { number: 44, text: "'Wie die Mutter, so die Tochter!', wird jeder sagen, der ein Sprichwort zitiert." },
      { number: 45, text: "Ja, du bist eine echte Tochter deiner Mutter, die ihren Mann und ihre Söhne verabscheute. Du bist auch eine echte Schwester deiner Schwestern, die sich nicht um Mann und Kinder scherten. Deine Mutter war eine Hetiterin, dein Vater ein Amoriter." },
      { number: 46, text: "Deine größere Schwester ist Samaria im Norden mit ihren Tochterstädten, und deine kleinere ist Sodom im Süden mit ihren Tochterstädten." },
      { number: 47, text: "Du bist nicht nur ihrem Beispiel gefolgt, hast nicht nur ihre Schändlichkeiten nachgemacht, sondern sie in kurzer Zeit noch übertroffen." },
      { number: 48, text: "So wahr ich lebe, spricht Jahwe, der Herr: Deine Schwester Sodom und ihre Töchter haben es nicht so schlimm getrieben wie du und deine Töchter!" },
      { number: 49, text: "Deine Schwester Sodom war eingebildet. Sie lebte mit ihren Töchtern in sorgloser Ruhe und im Überfluss. Arme und Elende kümmerten sie nicht." },
      { number: 50, text: "Sie waren stolz und taten abscheuliche Dinge. Als ich das sah, schaffte ich sie weg." },
      { number: 51, text: "Samaria hat nicht halb so viele Abscheulichkeiten begangen wie du. Du hast viel mehr gesündigt als sie. Du hast es so schlimm getrieben, dass deine Schwestern neben dir geradezu gerecht erscheinen." },
      { number: 52, text: "So trage auch du deine Schande, weil du deine Schwestern entlastet hast durch noch abscheulichere Sünden! Nur deshalb erscheinen sie gerechter als du. Darum schäme auch du dich und trage deine Schande, weil du so deine Schwestern gerecht erscheinen lässt!" },
      { number: 53, text: "Einst werde ich ihr Schicksal wenden, das Schicksal Sodoms und Samarias und ihrer Töchter. Und auch deine Gefangenschaft werde ich wenden," },
      { number: 54, text: "damit du deine Schande trägst und dich schämst für das, was du tatest, und weil du sie damit entlastet hast." },
      { number: 55, text: "Deine Schwestern Sodom und Samaria und auch du, ihr werdet samt euren Tochterstädten wieder sein wie früher." },
      { number: 56, text: "In deinem Hochmut hast du über Sodom die Nase gerümpft." },
      { number: 57, text: "Das war, bevor deine eigene Bosheit aufgedeckt wurde. Und so verhöhnen dich jetzt all deine Nachbarinnen, die Edomiterinnen und die Philisterinnen." },
      { number: 58, text: "Du musst nun die Folgen deiner Gräuel und Schandtaten tragen', spricht Jahwe." },
      { number: 59, text: "Denn so spricht Jahwe, der Herr: 'Ich werde mit dir tun, was du getan hast. Du hast den Eid missachtet und den Bund gebrochen." },
      { number: 60, text: "Aber ich will an meinen Bund mit dir denken, der seit deiner Jugendzeit gilt, und will einen ewigen Bund mit dir schließen." },
      { number: 61, text: "Dann wirst du dich an dein Verhalten erinnern und dich schämen, dann, wenn du deine Schwestern zu dir nimmst, die älteren und die jüngeren, und ich sie dir als Töchter gebe. Doch das geht nicht von deinem Bund aus." },
      { number: 62, text: "Ich selbst werde meinen Bund mit dir schließen. Dann wirst du erkennen, dass ich, Jahwe, es bin." },
      { number: 63, text: "Dann sollst du dich erinnern, sollst dich schämen und nicht mehr wagen, den Mund aufzutun, weil ich dir alles vergebe, was du getan hast, spricht Jahwe, der Herr.'\"" },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Der Adler und die Zeder" },
      { number: 2, text: "\"Du Mensch, gib dem Haus Israel ein Rätsel auf, erzähle ihm ein Gleichnis." },
      { number: 3, text: "Sag zu ihnen:'So spricht Jahwe, der Herr: Ein großer Adler mit riesigen Flügeln, weiten Schwingen und dichten, bunten Federn kam in den Libanon und brach den Wipfel einer Zeder ab." },
      { number: 4, text: "Den obersten Zweig riss er ab und brachte ihn ins Land der Händler, in eine Stadt der Kaufleute." },
      { number: 5, text: "Dann nahm er einen Steckling aus dem Boden des Landes und pflanzte ihn in ein gut bewässertes Feld." },
      { number: 6, text: "Er sollte wachsen und zu einem üppig wuchernden Weinstock von niedrigem Wuchs werden. Seine Ranken sollten sich zum Adler hin wenden und seine Wurzeln unter ihm bleiben. Tatsächlich wurde ein Weinstock daraus, er bildete Triebe und entfaltete seine Ranken." },
      { number: 7, text: "Da kam ein anderer Adler mit großen Flügeln und dichtem Gefieder. Auf einmal drehte der Weinstock seine Wurzeln zu ihm hin und streckte ihm seine Ranken entgegen. Er sollte ihn tränken, besser als das Feld, in das er gepflanzt war." },
      { number: 8, text: "Dabei war er doch in einen guten Boden mit reichlich Wasser gepflanzt worden. Er hatte alles, was er brauchte, um Ranken zu treiben und Frucht zu bringen, um zu einem prächtigen Weinstock zu werden.'" },
      { number: 9, text: "Sage: 'So spricht Jahwe, der Herr: Wird er jetzt noch gedeihen? Wird nicht der erste Adler an den Wurzeln zerren und ihre Frucht abknicken, dass sie vertrocknet und alle grünen Triebe verdorren? Dann braucht man nicht mehr viel Kraft und viele Menschen, um ihn mit den Wurzeln herauszureißen." },
      { number: 10, text: "Nun ist er verpflanzt, doch wird er gedeihen? Wird er nicht vertrocknen, sobald der heiße Ostwind ihn berührt, wird er nicht auf seinem Feld völlig verdorren?'\"" },
      { number: 11, text: "Das Wort Jahwes kam zu mir. Er sagte:" },
      { number: 12, text: "\"Sag doch zu diesem sturen Volk: 'Merkt ihr denn nicht, was das Gleichnis bedeutet?' Sage: 'Passt auf! Der König von Babylon kam nach Jerusalem und nahm dessen König und seine führenden Männer mit nach Babylon." },
      { number: 13, text: "An seine Stelle setzte er einen anderen Spross der Königsfamilie, schloss einen Vertrag mit ihm und ließ ihn Treue schwören. Die führenden Männer des Landes jedoch nahm er gefangen," },
      { number: 14, text: "damit das Königreich schwach bliebe und nicht aufbegehrte, damit es den Bund hielte und bestehen bliebe.*", footnotes: ["Vergleiche 2. Könige 24,8-17 zu den Versen 13-14."] },
      { number: 15, text: "Doch der König brach den Vertrag und schickte Gesandte nach Ägypten, um von dort Pferde und Soldaten zu bekommen. Wird das gut gehen? Wird der, der das getan hat, davonkommen? Wird der, der den Vertrag gebrochen hat, seiner Strafe entgehen?" },
      { number: 16, text: "So wahr ich lebe, spricht Jahwe, der Herr: Er wird in Babylon sterben, der Stadt des Königs, der ihn eingesetzt hat, des Königs, dessen Vertrag er brach und dessen Schwur er verachtete!" },
      { number: 17, text: "Und der Pharao wird ihm nicht mit einem großen Heer beistehen, wenn man einen Wall um die Stadt aufschüttet und Belagerungstürme baut und viele Menschen den Tod finden." },
      { number: 18, text: "Hat er doch den Eid verachtet und den Vertrag gebrochen. Er hatte sich mit Handschlag verpflichtet und dennoch all dieses getan. Er wird nicht entkommen!" },
      { number: 19, text: "Darum spricht Jahwe, der Herr: So wahr ich lebe, das wird er mir büßen! Denn er hat meinen Eid verachtet und meinen Vertrag gebrochen!" },
      { number: 20, text: "Ich spanne mein Netz über ihn aus und fange ihn in meinem Garn. Ich bringe ihn nach Babylon und stelle ihn dort vor mein Gericht, denn mir ist er untreu geworden!" },
      { number: 21, text: "Seine Soldaten versuchen zu fliehen und werden mit dem Schwert niedergemacht. Der Rest wird in alle Winde zerstreut. Dann werdet ihr erkennen, dass ich, Jahwe, geredet habe.'*", footnotes: ["Vergleiche 2. Könige 24,18 – 25,21 zu den Versen 15-21. Hesekiël beschreibt die Rebellion Zidkijas, die 588 v.Chr. begann und 586 v.Chr. zum Ende des Staates Juda führte. Wenn er sein Buch in chronologischer Ordnung abfasste, dann empfing er diese Botschaft drei Jahre vor dem Eintreten der Ereignisse, zwischen 592 (8,1) und 591 v.Chr. (20,1)."] },
      { number: 22, text: "So spricht Jahwe, der Herr: 'Ich selbst nehme einen zarten Trieb vom Wipfel der Zeder und pflanze ihn auf einem hoch aufragenden Berg ein." },
      { number: 23, text: "Auf dem hohen Berg Israels* werde ich ihn einpflanzen. Dort wird er Zweige treiben und Frucht tragen und zu einer herrlichen Zeder werden. In ihren Zweigen werden alle Arten von Vögeln wohnen, ja alles, was Flügel hat, wohnt im Schatten ihrer Zweige.", footnotes: ["Berg Israels. Gemeint ist offenbar der Tempelberg, siehe Hesekiel 20,40."] },
      { number: 24, text: "Dann werden alle Bäume auf dem Feld erkennen, dass ich, Jahwe, es bin, der den hohen Baum erniedrigt und den niedrigen Baum erhöht, der den grünen Baum vertrocknen lässt und den dürren Baum zum Blühen bringt. Ich, Jahwe, sage das, und ich tue es auch.'\"" },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Grundsätze der Gerechtigkeit Gottes" },
      { number: 2, text: "\"Wie kommt ihr dazu, dieses Sprichwort im Land Israel zu gebrauchen? Ihr sagt: 'Die Väter essen saure Trauben, und die Söhne bekommen die stumpfen Zähne.'\"" },
      { number: 3, text: "\"So wahr ich lebe, spricht Jahwe, der Herr:Diesen Spruch soll keiner von euch mehr benutzen!" },
      { number: 4, text: "Seht, alle Menschen gehören doch mir. Mir gehört das Leben des Vaters und das Leben des Sohnes. Nur wer sündigt, muss sterben!" },
      { number: 5, text: "Wenn jemand das Rechte tut und lebt, wie es mir gefällt," },
      { number: 6, text: "wenn er nicht von den Opfern auf den Bergen isst, nicht zu den Götzen des Hauses Israel aufschaut, wenn er die Frau seines Nächsten nicht berührt und auch nicht seine eigene Frau, wenn sie ihre Tage hat," },
      { number: 7, text: "wenn er niemand unterdrückt und dem Schuldner sein Pfand wiedergibt*, wenn er sein Brot mit dem Hungernden teilt und den Nackten mit Kleidung versorgt,", footnotes: ["Pfand wiedergibt. Siehe 5. Mose 24,10-13."] },
      { number: 8, text: "wenn er keinen Wucherzins nimmt und sich nicht an Unrecht beteiligt und im Gericht ein unparteiisches Urteil fällt," },
      { number: 9, text: "wenn er sich an meine Ordnungen hält und treu tut, was recht vor mir ist – der ist gerecht. Er soll am Leben bleiben, spricht Jahwe, der Herr." },
      { number: 10, text: "Hat er aber einen Sohn, der gewalttätig wird, der Blut vergießt oder sonst etwas von dem Genannten tut," },
      { number: 11, text: "was sein Vater vermieden hat, wenn er sogar von den Opfern auf den Bergen isst und mit anderen Frauen schläft," },
      { number: 12, text: "wenn er Schutzlose unterdrückt, andere beraubt und dem Schuldner das Pfand nicht zurückgibt, wenn er Abscheuliches tut und sich mit Götzen einlässt," },
      { number: 13, text: "oder wenn er Wucherzins nimmt, sollte er am Leben bleiben? Nein! Wer solch abscheuliche Dinge tut, der muss getötet werden. Und er ist selbst an seinem Tod schuld." },
      { number: 14, text: "Aber vielleicht hat er auch einen Sohn, der die Sünden seines Vaters sieht, aber nichts dergleichen tut." },
      { number: 15, text: "Er isst nicht von den Opfern auf den Bergen und schaut nicht zu den Götzen des Hauses Israel auf, er schläft nicht mit einer anderen Frau" },
      { number: 16, text: "und beutet niemand aus, er fordert kein Pfand und begeht keinen Raub, er gibt dem Hungernden von seinem Brot und versorgt den Nackten mit Kleidung," },
      { number: 17, text: "er vergreift sich nicht an Schutzlosen und nimmt keinen Wucherzins, er hält sich an meine Ordnungen und tut, was recht vor mir ist: Er muss nicht für die Schuld seines Vaters sterben. Er soll am Leben bleiben." },
      { number: 18, text: "Nur sein Vater, der andere in seinem Volk erpresst und beraubt hat und tat, was nicht gut war, muss wegen seiner Schuld sterben." },
      { number: 19, text: "Doch ihr fragt: 'Warum wird der Sohn nicht mit dem Vater bestraft?' – Weil er getan hat, was gut und richtig ist, und alle meine Gebote befolgte, darum wird er auf jeden Fall am Leben bleiben!" },
      { number: 20, text: "Nur wer sündigt, muss sterben. Der Sohn soll nicht die Schuld des Vaters tragen und der Vater nicht die des Sohnes. Die Gerechtigkeit kommt nur dem zugute, der recht vor Gott lebt, und die Schuld lastet nur auf dem Schuldigen." },
      { number: 21, text: "Wenn der Gottlose umkehrt und das Sündigen lässt, sich an meine Ordnungen hält und tut, was gut und richtig ist, dann soll er am Leben bleiben und muss nicht sterben." },
      { number: 22, text: "Keine von allen Sünden, die er begangen hat, soll ihm noch angelastet werden. Weil er danach getan hat, was vor Gott recht ist, soll er am Leben bleiben." },
      { number: 23, text: "Meint ihr, es gefällt mir, wenn ein Gottloser stirbt?\", sagt Jahwe, der Herr. \"Nein, ich freue mich, wenn er sein Leben ändert und am Leben bleibt." },
      { number: 24, text: "Wenn aber ein Gerechter nicht mehr recht vor mir lebt, wenn er anfängt, Böses zu tun, und dieselben Abscheulichkeiten begeht wie der Gottlose, soll er dann am Leben bleiben? Nein! Keine von all seinen gerechten Taten wird ihm angerechnet werden. Weil er sich der Untreue schuldig gemacht und Böses getan hat, muss er sterben!" },
      { number: 25, text: "Wenn ihr nun sagt: 'Was der Herr tut, ist nicht recht!', so hört mir zu, ihr Leute von Israel: Meine Handlungsweise soll nicht richtig sein? Sind nicht vielmehr eure Handlungen falsch?" },
      { number: 26, text: "Wenn ein Gerechter nicht mehr recht vor mir lebt, wenn er anfängt, Unrecht zu tun und daraufhin stirbt, so stirbt er wegen des Unrechts, das er getan hat." },
      { number: 27, text: "Wenn aber ein Gottloser umkehrt, sein gesetzloses Handeln lässt und tut, was gut und richtig ist, dann wird er sein Leben retten." },
      { number: 28, text: "Sieht er es ein und lässt sein gesetzwidriges Tun, soll er am Leben bleiben und nicht sterben." },
      { number: 29, text: "Wenn also das Haus Israel sagt: 'Was der Herr tut, ist nicht recht!' – sollte wirklich meine Handlungsweise nicht die richtige sein, ihr Leute von Israel? Sind nicht vielmehr eure Handlungen falsch?" },
      { number: 30, text: "Darum werde ich euch das Urteil sprechen, ihr Leute von Israel! Jeder bekommt das, was er durch seine Taten verdient hat, spricht Jahwe, der Herr. Kehrt also um und macht Schluss mit allem Unrecht, damit es euch nicht zur Schuldfalle wird!" },
      { number: 31, text: "Trennt euch von allen Vergehen, mit denen ihr euch an mir vergangen habt, und schafft euch so ein neues Herz und einen neuen Geist! Warum wollt ihr denn sterben, ihr Leute von Israel?" },
      { number: 32, text: "Mir gefällt es nicht, wenn ein Mensch sterben muss, spricht Jahwe, der Herr. Kehrt also um, damit ihr am Leben bleibt!\"" },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Stimm du ein Klagelied über Israels Fürsten an!", heading: "Klagelied über Israels Fürsten" },
      { number: 2, text: "Es lautet so:\"Welch eine Löwin war deine Mutter! / Unter Löwen hatte sie ihr Lager, / unter jungen Löwen zog sie ihre Jungen auf." },
      { number: 3, text: "Eins von ihren Jungen zog sie groß, / und es wurde ein starker Löwe. / Er lernte, Beute zu reißen, / und fraß Menschen." },
      { number: 4, text: "Die Völker hörten von ihm / und fingen ihn in ihrer Grube. / Sie schleppten ihn an Haken nach Ägypten." },
      { number: 5, text: "Als die Löwin sah, dass sie vergeblich gehofft, / ja dass ihre Hoffnung verloren war, / nahm sie noch eins von ihren Jungen / und machte es zum starken Löwen." },
      { number: 6, text: "Auch dieser lebte unter Löwen, / wurde ein mächtiges Tier. / Er lernte, Beute zu reißen, / und fraß Menschen." },
      { number: 7, text: "Er kannte ihre Paläste / und zerstörte ihre Städte. / Das Land und alles darin erstarrte bei seinem Gebrüll." },
      { number: 8, text: "Da setzte man Völker gegen ihn ein / aus den Ländern ringsum. / Sie warfen ihr Netz über ihn / und packten ihn in ihrer Grube." },
      { number: 9, text: "An Haken zerrten sie ihn in den Käfig / und brachten ihn zum König von Babel. / Der sperrte ihn in einen Zwinger. / Und auf den Bergen Israels hört man sein Gebrüll nicht mehr.\"" },
      { number: 10, text: "Deine Mutter war wie ein Weinstock / am Wasser gepflanzt, / der Reben trieb / und voller Früchte hing, / weil er reichlich Wasser bekam." },
      { number: 11, text: "Seine Reben wurden stark / und waren selbst für Zepter gut; / sein Wuchs war hoch, / er ragte über das Laubwerk, / weit sichtbar durch seine Höhe / und die Menge seiner Reben." },
      { number: 12, text: "Doch im Zorn riss man ihn aus / und warf ihn auf die Erde; / der Ostwind dörrte ihn, / und seine Früchte riss man ab; / die mächtigen Reben verdorrten / und wurden vom Feuer verzehrt." },
      { number: 13, text: "Nun war er in die Wüste gepflanzt, / in ein trockenes, durstiges Land." },
      { number: 14, text: "Feuer fuhr von einer seiner Reben aus / und verzehrte seine Frucht. / Nun war keine starke Rebe mehr an ihm, / kein Zepter zum Herrschen geeignet.\"Dies ist ein Klagelied – es bleibt nur noch die Klage!" },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Am 10. August* im siebten Jahr unserer Verbannung kamen einige von den Ältesten Israels, um Jahwe zu befragen. Sie setzten sich vor mich hin.", heading: "Rebellisches Israel", footnotes: ["August. Wörtlich: im 5. Monat. Es war im Jahr 591 v. Chr., fünf Jahre vor der Zerstörung Jerusalems."] },
      { number: 2, text: "Da kam das Wort Jahwes zu mir:" },
      { number: 3, text: "\"Du Mensch, antworte den Ältesten Israels folgendermaßen: 'So spricht Jahwe, der Herr: Um mich zu befragen, kommt ihr? So wahr ich lebe, ich werde mich keinesfalls von euch befragen lassen, spricht Jahwe, der Herr.'" },
      { number: 4, text: "Willst du sie nicht richten, Mensch? Willst du nicht über sie Gericht halten? Halte ihnen die Schändlichkeiten ihrer Väter vor." },
      { number: 5, text: "Sage ihnen: 'So spricht Jahwe, der Herr:Als ich Israel erwählte, erhob ich meine Hand und schwor den Nachkommen Jakobs einen Eid, in Ägypten gab ich mich ihnen zu erkennen und schwor: Ich bin Jahwe, euer Gott!" },
      { number: 6, text: "An dem Tag erhob ich meine Hand zum Schwur, dass ich sie aus Ägypten herausführe in ein Land, das ich für sie ausgesucht hatte, das von Milch und Honig überfließt und eine Zierde aller Länder ist." },
      { number: 7, text: "Ich befahl ihnen: Werft die Scheusale weg, die ihr vor Augen habt, besudelt euch nicht an den Götzen Ägyptens! Ich bin Jahwe, euer Gott!" },
      { number: 8, text: "Aber sie widersetzten sich mir und gehorchten mir nicht. Keiner warf die Scheusale weg, die er vor Augen hatte. Sie wollten sich nicht von den Götzen Ägyptens trennen. Da wollte ich meinem Zorn freien Lauf lassen, noch in Ägypten sollten sie ihn zu spüren bekommen." },
      { number: 9, text: "Aber ich verschonte sie um meiner selbst willen. Ich wollte nicht, dass mein Ansehen bei den Völkern, unter denen sie waren, geschädigt würde. Denn vor ihren Augen hatte ich geschworen, mein Volk aus Ägypten heraus zu führen." },
      { number: 10, text: "So führte ich sie aus Ägypten und brachte sie in die Wüste." },
      { number: 11, text: "Dort gab ich ihnen meine Ordnungen und Gebote bekannt, durch die ein Mensch sein Leben bewahrt, wenn er sie befolgt." },
      { number: 12, text: "Ich gab ihnen auch meine Sabbate als Bundeszeichen zwischen mir und ihnen. Daran sollte man erkennen, dass ich, Jahwe, es bin, der sie heilig macht." },
      { number: 13, text: "Aber die Israeliten trotzten mir in der Wüste. Sie hielten sich nicht an meine Ordnungen und verwarfen meine Gebote, durch die ein Mensch sein Leben bewahrt, wenn er sie hält. Auch meine Sabbate entweihten sie völlig. Da wollte ich meinem Zorn freien Lauf lassen und sie in der Wüste vernichten." },
      { number: 14, text: "Aber ich verschonte sie um meiner selbst willen. Ich wollte nicht, dass mein Ansehen bei den Völkern beschädigt würde. Denn vor ihren Augen hatte ich mein Volk aus Ägypten heraus geführt." },
      { number: 15, text: "Doch in der Wüste erhob ich meine Hand zum Schwur, dass ich sie nicht in das Land bringen würde, das ich ihnen zugedacht hatte, das von Milch und Honig überfließt und eine Zierde aller Länder ist." },
      { number: 16, text: "Denn sie hingen immer noch an ihren Götzen, verwarfen meine Gebote, lebten nicht in meinen Ordnungen und schändeten meine Sabbate." },
      { number: 17, text: "Doch dann schaute ich sie mitleidig an und vernichtete sie nicht. Ich rottete sie in der Wüste nicht völlig aus." },
      { number: 18, text: "Zu ihren Söhnen sagte ich in der Wüste: Lebt nicht in den Ordnungen eurer Väter, folgt nicht ihren Geboten und besudelt euch nicht an ihren Götzen!" },
      { number: 19, text: "Ich bin Jahwe, euer Gott! Lebt in meinen Ordnungen und haltet meine Gebote!" },
      { number: 20, text: "Haltet auch meine Sabbate! Denn diese Tage sind mir geweiht und sollen das Zeichen für den Bund zwischen mir und euch sein, damit ihr erkennt, dass ich Jahwe, euer Gott, bin." },
      { number: 21, text: "Aber auch die Söhne widersetzten sich mir. Sie hielten sich nicht an meine Ordnungen und verwarfen meine Gebote, durch die ein Mensch sein Leben bewahrt, wenn er sie hält. Auch meine Sabbate schändeten sie. Da wollte ich meinem Zorn freien Lauf lassen und sie in der Wüste vernichten." },
      { number: 22, text: "Aber ich hielt mich zurück und verschonte sie um meiner selbst willen. Ich wollte nicht, dass mein Ansehen bei den Völkern beschädigt würde, vor deren Augen ich mein Volk aus Ägypten geführt hatte." },
      { number: 23, text: "Doch in der Wüste erhob ich meine Hand zum Schwur, dass ich sie unter die Völker zerstreuen und in alle Länder vertreiben werde." },
      { number: 24, text: "Denn sie verwarfen meine Gebote, lebten nicht in meinen Ordnungen und schändeten meine Sabbate. Ihre Augen hingen immer noch an den Götzen ihrer Väter." },
      { number: 25, text: "Da lieferte ich sie Ordnungen aus, die nicht gut waren und Geboten, die es ihnen unmöglich machten, am Leben zu bleiben.*", footnotes: ["Vergleiche die Handlungsweise Gottes in Römer 1,24-32."] },
      { number: 26, text: "Durch ihre Opfergaben besudelte ich sie. Sie brachten mir nämlich alle Erstgeborenen als Brandopfer. Ich wollte ihnen Entsetzen einjagen, denn sie sollten erkennen, dass ich bin, der ich bin – Jahwe!'" },
      { number: 27, text: "Du Mensch, sag darum zu den Leuten von Israel: 'So spricht Jahwe, der Herr: Eure Vorfahren haben mich auch dadurch beleidigt, dass sie mir untreu wurden." },
      { number: 28, text: "Als ich sie nämlich in das Land gebracht hatte – ich hatte ja meine Hand erhoben und geschworen, das zu tun –, da begannen sie, auf jedem hohen Hügel und unter jedem dichtbelaubten Baum Opfermahle zu feiern und brachten dort ihre Räucher- und Trankopfer dar." },
      { number: 29, text: "Ich fragte sie: Was habt ihr da auf der Höhe zu suchen? – Deshalb nennt man diese Stätten Opferhöhen* bis heute*.'", footnotes: ["Opferhöhen. Eigentlich: Höhen.", "heute. Das meint den Zeitpunkt, als das Buch verfasst wurde."] },
      { number: 30, text: "Darum sage zu den Leuten von Israel: 'So spricht Jahwe, der Herr: Wollt ihr euch genauso besudeln wie eure Väter und herumhuren mit ihren abscheulichen Götzen?" },
      { number: 31, text: "Ja, dadurch, dass ihr ihnen eure Gaben bringt und eure Kinder als Opfer verbrennt, besudelt ihr euch an euren Scheusalen. Und da soll ich mich von euch befragen lassen, ihr Israeliten? So wahr ich lebe, spricht Jahwe, der Herr: Von mir bekommt ihr keine Auskunft!'\"" },
      { number: 32, text: "\"Und was euch in den Sinn gekommen ist, darf niemals geschehen. Ihr sagt nämlich: 'Wir wollen wie die anderen Völker sein, wir wollen Holz und Stein verehren!'", heading: "Gott bringt sein Volk zur Umkehr" },
      { number: 33, text: "So wahr ich lebe, spricht Jahwe, der Herr: 'Ich werde mich als euer König erweisen; mit starker Hand und erhobenem Arm lasse ich meinem Zorn freien Lauf." },
      { number: 34, text: "Ich werde euch aus den Völkern herausführen und euch aus den Ländern holen, in die ich euch zerstreut habe. Mit starker Hand und erhobenem Arm lasse ich meinem Zorn freien Lauf" },
      { number: 35, text: "und führe euch in die Wüste zwischen den Völkern. Dort gehe ich persönlich mit euch ins Gericht." },
      { number: 36, text: "Ich werde euch zur Rechenschaft ziehen, wie ich es mit euren Vätern in der Wüste Ägyptens getan habe', spricht Jahwe, der Herr." },
      { number: 37, text: "'Ich werde euch zur Einzelprüfung unter dem Hirtenstab durchziehen lassen und so in die Ordnungen meines Bundes bringen." },
      { number: 38, text: "Und alle, die sich empört und mit mir gebrochen haben, werde ich von euch trennen. Ich werde sie zwar aus dem Land herausführen, in dem sie als Fremde gelebt haben, aber den Boden Israels werden sie nicht betreten. Dann werdet ihr erkennen, dass ich bin, der ich bin – Jahwe!" },
      { number: 39, text: "Aber was euch betrifft, ihr Leute von Israel', spricht Jahwe, der Herr, 'Geht doch hin und dient euren Götzen! Ihr werdet schon sehen, was ihr davon habt. Zuletzt aber werdet ihr meinen heiligen Namen nicht mehr entweihen mit euren Opfergaben und Götzen." },
      { number: 40, text: "Denn auf meinem heiligen Berg, dem hohen Berg Israels, spricht Jahwe, der Herr, wird das ganze Volk Israel mir dienen, alle, die sich im Land befinden. Dort werde ich ihnen meine Gnade schenken. Dort werde ich eure Opfergaben, die Erstanteile eurer Ernte und eure Weihgaben annehmen." },
      { number: 41, text: "Dort, beim Opfergeruch, der mich erfreut, werde ich euch voller Liebe wieder annehmen, nachdem ich euch aus den Völkern herausgeführt und aus den Ländern geholt habe, in die ich euch zerstreut hatte. So werde ich mich vor den Augen aller Völker als der Heilige erweisen." },
      { number: 42, text: "Und wenn ich euch wieder in das Land Israel bringe, das ich euren Vorfahren unter Eid zugesagt hatte, werdet ihr erkennen, dass ich bin, der ich bin – Jahwe!" },
      { number: 43, text: "Dort werdet ihr an euer Verhalten denken und an eure Taten, mit denen ihr euch besudelt habt. Ihr werdet Ekel vor euch selbst empfinden, wenn ihr an all das Böse denkt, das ihr getan habt." },
      { number: 44, text: "Dann werdet ihr erkennen, dass ich es bin – Jahwe, wenn ich um meinetwillen so mit euch umgegangen bin, ihr Leute von Israel, und nicht, wie ihr es mit eurem bösen Verhalten und eurem Verderben bringenden Tun verdient habt, spricht Jahwe, der Herr.'\"" },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Das Gleichnis vom Waldbrand" },
      { number: 2, text: "\"Du Mensch, blick nach Süden und lass deine Rede dorthin strömen, weissage gegen den Wald im Negev, dem heißen Land im Süden." },
      { number: 3, text: "Sage zum Wald des Negev: Höre das Wort Jahwes! So spricht Jahwe, der Herr: 'Pass auf! Ich werde ein Feuer in dir anzünden, das alle deine Bäume verzehrt, die grünen ebenso wie die dürren. Seine lodernde Flamme wird nicht verlöschen, und alle Gesichter, vom Süden bis zum Norden, werden durch sie versengt." },
      { number: 4, text: "Alle Welt soll erkennen, dass ich, Jahwe, den Brand gelegt habe, der nicht erlöschen wird.'\"" },
      { number: 5, text: "Da erwiderte ich: \"Ach Herr, Jahwe! Sie halten mir vor, dass ich nur Rätsel dichte!\"" },
      { number: 6, text: "Da kam das Wort Jahwes zu mir. Er sagte:" },
      { number: 7, text: "\"Du Mensch, blick in Richtung Jerusalem und lass deine Rede gegen die Heiligtümer strömen, weissage gegen das Land Israel!" },
      { number: 8, text: "Sag zum Land Israel: 'So spricht Jahwe: Pass auf! Jetzt gehe ich gegen dich vor! Ich ziehe mein Schwert und rotte die Gerechten und die Gottlosen in dir aus." },
      { number: 9, text: "Alle Menschen, vom Süden bis zum Norden, wird mein Schwert treffen, Gerechte und Gottlose." },
      { number: 10, text: "Und alle Welt soll erkennen, dass ich, Jahwe, mein Schwert gezogen habe und es nicht wieder in seine Scheide stecke.'" },
      { number: 11, text: "Doch du, Mensch, stöhne! Vor ihren Augen sollst du zusammenbrechen und vor Schmerz unaufhörlich stöhnen." },
      { number: 12, text: "Und wenn sie dich fragen: 'Weshalb stöhnst du so?', dann sage: 'Wegen der Nachricht, die kommen wird. Dann werden alle mutlos und verzagt, alle Hände werden schlaff und alle Knie werden weich. Ja, es kommt und geschieht, spricht Jahwe, der Herr.'\"" },
      { number: 13, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Das Lied vom Schwert" },
      { number: 14, text: "\"Du Mensch, weissage! Du sollst sagen: So spricht Jahwe:'Ein Schwert, ein Schwert, / geschärft und poliert;" },
      { number: 15, text: "geschärft für eine Metzelei, / poliert, dass es blitzt!Oder sollen wir uns freuen am Stock für meinen Sohn? Das Schwert verachtet solches Holz." },
      { number: 16, text: "Man gab es zum Schleifen, / dann packt es die Faust. / Ein Schwert, geschärft und poliert, / dem Scharfrichter ist es gegeben." },
      { number: 17, text: "Schrei und heule, Mensch, / denn es zielt auf mein Volk, / auf alle Fürsten Israels. / Sie sind dem Schwert verfallen, / genauso wie mein Volk. / Schlag dir auf die Hüfte," },
      { number: 18, text: "denn es wurde erprobt!''Doch was, wenn der verachtete Stock nicht mehr ist?', spricht Jahwe, der Herr." },
      { number: 19, text: "Weissage, Mensch, / und schlag die Hände zusammen! / Da verdoppelt sich das Schwert, / ja dreifach wird es sein! / Es sei das Schwert der Erschlagenen, / ein großes Mordschwert, / das sie von allen Seiten umkreist." },
      { number: 20, text: "Das Herz sei voller Angst, / und viele sollen fallen! / An allen ihren Toren wütet das Schwert. / Ja, zum Blitzen bist du gemacht, / zum Schlachten geschärft!" },
      { number: 21, text: "Zeig, dass du scharf bist! / Zucke nach rechts, / fahre nach links, / wohin deine Schneide sich richtet!" },
      { number: 22, text: "Auch ich schlag die Hände zusammen / und stille meinen Zorn. / Ich, Jahwe, habe gesprochen.\"" },
      { number: 23, text: "Das Wort Jahwes kam zu mir. Er sagte:" },
      { number: 24, text: "\"Du Mensch, stell zwei Wege für dich dar, auf denen der König von Babylon mit seinem Heer kommt. Beide Wege gehen vom selben Land aus. Und stell einen Wegweiser an der Gabelung auf." },
      { number: 25, text: "Einer soll nach Rabba zeigen, der Hauptstadt der Ammoniter, und einer nach Jerusalem, der befestigten jüdischen Stadt." },
      { number: 26, text: "Denn der König von Babylon bleibt an der Wegscheide stehen und befragt das Orakel. Er schüttelt die Pfeile, befragt die Terafim* und beschaut die Leber.", footnotes: ["Terafim. Abbilder oder Figuren von Schutzgeistern bzw. Hausgötzen, die auch zu Orakelzwecken benutzt wurden."] },
      { number: 27, text: "Dann hält er in seiner rechten Hand den Entscheid des Orakels: Jerusalem. Jetzt wird er das Kriegsgeschrei gegen die Stadt erheben, Sturmböcke an ihre Tore stellen, Wälle aufschütten und Belagerungstürme bauen." },
      { number: 28, text: "Doch die Leute von Jerusalem bilden sich ein, es sei ein Lügenorakel, denn man hat ihnen ja heilige Eide geschworen. Aber der König von Babel bringt ihre ganze Schuld ans Licht und nimmt sie gefangen.\"" },
      { number: 29, text: "Darum spricht Jahwe, der Herr: \"Weil ihr eure Schuld in Erinnerung brachtet, indem ihr eure Verbrechen aufdeckt und man die Sünden in all eurem Tun erkennt, weil ihr euch so in Erinnerung brachtet, werdet ihr mit harter Hand gepackt!" },
      { number: 30, text: "Und du gottloser Schurke, du König Israels, für den der Tag der endgültigen Abrechnung gekommen ist:" },
      { number: 31, text: "Weg mit dem Kopfbund, herunter mit der Krone, spricht Jahwe, der Herr. Nichts bleibt, wie es ist! Der Niedrige wird erhöht und der Mächtige gestürzt!" },
      { number: 32, text: "In Trümmer lege ich Jerusalem, in Trümmer, in Trümmer! Auch das bleibt nicht, bis der kommt, dem es rechtmäßig gehört. Ihm gebe ich es." },
      { number: 33, text: "Du Mensch, weissage Folgendes: 'So spricht Jahwe, der Herr, über die Ammoniter und ihren Hohn:Schwert, Schwert, gezückt zum Schlachten, poliert zum Fressen, damit es wie ein Blitz einschlägt." },
      { number: 34, text: "Du wirst an die Hälse der schändlichen Frevler gelegt, während man noch Nichtiges schaut und Lüge orakelt, denn der Tag der endgültigen Abrechnung ist da!" },
      { number: 35, text: "Doch dann zurück in deine Scheide, Schwert! Auch dich will ich richten im Land deiner Herkunft, am Ort, wo du geschaffen wurdest." },
      { number: 36, text: "Ich lasse meinem Zorn freien Lauf und fache meinen Grimm gegen dich an. Ich gebe dich viehischen Männern in die Hand: Schmieden des Verderbens." },
      { number: 37, text: "Du wirst vom Feuer verzehrt, dein eigenes Land trinkt dein Blut. Man wird dich vergessen.' Ich habe es gesagt, ich, Jahwe.\"" },
    ] },
    { number: 22, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Das Urteil" },
      { number: 2, text: "\"Mensch, willst du richten? Willst du die Stadt der Mörder richten? Dann halte ihr die Gräueltaten vor, die sie beging," },
      { number: 3, text: "und sage: 'So spricht Jahwe, der Herr:Du Stadt, die Blut in ihren Mauern vergießt und damit ihr Ende heraufbeschwört, die sich besudelt durch ihre Götzen!" },
      { number: 4, text: "Durch dein Blutvergießen bist du schuldig geworden, und durch deine Götzen hast du dich besudelt. Damit hast du deinen Untergang herbeigeführt. Du bist ans Ende deiner Jahre gekommen. Deshalb mache ich dich zu einem Zeichen der Schande unter den Völkern und gebe dich preis ihrem höhnischen Spott." },
      { number: 5, text: "Die Nahen und die Fernen verhöhnen dich, denn dein Name ist besudelt, deine Verbrechen sind groß." },
      { number: 6, text: "Die Fürsten Israels in dir missbrauchten ihre Macht, um Blut zu vergießen." },
      { number: 7, text: "In dir verachtet man Vater und Mutter, in deiner Mitte erpresst man den Fremden und unterdrückt Waisen und Witwen." },
      { number: 8, text: "Was mir heilig ist, verachtest du und schändest den Sabbat." },
      { number: 9, text: "Es gibt Verleumder in dir, die Menschen dem Tod ausliefern. Auf deinen Bergen feiert man Opfermahle, und in deiner Mitte begeht man die schlimmsten Untaten." },
      { number: 10, text: "Man schläft mit der Frau des eigenen Vaters und verkehrt mit Frauen während ihrer Monatsblutung." },
      { number: 11, text: "Der eine hat Sex mit der Frau seines Nächsten, der andere schändet seine Schwiegertochter und der dritte missbraucht seine Schwester." },
      { number: 12, text: "Bestochene Richter sprechen Todesurteile aus, man nimmt Wucherzinsen und erpresst seinen Nächsten. Doch mich, mich hast du vergessen, spricht Jahwe, der Herr." },
      { number: 13, text: "Ich schlage die Hände wegen deiner Raffgier zusammen und wegen der Morde, die in deiner Mitte geschehen sind." },
      { number: 14, text: "Bildest du dir ein, du könntest vor mir bestehen? Meinst du, deine Hände bleiben stark, wenn ich mich mit dir befasse? Ich, Jahwe, habe es gesagt, und ich werde es tun!" },
      { number: 15, text: "Ich werde dich unter die Völker zersprengen, vertreibe dich in alle Länder und mache deinem gottlosen Treiben ein Ende." },
      { number: 16, text: "Vor den Augen aller Völker wirst du durch dich selbst besudelt werden. Du sollst erkennen, dass ich bin, der ich bin – Jahwe!'\"" },
      { number: 17, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Der Schmelzofen" },
      { number: 18, text: "\"Du Mensch, das Haus Israel ist für mich wie Schlacke geworden, wie Schlacke beim Silberschmelzen, die nur noch Kupfer, Zinn, Eisen und Blei enthält." },
      { number: 19, text: "Darum spricht Jahwe, der Herr: 'Weil ihr alle zu Schlacke geworden seid, häufe ich euch in Jerusalem auf." },
      { number: 20, text: "Wie man Silber, Kupfer, Eisen, Blei und Zinn in einem Schmelzofen zusammenbringt, um Feuer darunter anzublasen, so bringe ich euch zusammen und lasse euch die Glut meines Zorns spüren." },
      { number: 21, text: "Ja, ich werde euch zusammenwerfen und das Feuer meines Grimms unter euch anblasen, dass ihr darin ausgeschmolzen werdet." },
      { number: 22, text: "Wie das Silber im Ofen, so sollt ihr in meinem Grimm geschmolzen werden. Ihr sollt erkennen, dass ich, Jahwe, meinen glühenden Zorn über euch ausgegossen habe.'\"" },
      { number: 23, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Alle sind schuld" },
      { number: 24, text: "\"Sprich zum Land Israel, Mensch: 'Du bist so besudelt, dass ich am Tag meines Zorns keinen Regen mehr schicke.'" },
      { number: 25, text: "Die Rotte seiner Propheten hat sich verschworen. Sie verschlingen Seelen wie ein brüllender Löwe, der Beute reißt. Sie rauben Schätze zusammen und haben viele Frauen zu Witwen gemacht." },
      { number: 26, text: "Seine Priester tun meinem Gesetz Gewalt an und entweihen, was mir heilig ist. Sie machen keinen Unterschied zwischen heiligen und unheiligen Dingen, sie belehren nicht über rein und unrein und verschließen ihre Augen vor dem Sabbat. So werde ich unter ihnen entweiht." },
      { number: 27, text: "Seine Oberen sind wie räuberische Wölfe. Sie vergießen Blut, verderben Seelen, nur um sich zu bereichern." },
      { number: 28, text: "Und seine Propheten schmieren Lehm darüber, indem sie Hirngespinste schauen und ihnen falsche Orakel verkünden und dabei sagen: 'So spricht Jahwe, der Herr!' Dabei hat Jahwe gar nicht geredet." },
      { number: 29, text: "Das Volk des Landes erpresst und raubt, es plündert und plagt den Elenden und Armen und verweigert dem Fremden sein Recht." },
      { number: 30, text: "Ich suchte einen Mann unter ihnen, der die Mauer zumauert oder der für das Land in die Bresche springt und mir entgegentritt, damit ich es nicht vernichten muss. Doch ich fand keinen." },
      { number: 31, text: "So schütte ich die Glut meines Zorns über sie aus und vernichte sie in meinem Grimm. Ihr Tun lasse ich auf sie selbst zurückfallen, spricht Jahwe, der Herr.\"" },
    ] },
    { number: 23, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Die schamlosen Schwestern" },
      { number: 2, text: "\"Du Mensch, da gab es zwei Frauen, Töchter einer Mutter." },
      { number: 3, text: "Schon in ihrer Jugend, in Ägypten, lebten sie in Unmoral und ließen ihre Brüste betasten. Dort befühlte man ihren mädchenhaften Busen." },
      { number: 4, text: "Die ältere Schwester hieß Ohola*, die jüngere Oholiba*. Ohola ist Samaria und Oholiba Jerusalem. Sie wurden meine Frauen und gebaren mir Söhne und Töchter.", footnotes: ["Ohola = Ihr eigenes Zelt, d.h. \"die ihr eigenes Heiligtum (in Bethel) hat\".", "Oholiba = Mein Zelt in ihr, d.h. \"die, in der mein Heiligtum (in Jerusalem) sich befindet\"."] },
      { number: 5, text: "Ohola aber brach die Ehe mit mir. Sie hofierte ihre Liebhaber, die kampftüchtigen Assyrer," },
      { number: 6, text: "die in Purpur gekleideten Statthalter und Offiziere, allesamt schöne junge Männer hoch zu Ross." },
      { number: 7, text: "Mit ihnen ließ sie sich ein – es war die Elite von Assur –, ihnen gab sie sich hin, und mit ihren Götzen besudelte sie sich." },
      { number: 8, text: "Doch auch das, was sie in Ägypten getrieben hatte, gab sie nicht auf. Denn die Ägypter hatten schon in ihrer Jugend bei ihr gelegen, ihren mädchenhaften Busen befühlt und Verkehr mit ihr gehabt." },
      { number: 9, text: "Darum gab ich sie der Gewalt ihrer Liebhaber preis, der Gewalt der Assyrer, auf die sie so versessen war." },
      { number: 10, text: "Die zogen sie nackt aus, nahmen ihr die Söhne und Töchter weg und erschlugen sie dann mit dem Schwert. So vollzogen sie das Strafgericht an ihr, zum abschreckenden Beispiel für alle Frauen." },
      { number: 11, text: "Ihre Schwester Oholiba sah das alles, aber sie trieb es noch ärger mit ihrer Gier und ihrer sexuellen Unmoral als sie." },
      { number: 12, text: "Auch sie hofierte die Söhne Assurs, die Statthalter und Offiziere, die schönen jungen Männer, die prächtig gekleideten Kämpfer, hoch zu Ross." },
      { number: 13, text: "Ich sah, wie sie sich mit ihnen besudelte. Da waren beide Schwestern gleich." },
      { number: 14, text: "Aber das war ihr noch nicht genug. Sie sah Wandbilder von Männern mit roter Farbe gemalt, es waren Chaldäer*.", footnotes: ["Chaldäer. Bewohner von Süd-Babylonien, später wurden alle Babylonier so genannt."] },
      { number: 15, text: "Sie hatten einen Gurt um die Hüfte und einen Bund um den Kopf. Unter diesem quoll ihr langes Haar hervor. Alle sahen wie Krieger aus, hervorragende Kämpfer, wie Babylonier, deren Geburtsland Chaldäa ist." },
      { number: 16, text: "Als sie ihre Bilder sah, packte sie die Gier, und sie schickte Boten nach Chaldäa." },
      { number: 17, text: "Da kamen die Babylonier zu ihrem Liebesnest und besudelten sie mit ihrer sexuellen Unmoral. Doch als sie sich befleckt hatte, riss sie sich von ihnen los." },
      { number: 18, text: "Aber da wandte ich mich jäh von ihr ab, so wie ich mich auch schon von ihrer Schwester abgewandt hatte, denn ihre sexuelle Unmoral war offenkundig, sie hatte ihre Blöße aufgedeckt." },
      { number: 19, text: "Doch sie trieb es nur noch schlimmer. Sie dachte an ihre Jugendzeit, wo sie es mit den Ägyptern getrieben hatte." },
      { number: 20, text: "Wieder packte sie die Gier nach ihren früheren Liebhabern, deren Glied so groß wie das eines Esels war und deren Samenerguss so mächtig wie der von einem Hengst." },
      { number: 21, text: "Du wolltest es wieder mit ihnen treiben wie in deiner Jugend, als man in Ägypten deine Brüste betastete und deinen jungfräulichen Busen befühlte." },
      { number: 22, text: "Darum Oholiba, spricht Jahwe, der Herr, pass auf: Deine früheren Liebhaber, denen du auf einmal den Rücken gekehrt hast, hetze ich gegen dich auf. Ich lasse sie von allen Seiten über dich kommen." },
      { number: 23, text: "Es sind die Männer aus Babylon und alle Chaldäer, die Männer aus Pekod, Schoa und Koa* und dazu die Assyrer, lauter schöne junge Männer, Statthalter und Befehlshaber, hervorragende Kämpfer und Edelleute, alle hoch zu Ross.", footnotes: ["Pekod: Aramäer, die östlich von Babylon lebten. Schoa und Koa waren offenbar babylonische Verbündete."] },
      { number: 24, text: "In Scharen fallen sie über dich her mit Reitern und Wagen und einem Heer aus vielen Völkern. Dann bist du von Helmen, Rund- und Langschilden umringt. Ich übergebe dich ihrem Gericht, und nach ihrem Recht bestrafen sie dich." },
      { number: 25, text: "Ich werde dich meine Eifersucht fühlen lassen und ein schweres Strafgericht an dir vollziehen. Nase und Ohren werden sie dir abschneiden, und deine Nachkommenschaft wird mit dem Schwert getötet werden. Deine Söhne und Töchter nehmen sie dir weg, und was dann noch übrig ist von dir, wird vom Feuer vernichtet." },
      { number: 26, text: "Sie werden dir die Kleider ausziehen und dir deinen Schmuck wegnehmen." },
      { number: 27, text: "So mache ich deinem schändlichen Treiben ein Ende und deiner sexuellen Unmoral, die schon in Ägypten begann. Du sollst nicht mehr nach ägyptischen Männern Ausschau halten und nicht einmal mehr an sie denken.\"" },
      { number: 28, text: "Denn so spricht Jahwe, der Herr: \"Ich gebe dich in die Gewalt deiner früheren Liebhaber, von denen du dich auf einmal abgewandt hast und die du jetzt verabscheust." },
      { number: 29, text: "Hasserfüllt werden sie über dich herfallen und dir alles wegnehmen, was du dir erworben hast. Sie lassen dich nackt und bloß daliegen. Deine Scham wird entblößt und dein schändliches, lüsternes und widerliches Treiben kommt an den Tag." },
      { number: 30, text: "So wirst du dafür bestraft, weil du in deiner sexuellen Gier den Völkern nachgelaufen bist und dich mit ihren Götzen besudelt hast." },
      { number: 31, text: "Du bist denselben Weg wie deine Schwester gegangen, darum gebe ich dir jetzt ihren Becher zu trinken.\"" },
      { number: 32, text: "So spricht Jahwe, der Herr:\"Den Becher deiner Schwester wirst du leeren, / den Riesenbecher, der viel fasst. / Verspotten und verhöhnen wird man dich." },
      { number: 33, text: "Von Trunkenheit und Kummer wirst du voll, / denn ein Becher des Grauens und Entsetzens / ist der Becher deiner Schwester Samaria." },
      { number: 34, text: "Du wirst ihn trinken und schlürfst ihn aus, / du wirst seine Scherben zerbeißen / und dir die Brüste zerreißen. / Denn ich habe gesprochen, sagt Jahwe, der Herr.\"" },
      { number: 35, text: "Darum spricht Jahwe, der Herr: \"Weil du mich vergessen und mich völlig verworfen hast, sollst du die Folgen deines schamlosen Treibens und deiner sexuellen Unmoral tragen.\"" },
      { number: 36, text: "Darauf sagte Jahwe zu mir: \"Mensch, willst du nicht Ohola und Oholiba zur Rechenschaft ziehen? Halte ihnen ihre Gräueltaten vor!" },
      { number: 37, text: "Sie haben die Ehe gebrochen, und Blut klebt an ihren Händen. Den Ehebruch haben sie mit ihren Mistgötzen begangen und ihnen auch noch die Kinder, die sie mir geboren hatten, zum Fraß hingeworfen." },
      { number: 38, text: "Und auch das haben sie mir angetan: Am selben Tag haben sie mein Heiligtum besudelt und den Sabbat entweiht." },
      { number: 39, text: "Denn wenn sie ihre Söhne ihren Götzen schlachteten, kamen sie noch am selben Tag in mein Heiligtum und haben es besudelt. So trieben sie es in meinem Haus." },
      { number: 40, text: "Außerdem haben sie Boten in die Ferne geschickt und Männer eingeladen. Als die dann kamen, hattest du dich für sie gebadet, deine Augen geschminkt und deinen Schmuck angelegt." },
      { number: 41, text: "Dann hast du dich auf ein prächtiges Ruhebett niedergelassen. Davor war ein Tisch zugerichtet, auf dem du meinen Weihrauch und mein Öl gestellt hattest." },
      { number: 42, text: "Ihr umgabt euch mit einer lärmenden ausgelassenen Menge. Und zu den Männern aus dem Menschenhaufen ließ man noch Säufer aus der Wüste kommen. Diese legten den Schwestern Spangen an die Arme und setzten ihnen prachtvolle Kronen auf." },
      { number: 43, text: "Da sagte ich mir: 'Sie sind doch schon verbraucht – und treiben immer noch Ehebruch? Ihr Huren muss doch zum Ekel werden, und sie auch!'" },
      { number: 44, text: "Doch die Männer hatten Verkehr mit ihr, wie man es eben mit einer Prostituierten tut; so trieben sie es mit Ohola und Oholiba." },
      { number: 45, text: "Aber gerechte Männer werden das Urteil über sie sprechen nach dem Gesetz für Ehebrecherinnen und Mörderinnen. Denn sie haben die Ehe gebrochen, und Blut klebt an ihren Händen.\"" },
      { number: 46, text: "Denn so spricht Jahwe, der Herr: \"Ich bringe eine große Menge Volk gegen sie zusammen und gebe sie der Misshandlung und Ausplünderung preis." },
      { number: 47, text: "Die Versammlung soll sie steinigen und ihre Leichen mit Schwertern zerhauen. Ihre Söhne und Töchter soll man erschlagen und ihre Häuser niederbrennen." },
      { number: 48, text: "So werde ich der sexuellen Unmoral im Land ein Ende machen, dass alle Frauen sich warnen lassen und eurem schlimmen Beispiel nicht folgen." },
      { number: 49, text: "Eure Unmoral wird auf euch zurückfallen, und die Folgen eures sündhaften Götzendienstes müsst ihr tragen. Ihr sollt erkennen, dass ich Jahwe, der Herr bin.\"" },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Am 10. Januar* im neunten Jahr unserer Verbannung kam das Wort Jahwes zu mir.", heading: "Der rostige Topf", footnotes: ["Januar. Wörtlich: im 10. Monat. Es war das Jahr 588 v. Chr., etwa zwei Jahre vor der Zerstörung Jerusalems."] },
      { number: 2, text: "\"Mensch, schreib dir das Datum dieses Tages auf, genau den heutigen Tag! Heute hat der König von Babylon seinen Angriff auf Jerusalem begonnen." },
      { number: 3, text: "Trag dem widerspenstigen Volk ein Gleichnis vor. Sag zu ihnen: 'So spricht Jahwe, der Herr:Stell hin den Topf, stell hin / und gieße auch Wasser hinein!" },
      { number: 4, text: "Lege Fleisch in den Topf, / lauter gute Stücke / von Lende und Schulter. / Gib die besten Knochen dazu." },
      { number: 5, text: "Nimm auserlesene Schafe! / Das Holz ist darunter zu schichten! / Lass die Fleischstücke sieden mit den Knochen darin!'" },
      { number: 6, text: "Darum spricht Jahwe, der Herr:'Weh der blutbefleckten Stadt! / Weh dem rostigen Topf, / dessen Rost nicht abgehen will! / Stück für Stück nimm wahllos heraus!" },
      { number: 7, text: "Denn das Blut, das sie vergoss, / ist noch mitten in ihr. / Auf die Felsplatte hat sie es geschüttet / und es nicht einmal mit Erde bedeckt." },
      { number: 8, text: "Um Zorn heraufzuführen, / um Rache zu nehmen, / gebe ich auf kahlen Fels ihr Blut; / es wird nicht mit Erde bedeckt.'" },
      { number: 9, text: "Darum spricht Jahwe, der Herr:'Weh der blutbefleckten Stadt! / Auch ich schichte einen großen Holzstoß auf." },
      { number: 10, text: "Trage nur viel Holz herbei! / Entzünde das Feuer! / Siede das Fleisch! / Verkoche die Brühe, / bis selbst die Knochen anglühen!" },
      { number: 11, text: "Dann stell ihn leer auf seine Kohlen, / dass der Topf sich erhitzt, / seine Bronze erglüht, / der Rost ausgebrannt wird, / der ihn besudelt hat." },
      { number: 12, text: "Vergebliche Mühe! / Er ist so mit Rost bedeckt, / dass auch die Glut ihn nicht reinigen kann.'" },
      { number: 13, text: "Ich wollte dich reinigen, aber du warst nicht rein zu bekommen. Nun wirst du besudelt bleiben, bis ich meinen ganzen Zorn an dir ausgelassen habe." },
      { number: 14, text: "Ich, Jahwe, habe es gesagt. Es kommt und ich werde es tun! Ich lasse nicht nach, ich schone nicht, habe keine Bedenken. Nach deinem Verhalten und nach deinen Taten wird man dich richten, spricht Jahwe, der Herr.\"" },
      { number: 15, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Der Tod ohne Trauer" },
      { number: 16, text: "\"Du Mensch, ich nehme dir jetzt dein Liebstes weg, die Freude deiner Augen durch plötzlichen Tod. Doch du sollst nicht klagen und weinen. Keine Träne soll dir kommen," },
      { number: 17, text: "hemme das Seufzen! Unterlass die Totenklage! Binde deinen Kopfbund um und ziehe deine Schuhe an! Verhülle deinen Bart nicht und iss nichts von dem Trauerbrot, das dir die Leute bringen!\"" },
      { number: 18, text: "Am Morgen darauf redete ich zum Volk. Am Abend starb meine Frau. Und am anderen Morgen verhielt ich mich so, wie mir befohlen war." },
      { number: 19, text: "Da fragten mich die Leute: \"Willst du uns nicht erklären, was dein Verhalten für uns zu bedeuten hat?\"" },
      { number: 20, text: "Ich sagte zu ihnen: \"Das Wort Jahwes kam zu mir. Er sagte:" },
      { number: 21, text: "'Sag zu den Leuten von Israel: So spricht Jahwe, der Herr: Passt auf! Ich entweihe mein Heiligtum, den Zufluchtsort, auf den ihr so stolz seid, die Freude eurer Augen und das Ziel eurer Sehnsucht. Eure Söhne und Töchter, die ihr verlassen musstet, werden unter dem Schwert umkommen." },
      { number: 22, text: "Da werdet ihr tun, was ich getan habe; ihr werdet den Bart nicht verhüllen und kein Trauerbrot von den Nachbarn annehmen." },
      { number: 23, text: "Ihr werdet den Kopfbund aufbehalten und die Schuhe an den Füßen. Ihr werdet nicht klagen und weinen, sondern hinmodern in euren Sünden und einer den anderen anstöhnen." },
      { number: 24, text: "So wird Hesekiël für euch zum Wahrzeichen sein. Wenn es kommt, werdet ihr euch genauso wie er verhalten. Dann werdet ihr erkennen, dass ich Jahwe, der Herr bin.'\"" },
      { number: 25, text: "\"Aber du, Mensch, pass auf! An dem Tag, an dem ich ihnen ihre Zuflucht wegnehme, ihre Pracht und Wonne, die Freude ihrer Augen und das Ziel ihrer Sehnsucht, und ihre Söhne und Töchter dazu," },
      { number: 26, text: "an dem Tag wird ein Flüchtling zu dir kommen, sodass du es mit eigenen Ohren hören kannst." },
      { number: 27, text: "Dann wird deine Zunge gelöst werden, du wirst mit ihm reden können und nicht länger stumm sein. Dann bist du ihnen zum Wahrzeichen geworden, und sie werden erkennen, dass ich es bin – Jahwe!\"" },
    ] },
    { number: 25, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Das Gericht über die Nachbarn von Juda (25-32)\nAmmon" },
      { number: 2, text: "\"Du Mensch, blick in Richtung der Ammoniter* und weissage Folgendes gegen sie:", footnotes: ["Die Ammoniter waren nordöstliche Nachbarn der Moabiter."] },
      { number: 3, text: "'Hört das Wort Jahwes, des Herrn! So spricht Jahwe, der Herr: Du lachst und spottest über mein Heiligtum, weil es entweiht ist, und über das Land Israel, weil es verwüstet wurde, und über das Volk der Juden, weil sie in die Gefangenschaft verschleppt sind." },
      { number: 4, text: "Deshalb gebe ich dich und dein Land den Beduinen des Ostens zum Besitz. Sie werden ihre Zelte bei euch aufschlagen und ihre Siedlungen in deinem Land errichten, sie werden deine Früchte essen und deine Milch trinken." },
      { number: 5, text: "Rabba mache ich zu einem Weideplatz für Kamele und eure Ortschaften zum Lagerplatz für Kleinvieh. Dann werdet ihr erkennen, dass ich es bin – Jahwe!" },
      { number: 6, text: "Denn so spricht Jahwe, der Herr: Weil du in die Hände geklatscht und vor Freude mit den Füßen gestampft hast, weil du voller Schadenfreude auf das Land Israel herabgesehen hast," },
      { number: 7, text: "deshalb gehe ich jetzt gegen dich vor. Ich gebe dich fremden Völkern preis und rotte dich aus der Völkergemeinschaft aus. Ich werde dich vernichten. Dann wirst du erkennen, dass ich es bin – Jahwe!'\"" },
      { number: 8, text: "So spricht Jahwe, der Herr: \"Weil Moab* und Seïr* sagen: 'Das Haus Juda ist so wie alle anderen Nationen',", heading: "Moab", footnotes: ["Die Moabiter lebten östlich des Toten Meeres zwischen den Flüssen Arnon und Zered.", "Seïr. Gebirge südlich des Toten Meeres, das von Edomitern bewohnt wurde."] },
      { number: 9, text: "darum lege ich Moabs Schulter frei, seine Berghänge werden von all seinen Städten entblößt sein, von der Zierde des Landes über Bet-Jeschimot, Baal-Meon bis nach Kirjatajim." },
      { number: 10, text: "Ich gebe das Land den Beduinen des Ostens und den Ammonitern, an die sich niemand mehr erinnern wird." },
      { number: 11, text: "So vollstrecke ich mein Strafgericht an den Moabitern; und sie werden erkennen, dass ich es bin – Jahwe!\"" },
      { number: 12, text: "So spricht Jahwe, der Herr: \"Weil Edom* grausam Rache am Haus Juda genommen und dabei schwere Schuld auf sich geladen hat,", heading: "Edom", footnotes: ["Edom. Land östlich der Araba und südlich vom Toten Meer, bewohnt von den Nachkommen Esaus."] },
      { number: 13, text: "deshalb, spricht Jahwe, der Herr, gehe ich jetzt gegen Edom vor. Ich rotte Menschen und Vieh in ihm aus. Von Teman bis nach Dedan* lege ich es in Trümmer, und alle seine Bewohner werden durchs Schwert umkommen.", footnotes: ["Teman ist ein Gebiet mitten in Edom, in der Nähe von Petra. Dedan ist ein Stamm und ein Gebiet im Süden Edoms."] },
      { number: 14, text: "Meine Rache an Edom lasse ich durch mein Volk Israel vollziehen. Sie werden Edom meinen Zorn und Grimm spüren lassen, dass sie meine Rache erkennen, spricht Jahwe, der Herr.\"" },
      { number: 15, text: "So spricht Jahwe, der Herr: \"Weil die Philister sich grausam gerächt haben mit hämischer Lust und voller Hass, um Juda aus uralter Feindschaft zu vernichten,", heading: "Die Philister" },
      { number: 16, text: "darum spricht Jahwe, der Herr: 'Passt auf, ich gehe gegen die Philister vor, diese Leute aus Kreta, und rotte die Bewohner der Küstenebene bis auf den letzten Rest aus." },
      { number: 17, text: "Mit grimmigen Strafen nehme ich gewaltige Rache an ihnen. Und wenn ich meine Rache über sie bringe, wird man erkennen, dass ich es bin – Jahwe!'\"" },
    ] },
    { number: 26, verses: [
      { number: 1, text: "Am 1. des Monats* im elften Jahr unserer Verbannung kam das Wort Jahwes zu mir. Er sagte:", heading: "Das Gericht über Tyrus", footnotes: ["Monats. Der Monatsname wird nicht genannt. Es muss im Frühjahr 586 v. Chr. gewesen sein, kurz vor der Zerstörung Jerusalems."] },
      { number: 2, text: "\"Du Mensch, / weil Tyrus* über Jerusalem sagte: / 'Ha! Zerbrochen ist das Tor der Völker! / Jetzt fällt mir ihr Reichtum zu, / denn sie ist verwüstet',", footnotes: ["Tyrus war die wichtigste Hafenstadt an der phönizischen Küste, 56 km nördlich vom Berg Karmel. Zu dieser Zeit lag die Stadt schon auf einer Felsen-Insel vor dem Festland."] },
      { number: 3, text: "darum spricht Jahwe, der Herr: 'Jetzt gehe ich gegen dich vor, Tyrus! Wie das Meer gegen deine Klippen brandet, werde ich viele Völker gegen dich anstürmen lassen!" },
      { number: 4, text: "Sie werden deine Mauern schleifen, Tyrus, und deine Türme niederreißen. Ich fege deine Erde von dir weg und mache dich zu einem kahlen Felsen im Meer," },
      { number: 5, text: "zu einem Trockenplatz für Fischernetze. Ich habe das gesagt', spricht Jahwe, der Herr. 'Völker werden Tyrus ausplündern," },
      { number: 6, text: "seine Tochterstädte auf dem Festland zerstören und deren Einwohner töten. Daran wird man erkennen, dass ich es bin – Jahwe!'\"" },
      { number: 7, text: "So spricht Jahwe, der Herr: \"Ich werde den Großkönig Nebukadnezzar, den König von Babylon, über Tyrus kommen lassen. Er kommt vom Norden her mit Pferden, Streitwagen, Reitern und einem riesigen Heer." },
      { number: 8, text: "Er wird deine Tochterstädte zerstören und einen Wall gegen dich aufschütten, Angriffsrampen gegen deine Mauern vorantreiben und ein Schutzdach aus Langschilden gegen dich aufstellen." },
      { number: 9, text: "Der Stoß seiner Rammböcke wird deine Mauern treffen. Mit Brecheisen reißt er deine Türme ein." },
      { number: 10, text: "Eine Staubwolke wird dich bedecken, wenn er anrückt mit der Masse seiner Pferde. Der Lärm seiner Reiter, Räder und Wagen lässt deine Mauern erbeben, wenn er durch deine Tore einfährt, wie man in eine aufgebrochene Stadt einzieht." },
      { number: 11, text: "Die Hufe seiner Pferde zerstampfen deine Straßen, dein Volk erschlägt er mit dem Schwert. Die stolzen Steinsäulen, die du verehrst, sinken in Trümmer." },
      { number: 12, text: "Sie plündern deinen Besitz, sie rauben deine Waren, sie schleifen deine Mauern und zerstören deine Paläste. Und deine Steine, dein Holz und deinen Schutt schütten sie ins Meer." },
      { number: 13, text: "Ich lasse den Klang deiner Lieder verstummen, und die Musik deiner Harfen wird nicht mehr gehört." },
      { number: 14, text: "Ich mache dich zu einem kahlen Felsen, zu einem Trockenplatz für Fischernetze. Du wirst nicht wieder aufgebaut werden, denn ich, Jahwe, habe das gesagt!\", spricht Jahwe, der Herr." },
      { number: 15, text: "So spricht Jahwe, der Herr, gegen Tyrus: \"Vom Donnergetöse deines Falls werden die Inseln erbeben, wenn Mörder in dir wüten und jeder Durchbohrte stöhnt." },
      { number: 16, text: "Dann sinken die Fürsten des Meeres von ihren Thronen. Sie legen ihre Mäntel ab, ziehen ihre buntgewirkten Kleider aus und kleiden sich in zitternde Angst. Vor Entsetzen kauern sie auf dem Boden und zittern und zitterten." },
      { number: 17, text: "Dann stimmen sie die Totenklage über dich an:'Ach, wie bist du zerstört, / du ruhmreiche Stadt, / du Festung am Meer! / Du hattest solche Macht auf der See, / hast ihre Anwohner in Schrecken versetzt." },
      { number: 18, text: "Nun zittern die Küsten am Tag deines Falls; / über dein Ende sind die Inseln entsetzt.'\"" },
      { number: 19, text: "Denn so spricht mein Herr, Jahwe: \"Wenn ich dich zu einer verwüsteten und menschenleeren Stadt mache, wenn ich die Flut über dich kommen lasse, sodass du darin untergehst," },
      { number: 20, text: "dann musst du in die Totenwelt hinab zu den längst Verstorbenen, in die tiefste Tiefe zu den uralten Ruinen. Dann wirst du nie mehr bewohnt und hast keinen Platz mehr im Land der Lebendigen." },
      { number: 21, text: "Tödlichem Terror gebe ich dich preis, du wirst nicht mehr sein! Man wird dich suchen, aber nicht mehr finden. Das gilt für alle Zeit, spricht Jahwe, der Herr.\"" },
    ] },
    { number: 27, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Klagelied über den Untergang von Tyrus" },
      { number: 2, text: "\"Du Mensch, stimm ein Klagelied über Tyrus an:" },
      { number: 3, text: "Zur Stadt, die den Zugang zum Meer beherrscht, / die mit den Seevölkern Handel treibt, / spricht Jahwe, der Herr: / Du Tyrus, du sagst: / 'Ich bin die vollkommene Schönheit!'" },
      { number: 4, text: "Dein Zuhause ist das Meer, / deine Erbauer haben dich zu einem Schmuckstück gemacht." },
      { number: 5, text: "Deine Planken sind Zypressen vom Hermon* / und eine Zeder vom Libanon dein Mast.", footnotes: ["Hermon. Wörtlich: Senir, der amoritische Name für das Hermongebirge. Gemeint sind die Berge des Antilibanon."] },
      { number: 6, text: "Deine Ruder sind aus Eichen von Baschan, / die Aufbauten: Elfenbein und Buchsbaumholz von den Inseln der Zyprer." },
      { number: 7, text: "Bunte Leinwand aus Ägypten diente als Segel und Banner für dich. / Ein Sonnendach aus Purpur, blau und rot, / das brachten deine Händler aus Elischa*.", footnotes: ["Elischa war eine Stadt an der Ostküste von Zypern und gleichzeitig der älteste Name von Zypern."] },
      { number: 8, text: "Deine Ruderer stammten aus Sidon* und Arwad*, / und deine Besten, Tyrus, standen am Steuer.", footnotes: ["Sidon und Tyrus waren die wichtigsten Hafenstädte Phöniziens (heute: Libanon).", "Arwad. Inselstadt nördlich von Sidon."] },
      { number: 9, text: "Die Ältesten von Byblos* fuhren mit, / und seine erfahrenen Männer dichteten die Lecks. / Aus aller Herren Länder kamen Schiffe und tauschten Waren bei dir.", footnotes: ["Byblos. Hebräisch: Gebal. Wichtige Stadt zwischen Sidon und Arwad."] },
      { number: 10, text: "Männer aus Persien waren in deinem Heer, / aus Lydien und Libyen kamen deine Soldaten. / Ihre Schilde und Helme hängten sie in dir auf / und verliehen dir prächtigen Glanz." },
      { number: 11, text: "Männer aus Arwad verstärkten dein Heer / und standen auf deinen Mauern. / Wächter auf den Türmen waren Leute aus Gammad*. / Ihre Schilde hängten sie an deine Zinnen / und machten so deine Schönheit perfekt.\"", footnotes: ["Die Lage von Gammad ist nicht bekannt."] },
      { number: 12, text: "Tarschisch* kaufte deine Waren, denn du hattest viele Handelsgüter. Es lieferte dir dafür Silber, Eisen, Zinn und Blei.", footnotes: ["Tarschisch.Von Tyrus gegründete südspanische Küstenstadt."] },
      { number: 13, text: "Händler aus Griechenland, Tubal und Meschech* tauschten Sklaven und Kupferwaren in dir.", footnotes: ["Tubal und Meschech.Königreiche im nördlichen Kleinasien zwischen dem Schwarzen und dem Kaspischen Meer."] },
      { number: 14, text: "Die von Bet-Torgama* brachten Zug- und Reitpferde und Maulesel auf deine Märkte.", footnotes: ["Bet-Torgama war wahrscheinlich die Hauptstadt des anatolischen Königreiches Kammanu, das aus hetitischen und assyrischen Quellen bekannt ist."] },
      { number: 15, text: "Die Kaufleute von Rhodos und die Bewohner vieler Küsten trieben Handel mit dir. Sie brachten Elfenbein und Ebenholz." },
      { number: 16, text: "Die Edomiter* kauften aus deinem reichen Angebot und lieferten dafür Rubine, roten Purpur, bunte Stoffe und feinstes Leinen, Korallen und Edelsteine.", footnotes: ["Die Edomiter waren Nachkommen Esaus und bewohnten das Land östlich der Araba und südlich vom Toten Meer."] },
      { number: 17, text: "Juda und Israel lieferten Weizen von Minnit*, Süßigkeiten und Honig, Öl und duftendes Harz.", footnotes: ["Minnit. Stadt in Ammon, nordöstlich vom Toten Meer."] },
      { number: 18, text: "Auch die Händler aus Damaskus kauften aus deinem überreichen Angebot und lieferten dafür Wein aus Helbon* und Wolle aus Zahar*.", footnotes: ["Helbon liegt nördlich von Damaskus und ist auch heute noch ein Weinbauzentrum.", "Zahar liegt nordwestlich von Damaskus und ist heute noch ein Weidegebiet."] },
      { number: 19, text: "Die Daniter und Griechen von Usal* brachten Eisenwaren, Zimt und andere Gewürze zum Tausch.", footnotes: ["Usal Das Gebiet ist unbekannt."] },
      { number: 20, text: "Die Leute von Dedan* verkauften dir Satteldecken.", footnotes: ["Dedan war wahrscheinlich eine Wegstation auf der Weihrauchroute von Südarabien nach Syrien. Es kann auch einen arabischen Stamm meinen."] },
      { number: 21, text: "Die Scheiche von Arabien und Kedar* standen als Aufkäufer in deinem Dienst für Mastlämmer, Schaf- und Ziegenböcke.", footnotes: ["Scheiche von Arabien und Kedar. Nomadisierende Händler der arabischen Wüste."] },
      { number: 22, text: "Die Kaufleute von Saba* und Ragma* trieben Handel mit dir und tauschten die kostbarsten duftenden Öle, viele Arten von Edelsteinen und Gold gegen deine Waren ein.", footnotes: ["Saba liegt in der südwestlichen Ecke von Arabien, dem heutigen Jemen.", "Ragma ist eine Stadt in Südarabien."] },
      { number: 23, text: "Die Leute von Haran*, Kanne*, Eden* und Saba, von Assur* und ganz Medien trieben Handel für dich", footnotes: ["Haran war eine der bekanntesten Städte im Altertum, berühmt für seinen Handel und die Verehrung des Mondgottes. Sie liegt in der östlichen Türkei.", "Kanne lag irgendwo in Mesopotamien, es wird manchmal mit Kalne identifiziert.", "Eden war ein Gebiet südlich von Haran.", "Hier ist mit Assur wohl die Stadt südlich von Ninive gemeint."] },
      { number: 24, text: "mit prächtigen Gewändern, Mänteln aus blauem Purpur, mit bunten Stoffen und Teppichen aus Mischgewebe, mit fest gedrehten Tauen." },
      { number: 25, text: "Hochseeschiffe waren deine Karawanen und brachten dir diese Güter. Du wurdest reich und mächtig auf deiner Insel." },
      { number: 26, text: "Deine Ruderer brachten dich in viele Gewässer.Doch der Ostwind zerstörte deine Flotte auf allen Meeren." },
      { number: 27, text: "Dein Reichtum, deine Waren, dein Handelsgut, deine Seeleute und Matrosen, deine Schiffsbauer und deine Händler, all deine Soldaten und das ganze Volk in dir – sie alle stürzen mit dir ins Meer." },
      { number: 28, text: "Vom Jammergeschrei deiner Seeleute erbebt das Land um dich herum." },
      { number: 29, text: "Alle deine Ruderer, die Seeleute und Matrosen verlassen ihre Schiffe und bleiben an Land." },
      { number: 30, text: "Sie schreien laut und klagen bitterlich, sie streuen Staub auf ihre Köpfe und wälzen sich in Asche," },
      { number: 31, text: "sie scheren sich eine Glatze und ziehen den Trauersack an. Sie weinen um dich aus verbitterter Seele und halten die Totenklage über dich." },
      { number: 32, text: "In ihrem Jammer stimmen sie ein Klagelied über dich an:\"Wer konnte sich je mit Tyrus vergleichen, / der Stadt, von Wogen umspült? / Und nun: Totenstille.\"" },
      { number: 33, text: "Weil deine Waren über die Meere kamen, hast du viele Völker satt gemacht. Durch die Menge deiner Schätze und deinen Handel hast du die Könige der Erde reich gemacht." },
      { number: 34, text: "Jetzt liegst du zerbrochen im Meer, in Wassertiefen verschwunden, deine Handelswaren und all dein Volk in dir sind versunken." },
      { number: 35, text: "Alle Bewohner der Küsten sind entsetzt über dich, ihren Königen stehen die Haare zu Berge. Verstört sind ihre Gesichter." },
      { number: 36, text: "Die Händler wenden sich mit Schaudern ab. Zu einem Bild des Schreckens bist du geworden. Für alle Zeiten ist es aus mit dir." },
    ] },
    { number: 28, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Gegen den Herrscher von Tyrus" },
      { number: 2, text: "\"Du Mensch, sag zum Fürsten von Tyrus: So spricht Jahwe, der Herr: Du wurdest überheblich und sagtest: 'Ein Gott bin ich, einen Göttersitz habe ich mitten im Meer!' Obwohl du nur ein Mensch bist und kein Gott, setztest du deinen Verstand dem eines Gottes gleich." },
      { number: 3, text: "Gewiss, du bist weiser als Daniel. / Kein Geheimnis ist dir verborgen." },
      { number: 4, text: "Durch Weisheit und Verstand hast du dir Reichtum erworben, / hast Gold und Silber in deine Schatzkammern geschafft." },
      { number: 5, text: "Durch große Weisheit in deinem Handel / hast du deinen Reichtum vermehrt. / Doch dein Reichtum stieg dir zu Kopf / und du wurdest stolz.\"" },
      { number: 6, text: "Darum spricht Jahwe, der Herr:\"Weil du ein Herz dir gibst, / einem Gottesherzen gleich," },
      { number: 7, text: "darum führe ich Fremde gegen dich, / die Erbarmungslosesten der Völker. / Sie zücken das Schwert gegen deine prächtige Weisheit, / entweihen deinen strahlenden Glanz." },
      { number: 8, text: "In die Grube werden sie dich stürzen. / Du stirbst wie ein Erschlagener in deiner Festung im Meer." },
      { number: 9, text: "Wirst du dann auch noch sagen: 'Ich bin Gott', / wenn du deine Mörder siehst? / Du bist nur ein Mensch und nicht Gott / und bist in der Gewalt deiner Henker." },
      { number: 10, text: "Du stirbst wie Unbeschnittene* einen Tod durch Fremde, / denn ich habe es gesagt, spricht Jahwe, der Herr.\"", footnotes: ["Unbeschnittener. Verächtlicher Ausdruck für Menschen, die nicht zum Bund Gottes gehörten. Siehe 1. Mose 17,9-14!"] },
      { number: 11, text: "Das Wort Jahwes kam zu mir. Er sagte:" },
      { number: 12, text: "\"Du Mensch, stimm die Totenklage über den König von Tyrus an. Sag zu ihm: 'So spricht Jahwe, der Herr:Du warst die Vollkommenheit selbst, / voller Weisheit und makellos schön." },
      { number: 13, text: "Du lebtest im Garten Gottes, in Eden. / Dein Gewand war mit Edelsteinen jeder Art geschmückt: / Karneol, Topas und Diamant, / Türkis, Onyx und Jade, / Saphir, Rubin und Smaragd. / Deine Ohrringe waren aus Gold und Perlen. / Am Tag, als du geschaffen wurdest, / wurden auch sie bereitet." },
      { number: 14, text: "Du warst gesalbt als ein schirmender Cherub, / und ich hatte dich dazu gemacht. / Du warst auf Gottes heiligem Berg. / Zwischen den feurigen Steinen gingst du umher." },
      { number: 15, text: "Du bliebst vollkommen / vom Tag deiner Erschaffung an, / bis man Unrecht an dir fand." },
      { number: 16, text: "Durch deinen ausgedehnten Handel / wurdest du mit Frevel erfüllt / und bist in Sünde gefallen. / Da verstieß ich dich von Gottes Berg / und trieb dich ins Verderben, / du schirmender Cherub. / Ich tilgte dich aus der Mitte der feurigen Steine." },
      { number: 17, text: "Deine Schönheit hatte dich überheblich gemacht, / aus Eitelkeit hast du deine Weisheit zerstört. / Deshalb warf ich dich zu Boden, / gab dich Königen preis, / damit sie dich alle begaffen." },
      { number: 18, text: "Durch deine gewaltige Schuld, / durch unredliche Handelsgeschäfte / gabst du deine Heiligtümer preis. / So ließ ich Feuer aus dir fahren, das dich verzehrte. / Ich machte dich zu Asche auf der Erde / vor aller Augen, die dich sehen." },
      { number: 19, text: "Alle, die dich kennen unter den Völkern, / waren entsetzt über dich. / Zu einem Bild des Schreckens bist du geworden, / für alle Zeiten ist es aus mit dir.'\"" },
      { number: 20, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Gegen die Stadt Sidon" },
      { number: 21, text: "\"Du Mensch, blick in Richtung Sidon und weissage Folgendes:" },
      { number: 22, text: "'So spricht Jahwe, der Herr:Jetzt gehe ich gegen dich vor, Sidon, / und ich verherrliche mich in dir. / Dann wird man erkennen, dass ich es bin – Jahwe, / wenn ich mein Strafgericht vollstrecke / und mich heilig an dir erweise." },
      { number: 23, text: "Ich schicke Pest und Blut in deine Straßen, / viele fallen in dir, erschlagen vom Schwert, / das von allen Seiten über dich kommt. / Dann wird man erkennen, dass ich es bin – Jahwe!'\"" },
      { number: 24, text: "\"Dann droht dem Haus Israel kein stechender Dorn und kein schmerzender Stachel mehr von seinen schadenfreudigen Nachbarvölkern ringsum. Daran wird man erkennen, dass ich Jahwe, der Herr, bin.\"", heading: "Israel wird Frieden haben" },
      { number: 25, text: "So spricht Jahwe, der Herr: \"Wenn ich die Leute von Israel aus den Völkern sammle, unter die sie zerstreut worden sind, wenn ich mich so vor den Augen der Völker als der Heilige erweise, wenn sie wieder in dem Land wohnen, das ich meinem Diener Jakob gegeben habe," },
      { number: 26, text: "und in Sicherheit dort leben, Häuser bauen und Weinberge pflanzen, wenn ich an all den schadenfreudigen Nachbarvölkern mein Strafgericht vollstreckt habe, dann wird man erkennen, dass ich, Jahwe, ihr Gott bin.\"" },
    ] },
    { number: 29, verses: [
      { number: 1, text: "Am 12. Januar im zehnten Jahr unserer Verbannung* kam das Wort Jahwes zu mir. Er sagte:", heading: "Das Schicksal Ägyptens", footnotes: ["Januar. Wörtlich: im 10. Monat. Es war das Jahr 587 v. Chr. Ein Jahr und zwei Tage nach Beginn der Belagerung Jerusalems."] },
      { number: 2, text: "\"Du Mensch, wende dich gegen den Pharao, den König von Ägypten, und weissage Folgendes über ihn und ganz Ägypten:" },
      { number: 3, text: "'So spricht Jahwe, der Herr: Du bekommst es mit mir zu tun, Pharao, König von Ägypten, du großes Seeungeheuer, das im Nil und seinen Armen liegt und sagt:Mir gehört der Strom, / ich habe ihn selber gemacht." },
      { number: 4, text: "Ich schlage dir Haken durch die Kinnbacken und lasse die Fische deiner Ströme* an deinen Schuppen kleben und ziehe dich mit all den an dir hängenden Fischen aus ihnen heraus.", footnotes: ["Ströme bedeutet in Ägypten den Nil samt seinen Seitenarmen und Kanälen."] },
      { number: 5, text: "Dann werfe ich dich samt allen deinen Fischen in die Wüste. Dort bleibst du liegen, niemand sammelt dich auf. Den wilden Tieren und den Vögeln bist du zum Fraß vorgeworfen." },
      { number: 6, text: "Dann werden alle Bewohner Ägyptens erkennen, dass ich Jahwe bin. Denn du bist für das Haus Israel eine Stütze aus Schilfrohr gewesen:" },
      { number: 7, text: "Wenn sie dich in die Hand nahmen, knicktest du ein und rissest ihnen die ganze Schulter auf. Und wenn sie sich auf dich lehnten, zerbrachst du und durchbohrtest ihnen die Hüfte." },
      { number: 8, text: "Deshalb spricht Jahwe, der Herr: Pass auf! Ich bringe das Schwert über dich und rotte Menschen und Vieh in dir aus." },
      { number: 9, text: "Ägypten wird zu Wüste und Ödland werden, damit man erkennt, dass ich es bin – Jahwe! Weil du sagst:'Mir gehört der Strom, / ich habe ihn selber gemacht!'," },
      { number: 10, text: "deshalb gehe ich gegen dich und deine Ströme vor. Ich mache Ägypten zum dürren Ödland, zur Wüste, und zwar von Migdol* bis nach Assuan und an die Grenze von Nubien.*", footnotes: ["Migdol war eine Stadt im Norden Unterägyptens, in der auch Juden lebten. Assuan liegt 880 km südlich von Kairo.", "Nubien. Hebräisch: Kusch. Land am Oberlauf des Nil, südlich von Ägypten."] },
      { number: 11, text: "Weder Mensch noch Tier ziehen dort hindurch. 40 Jahre lang wird es nicht bewohnt sein." },
      { number: 12, text: "Ich mache Ägypten zur Wüste mitten in verwüsteten Ländern. Seine Städte werden 40 Jahre lang als Trümmerhaufen daliegen, und seine Bewohner werde ich in fremde Länder unter fremde Völker zerstreuen.*", footnotes: ["zerstreuen. Offenbar hat sich das erfüllt, als Nebukadnezzar Ägypten angriff, siehe Jeremia 43,8-13; 46,1-25. Es ist anzunehmen, dass er auch dort Städte zerstörte und Menschen nach Babylon deportierte. Andere werden in umliegende Länder geflohen sein, zum Beispiel Arabien oder Äthiopien."] },
      { number: 13, text: "Doch so spricht Jahwe, der Herr: Wenn die 40 Jahre vorbei sind," },
      { number: 14, text: "werde ich das Geschick Ägyptens zum Guten wenden und sie nach Oberägypten in das Land Patros, das Land ihrer Herkunft, zurückbringen.* Dort werden sie ein kleines Königreich sein,", footnotes: ["zurückbringen. Offenbar durften die Ägypter während der Regierungszeit des Kyrus von Persien (559-530 v.Chr.), der auch Israel die Rückkehr erlaubte, wieder in ihre Heimat zurückkehren."] },
      { number: 15, text: "schwächer als alle anderen Königreiche. Es wird sich nicht mehr über andere Völker erheben, denn ich vermindere ihre Zahl, damit sie nicht mehr über andere Völker herrschen können." },
      { number: 16, text: "Dann wird sich das Haus Israel auch nicht mehr auf sie verlassen und sich an sie hängen, was mich an ihre Schuld erinnern würde. Und man wird erkennen, dass ich, Jahwe, der Herr, bin.'\"" },
      { number: 17, text: "Am 1. April* im 27. Jahr unserer Verbannung kam das Wort Jahwes zu mir. Er sagte:", heading: "Tyrus, Ägypten und Nebukadnezzar", footnotes: ["April. Wörtlich: im 1. Monat. Im Jahr 571 v. Chr., 15 Jahre nach der Eroberung Jerusalems."] },
      { number: 18, text: "\"Du Mensch, König Nebukadnezzar von Babylon hat sein Heer gegen Tyrus eine schwere Arbeit tun lassen. Jeder Kopf ist dabei kahl geworden und jede Schulter blank gescheuert. Aber Lohn für ihre schwere Mühe haben er und sein Heer dort nicht erhalten.*", footnotes: ["Lohn ... nicht erhalten. Nebukadnezzar belagerte Tyrus 15 Jahre lang, von 586-571 v.Chr. und fand dann eine fast leere Stadt vor, weil sich die Einwohner mit Booten auf die vorgelagerte Insel gerettet hatten und dort eine neue Stadt befestigten."] },
      { number: 19, text: "Darum spricht Jahwe, der Herr: Passt auf! Ich gebe König Nebukadnezzar von Babylon das Land Ägypten. Der ganze Reichtum Ägyptens wird ihm zufallen. Er wird das Land ausplündern, und sein Heer wird reiche Beute machen. Das wird ihr Lohn sein." },
      { number: 20, text: "Weil sie für mich gearbeitet haben, gebe ich ihnen das Land Ägypten als Lohn, spricht Jahwe, der Herr." },
      { number: 21, text: "An dem Tag werde ich auch dem Haus Israel wieder Kraft verleihen, und dir gebe ich Freimut, zu den Leuten zu reden. Sie sollen erkennen, dass ich bin, der ich bin – Jahwe!\"" },
    ] },
    { number: 30, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Das Strafgericht über Ägypten" },
      { number: 2, text: "\"Du Mensch, weissage Folgendes: 'So spricht Jahwe, der Herr:Jammert und schreit: / O, welch ein Tag!" },
      { number: 3, text: "Denn nah ist der Tag, / nah der Tag Jahwes, / ein Tag dunkler Wolken. / Für die Völker hat die Stunde geschlagen." },
      { number: 4, text: "Das Schwert dringt ein in Ägypten. / Zittern überfällt die Nubier, / wenn Ägypter erschlagen fallen, / wenn man ihre Schätze wegschleppt / und ihre Festungswerke zerstört." },
      { number: 5, text: "Söldner aus Nubien, Libyen und Lydien und das ganze Völkergemisch, die Männer aus Kub und die Söhne aus dem Land meines Bundes werden mit ihnen durch das Schwert niedergemacht.'" },
      { number: 6, text: "So spricht Jahwe: 'Alle Helfer Ägyptens müssen fallen mit seiner Armee, dem Stolz seiner Macht. Von Migdol bis Assuan liegen die Erschlagenen, spricht Jahwe, der Herr." },
      { number: 7, text: "Ägypten wird zur Wüste werden mitten in verwüsteten Ländern, seine Städte werden Trümmerhaufen sein." },
      { number: 8, text: "Wenn ich Feuer an Ägypten lege und alle seine Unterstützer zerschmettere, wird man erkennen, dass ich es bin – Jahwe!" },
      { number: 9, text: "An jenem Tag schicke ich meine Boten auf Schiffen los, um das sichere Nubien aufzuschrecken. Ein Zittern überfällt sie am Gerichtstag Ägyptens. Passt auf! Genauso wird es kommen.'" },
      { number: 10, text: "So spricht Jahwe, der Herr: 'Ja, ich werde den Prunk Ägyptens wegschaffen lassen durch Nebukadnezzar, den König von Babylon." },
      { number: 11, text: "Die gewalttätigsten Völker wird er gegen Ägypten heranführen. Sie werden ihre Schwerter gegen Ägypten ziehen, das Land verwüsten und es mit Erschlagenen füllen." },
      { number: 12, text: "Ich werde den Nil und seine Arme trockenlegen und das Land in die Hand grausamer Menschen geben. Durch Fremde verwandle ich das blühende Land in eine Wüste. Das sage ich, Jahwe.'" },
      { number: 13, text: "So spricht Jahwe, der Herr: 'Ja, ich werde die Götzen vernichten! Verschwinden lasse ich die Nichtse aus Memphis*! Ägypten soll keinen Herrscher mehr haben, und ich bringe Furcht in dieses Land.", footnotes: ["Memphis war die alte Hauptstadt Ägyptens 21 km südlich vom heutigen Kairo."] },
      { number: 14, text: "Patros* werde ich verwüsten, und Zoan* brenne ich nieder. Ich vollstrecke das Gericht an Theben*.", footnotes: ["Patros ist Oberägypten, das Land links und rechts des Nil vom heutigen Kairo bis Assuan.", "Zoan ist eine Stadt im nordöstlichen Nildelta, am Menzale-See. Die Griechen nannten sie Tanis, heute heißt sie San-el-Hagar.", "Theben war die Hauptstadt Oberägyptens, heute: Luxor und Karnak, 530 km stromaufwärts von Kairo entfernt."] },
      { number: 15, text: "Mein Zorn trifft Sin*, das Bollwerk Ägyptens, und den Prunk von Theben rotte ich aus.", footnotes: ["Sin wird gewöhnlich mit der Hafenstadt Pelusium gleichgesetzt, die östlich vom Nildelta am Mittelmeer liegt."] },
      { number: 16, text: "Ich setze ganz Ägypten in Brand. Sin wird sich in Krämpfen winden, und Theben wird aufgebrochen sein. Memphis lebt in ständiger Angst." },
      { number: 17, text: "Die jungen Männer aus Heliopolis und Bubastis* werden mit dem Schwert erschlagen, und die übrigen kommen in Gefangenschaft.", footnotes: ["Bubastis war eine Zeit lang Hauptstadt von Unterägypten. Die Stadt, in der die katzenköpfige Göttin Bastet verehrt wurde, lag 64 km nordöstlich von Kairo."] },
      { number: 18, text: "In Tachpanhes* wird der Tag sich verfinstern, wenn ich dort die Joche Ägyptens zerbreche und seiner stolzen Macht ein Ende setze. Eine dunkle Wolke wird es bedecken, und seine Tochterstädte müssen in die Gefangenschaft.", footnotes: ["Tachpanhes war eine Grenzfestung gegen Syrien und Israel in der Nähe von Pelusium, im äußersten Nordosten von Ägypten."] },
      { number: 19, text: "So werde ich mein Strafgericht an Ägypten vollziehen, damit man erkennt, dass ich es bin – Jahwe!'\"" },
      { number: 20, text: "Am 7. April* im 11. Jahr unserer Verbannung kam das Wort Jahwes zu mir. Er sagte:", footnotes: ["April. Wörtlich: im 1. Monat. Es war das Jahr 587 v.Chr."] },
      { number: 21, text: "\"Du Mensch, ich habe dem Pharao, dem König von Ägypten, den Arm gebrochen. Man hat ihn nicht geschient und nicht verbunden, man hat ihm keine Heilung gegönnt, damit er wieder zu Kräften kommt. Nie mehr soll er zum Schwert greifen." },
      { number: 22, text: "Darum spricht Jahwe, der Herr: Passt auf! Ich werde gegen den Pharao, den König von Ägypten, vorgehen. Ich breche ihm die Arme, auch den, der schon gebrochen ist, und lasse das Schwert seiner Hand entfallen." },
      { number: 23, text: "Ich zerstreue die Ägypter unter die Völker, versprenge sie in fremde Länder." },
      { number: 24, text: "Aber die Arme des Königs von Babylon mache ich stark und gebe ihm mein Schwert in die Hand. Die Arme des Pharao jedoch zerbreche ich, dass er wie ein zu Tode Getroffener sich vor ihm windet und stöhnt." },
      { number: 25, text: "Ja, die Arme des Königs von Babylon mache ich stark, während die Arme des Pharao kraftlos herabfallen, damit man erkennt, dass ich es bin – Jahwe, wenn ich mein Schwert dem König von Babylon in die Hand gebe, damit er es gegen Ägypten gebraucht." },
      { number: 26, text: "Ich zerstreue die Ägypter unter die Völker, versprenge sie in fremde Länder, damit man erkennt, dass ich es bin – Jahwe!\"" },
    ] },
    { number: 31, verses: [
      { number: 1, text: "Am 1. Juni im 11. Jahr unserer Verbannung* kam das Wort Jahwes zu mir. Er sagte:", heading: "Der Pharao: Gleichnis vom prächtigen Baum", footnotes: ["... Verbannung. Wörtlich: des 3. Monats."] },
      { number: 2, text: "\"Du Mensch, sag zum Pharao, dem König von Ägypten, und zu seiner lärmenden Menge:'Wem kamst du gleich in deiner Größe?" },
      { number: 3, text: "Schau dir Assur* an! / Es war wie eine Zeder auf dem Libanon. / Die Pracht ihrer Äste gab reichlichen Schatten. / Hoch war ihr Wuchs, / ihr Wipfel stieß an die Wolken.", footnotes: ["Assyrien oder Assur (nach der Hauptstadt genannt) war das einzige mesopotamische Volk, das Ägypten bis dahin erobert hatte (633 v.Chr., siehe Nahum 3,8-10), und auch diese Weltmacht war durch Babylon zerstört worden, was damals auch auf Ägypten zukam. Es besteht keine Notwendigkeit, den Text zu verändern, wie es manche Übersetzungen tun."] },
      { number: 4, text: "Das Wasser machte sie groß, / das Grundwasser trieb sie hoch, / Ströme flossen rings um die Pflanzen, / schickten Wasser zu allen Bäumen im Feld." },
      { number: 5, text: "Darum wuchs sie höher als alle anderen Bäume / und breitete ihre vielen Äste weit aus, / denn sie hatte so viel Wasser." },
      { number: 6, text: "Die Vögel bauten Nester in den Zweigen, / und das Wild warf seine Jungen unter ihrem Schutz. / Ganze Völker wohnten in ihrem Schatten." },
      { number: 7, text: "Schön war sie in ihrer Größe und ihrem breiten Geäst, / denn ihre Wurzeln hatten viel Wasser." },
      { number: 8, text: "Keine Zeder im Garten Gottes glich ihr, / keine Zypresse hatte Zweige wie sie, / keine Platane so mächtige Äste. / Kein Baum in Gottes Garten war so schön wie sie." },
      { number: 9, text: "Ich hatte sie so schön gemacht mit ihren zahlreichen Zweigen, / dass alle in Eden sie beneideten, / alle Bäume in Gottes Paradies.'" },
      { number: 10, text: "Doch nun spricht Jahwe, der Herr: 'Weil sie so hoch gewachsen ist, weil sie ihren Wipfel bis zwischen die Wolken ausstreckte und ihre Größe ihr zu Kopf gestiegen ist," },
      { number: 11, text: "liefere ich sie dem mächtigsten Herrscher der Völker aus. Er wird sie nach seinem Belieben behandeln. Wegen ihrer Gottlosigkeit habe ich sie verstoßen." },
      { number: 12, text: "Fremde werden sie umhauen, die gewalttätigsten Völker werfen sie auf die Berge hin. Ihre abgeschlagenen Zweige füllen Täler und Bachrinnen aus. Und die Völker, die in ihrem Schatten gewohnt haben, ergreifen die Flucht." },
      { number: 13, text: "Auf ihren umgefallenen Stamm setzen sich die Vögel, und das Wild läuft über die Äste." },
      { number: 14, text: "Das geschieht, damit kein Baum am Wasser sich mehr überhebt und seinen Wipfel bis zwischen die Wolken streckt. Denn alle werden dem Tod ausgeliefert und müssen unter die Erde ins Grab, wo die Menschen sind.'" },
      { number: 15, text: "So spricht Jahwe, der Herr: 'An dem Tag, an dem ich die Zeder ins Totenreich stürzte, habe ich die Tiefe in Trauer versetzt; wegen ihr hielt ich die Ströme zurück und hemmte die Flüsse, wegen ihr hüllte ich den Libanon in Trauer, und wegen ihr verdorrten die Bäume im Wald." },
      { number: 16, text: "Als ich die Zeder mit gewaltigem Getöse in die Totenwelt stürzte – zusammen mit allen, die ins Grab müssen, – zitterten die Völker vor Angst. Und dort, im Land der Tiefe, trösteten sich die Bäume von Eden, die Prachtbäume des Libanon, die am Wasser standen, dass auch sie ihr Schicksal teilt." },
      { number: 17, text: "Auch sie waren mit ihr ins Totenreich gestürzt, zu den vom Schwert Erschlagenen. Und alle Nationen, die im Schatten der Zeder wohnten, kamen um.'" },
      { number: 18, text: "Welcher von den Bäumen Edens war so groß und prächtig wie du? Und doch musst du mit all den Bäumen von Eden unter die Erde. Dort wirst du liegen unter Unbeschnittenen und vom Schwert Erschlagenen. So geht es dem Pharao samt seinem lärmenden Gefolge, spricht Jahwe, der Herr.\"" },
    ] },
    { number: 32, verses: [
      { number: 1, text: "Am 1. März* im 12. Jahr unserer Verbannung kam das Wort Jahwes zu mir. Er sagte:", heading: "Ein Klagelied über den Pharao", footnotes: ["März. Wörtlich: im 12. Monat. Es handelt sich um das Jahr 585 v. Chr., das Jahr nach der Eroberung Jerusalems."] },
      { number: 2, text: "\"Du Mensch, stimm folgende Totenklage über den Pharao, den König von Ägypten, an:'Ein Junglöwe unter den Völkern warst du, / wie ein Drache in den Seen. / Du sprudeltest in deinen Strömen, / trübtest das Wasser mit deinen Füßen / und wühltest die Ströme auf." },
      { number: 3, text: "So spricht Jahwe, der Herr: / Durch ein Heer von vielen Völkern / spanne ich mein Netz für dich auf. / Sie ziehen dich in meinem Fanggarn heraus." },
      { number: 4, text: "Und ich werfe dich aufs Land, / schleudere dich aufs freie Feld, / dass sich die Vögel auf dich setzen / und die Raubtiere dich fressen." },
      { number: 5, text: "Dein Leichnam wird die Berge bedecken, / und die Täler sind mit deinem Aas gefüllt." },
      { number: 6, text: "Bis zu den Bergen hin / tränke ich das Land mit deinem Blut, / die Kanäle werden voll von dir sein." },
      { number: 7, text: "Wenn ich dich erlöschen lasse, / bedecke ich den Himmel. / Ich verdunkle seine Sterne, / überziehe die Sonne mit Wolken / und lasse den Mond nicht mehr leuchten." },
      { number: 8, text: "Alle leuchtenden Lichter am Himmel / verdüstere ich wegen dir / und lege Finsternis über dein Land, / spricht Jahwe, der Herr." },
      { number: 9, text: "Ich bekümmere das Herz vieler Völker, / wenn ich deinen Sturz den Nationen vermelde, / selbst denen, die du nie kanntest." },
      { number: 10, text: "Ich flöße den Völkern Entsetzen ein. / Ihren Königen stehen die Haare zu Berge, / wenn sie mich das Schwert schwingen sehen. / Sie zittern um ihr Leben am Tag deines Falls." },
      { number: 11, text: "Denn so spricht Jahwe, der Herr: / Über dich kommt das Schwert des Königs von Babel." },
      { number: 12, text: "Deine lärmende Menge fällt / durch die Schwerter von Helden erbarmungsloser Völker. / Sie verwüsten den Stolz von Ägypten / und seine ganze lärmende Pracht." },
      { number: 13, text: "Auch sein Vieh bringe ich um, / entferne es von seinem Gewässer. / Kein Menschenfuß wird das Wasser mehr trüben, / und kein Huf wühlt es mehr auf." },
      { number: 14, text: "Ihr Gewässer wird sich klären, / ihre Flüsse fließen wie Öl, / spricht Jahwe, der Herr." },
      { number: 15, text: "Wenn ich Ägypten zur Einöde mache, / das Land von seiner Fülle veröde / und alle seine Bewohner erschlage, / wird man erkennen, dass ich es bin – Jahwe!'" },
      { number: 16, text: "Das ist ein Klagelied, und man soll es als Totenklage singen. Die Frauen aller Völker sollen es anstimmen und damit über Ägypten und seine lärmende Menge klagen, spricht Jahwe, der Herr.\"" },
      { number: 17, text: "Am 15. April* im 12. Jahr unserer Verbannung kam das Wort Jahwes zu mir. Er sagte:", heading: "Ägypten im Totenreich", footnotes: ["April. Wörtlich: des Monats. Nach der LXX war es der erste Monat. Es handelt sich um das Jahr 586 v. Chr."] },
      { number: 18, text: "\"Du Mensch, stimm schon die Totenklage an über die lärmende Menge Ägyptens und schick sie so – zusammen mit den Töchtern mächtiger Völker – unter die Erde zu denen, die schon in der Grube liegen." },
      { number: 19, text: "'Wen hast du an Schönheit übertroffen? Stürze hinab und lege dich zu den Unbeschnittenen!'" },
      { number: 20, text: "Sie soll unter den vom Schwert Gefällten liegen. Für das Schwert ist Ägyptens ganze lärmende Menge bestimmt." },
      { number: 21, text: "Aus dem Totenreich heraus reden die mächtigen Führer mit Ägypten und seiner lärmenden Menge. Sie liegen schon da, die Unbeschnittenen und Schwertgefällten." },
      { number: 22, text: "Dort liegt Assur und sein ganzes Heer, alle erschlagen, vom Schwert gefällt. Rings um ihn her sind seine Gräber." },
      { number: 23, text: "Als sie noch lebten, haben sie Schrecken verbreitet. Nun sind ihnen Gräber in der tiefsten Grube gegeben." },
      { number: 24, text: "Dort liegt Elam* mit seiner lärmenden Menge, alle erschlagen, vom Schwert gefällt. Rings um ihn her sind seine Gräber. Als sie noch lebten, haben sie Schrecken verbreitet. Nun tragen sie die Schmach mit denen, die schon vor ihnen in die Grube geworfen wurden. Als Unbeschnittene sind sie in die Tiefe gestürzt.", footnotes: ["Elam ist die persische Provinz, deren Hauptstadt Susa war, siehe Nehemia 1,1; Ester 1,2."] },
      { number: 25, text: "Mitten unter Erschlagenen hat man ihm ein Lager angewiesen, samt seiner lärmenden Menge, deren Gräber rings um ihn her sind. Es sind alles Unbeschnittene, vom Schwert Gefällte. Weil sie Schrecken verbreitet haben, als sie noch lebten, tragen sie nun die Schmach mit denen, die vor ihnen in die Grube geworfen wurden. Mitten unter Erschlagenen liegt er." },
      { number: 26, text: "Dort liegt Meschesch-Tubal* mit seiner lärmenden Menge, Unbeschnittene, vom Schwert gefällt. Rings um ihn her sind seine Gräber. Als sie noch lebten, haben sie Schrecken verbreitet.", footnotes: ["Meschesch-Tubal. Völkerstämme im nördlichen Kleinasien zwischen dem Schwarzen und dem Kaspischen Meer."] },
      { number: 27, text: "Sie liegen nicht bei den Helden, die in der Vorzeit gefallen sind, die mit ihren Kriegswaffen zu den Toten kamen. Ihre Schwerter hatte man ihnen unter den Kopf gelegt, die Schilde auf ihre Knochen. Auch sie verbreiteten Schrecken, als sie noch lebten." },
      { number: 28, text: "So wirst auch du, Ägypten, unter den vom Schwert Gefällten liegen, unter Unbeschnittenen zerschmettert werden." },
      { number: 29, text: "Dort liegt Edom mit seinen Königen und all seinen Fürsten, die samt ihrer Heldenmacht zu den vom Schwert Gefällten gelegt wurden. Sie liegen unter Unbeschnittenen, bei denen, die in die Grube geworfen wurden." },
      { number: 30, text: "Dort liegen alle Fürsten des Nordens und alle Männer von Sidon. Sie liegen unter den Erschlagenen. Trotz ihrer Heldenkraft und des Schreckens, den sie verbreiteten, müssen sie ihre Schande tragen und liegen als Unbeschnittene bei den vom Schwert Gefällten und denen, die in die Grube geworfen wurden." },
      { number: 31, text: "Sie alle wird der Pharao sehen und sich über seine ganze lärmende Menge trösten. Der Pharao und sein ganzes Heer sind vom Schwert gefällt, spricht Jahwe, der Herr." },
      { number: 32, text: "Denn ich habe Schrecken vor ihm verbreitet, als sie noch lebten. Nun werden der Pharao und seine ganze lärmende Menge unter Unbeschnittenen und vom Schwert Gefällten liegen, spricht Jahwe, der Herr.\"" },
    ] },
    { number: 33, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "33-48: Gottes Herrlichkeit kehrt zurück\nDie Erneuerung von Gottes Volk (33-39)\nHesekiëls Wächterdienst" },
      { number: 2, text: "\"Du Mensch, sag zu den Leuten aus deinem Volk: 'Wenn ich das Schwert über ein Land kommen lasse und das Volk des Landes einen seiner Männer als Wächter wählt," },
      { number: 3, text: "wenn dieser die Gefahr kommen sieht und das Signalhorn* bläst, um das Volk zu warnen,", footnotes: ["Das Signalhorn (Hebräisch: Schofar) war aus den gewundenen Hörnern des männlichen Fettschwanzschafes hergestellt und brachte einen dumpfen, durchdringenden Ton hervor."] },
      { number: 4, text: "und wenn einer das Signal hört, sich aber nicht warnen lässt und deshalb umkommt, ist er selbst an seinem Tod schuld." },
      { number: 5, text: "Er hat das Signal gehört, aber nicht beachtet, und ist selber schuld. Lässt er sich aber warnen, rettet er sein Leben." },
      { number: 6, text: "Doch wenn der Wächter die Gefahr kommen sieht und nicht ins Horn stößt, um das Volk zu warnen, und wenn dann einer getötet wird, dann ist dies zwar die Strafe für dessen Schuld, aber den Wächter werde ich für seinen Tod verantwortlich machen.'" },
      { number: 7, text: "Mensch, dich habe ich zum Wächter über das Haus Israel bestellt. Du sollst das Wort von mir hören und sie von mir aus warnen." },
      { number: 8, text: "Wenn ich einem Menschen, der sich von mir gelöst hat, den Tod androhe, du sagst ihm aber nichts, um ihn vor seinem Weg zu warnen, so wird dieser Gottlose zwar sterben, wie er es verdient hat, aber dich werde ich für seinen Tod verantwortlich machen." },
      { number: 9, text: "Wenn du den Gottlosen jedoch vor seinem Weg warnst, damit er umkehrt, er sich aber nicht von seinem falschen Weg abbringen lässt, wird er wegen seiner Schuld sterben. Aber du hast dein Leben gerettet." },
      { number: 10, text: "Du Mensch, sag zu den Leuten von Israel: 'Ihr klagt mit dem Spruch: Unsere Vergehen und Sünden lasten auf uns, wir gehen daran zugrunde! Wie sollen wir da am Leben bleiben?'" },
      { number: 11, text: "Sag zu ihnen: 'So wahr ich lebe, spricht Jahwe, der Herr: Mir gefällt es nicht, wenn ein Schuldiger stirbt! Im Gegenteil: Ich freue mich, wenn er von seinem falschen Weg umkehrt und am Leben bleibt! Kehrt um! Verlasst eure bösen Wege! Warum wollt ihr denn sterben, ihr Leute von Israel?'" },
      { number: 12, text: "Und du, Mensch, sag den Leuten aus deinem Volk:An dem Tag, an dem ein Gerechter in Sünde fällt, wird ihn auch seine Gerechtigkeit nicht retten. Und an dem Tag, an dem ein Gottloser von seinem gottlosen Tun umkehrt, wird er nicht mehr zu Fall kommen. Der Gerechte aber kann trotz seiner Gerechtigkeit nicht am Leben bleiben, sobald er sündigt." },
      { number: 13, text: "Wenn ich zum Gerechten sage: 'Du wirst am Leben bleiben!', er aber im Vertrauen auf seine Gerechtigkeit Unrecht tut, dann zählt sein ganzes vorbildliches Leben nicht mehr. Weil er Unrecht getan hat, muss er sterben." },
      { number: 14, text: "Wenn ich zum Gottlosen sage: 'Du musst sterben!', er aber sein sündhaftes Leben aufgibt und nach Recht und Gerechtigkeit handelt," },
      { number: 15, text: "das Pfand zurückgibt, erstattet, was er sich angeeignet hat, nach den Ordnungen des Lebens lebt und kein Unrecht mehr tut, dann soll er am Leben bleiben und muss nicht sterben." },
      { number: 16, text: "Keine von den Sünden, die er früher begangen hat, wird ihm angerechnet werden. Weil er jetzt das Rechte tut, wird er am Leben bleiben." },
      { number: 17, text: "Doch die Leute in deinem Volk behaupten: 'Es ist nicht richtig, wie der Herr verfährt!' Dabei ist doch ihr eigener Weg nicht richtig." },
      { number: 18, text: "Wenn jemand, der im richtigen Verhältnis zu mir lebt, diese seine Gerechtigkeit aufgibt, und beginnt Unrecht zu tun, muss er dafür sterben." },
      { number: 19, text: "Und wenn ein Mensch, der sich von mir gelöst hat, seine Gottlosigkeit aufgibt und tut, was recht vor mir ist, wird er dafür am Leben bleiben." },
      { number: 20, text: "Und da sagt ihr: 'Das Verfahren des Herrn ist nicht recht.' Nein, jeder wird von mir nach seinem Tun gerichtet, ihr Leute von Israel!\"" },
      { number: 21, text: "Am 5. Januar im 12. Jahr unserer Verbannung* kam ein Flüchtling aus Jerusalem zu mir und sagte: \"Die Stadt ist gefallen!\"", heading: "Die Nachricht vom Fall Jerusalems", footnotes: ["Januar. Wörtlich: im 10. Monat. Es handelt sich um das Jahr 585 v. Chr."] },
      { number: 22, text: "Schon am Abend vorher hatte sich die Hand Jahwes auf mich gelegt und mich stumm gemacht. Als der Flüchtling dann am Morgen zu mir hereinkam, wurde mir die Sprache wiedergeschenkt, und ich konnte frei reden." },
      { number: 23, text: "Das Wort Jahwes kam zu mir. Er sagte:" },
      { number: 24, text: "\"Du Mensch, die Bewohner dieser Trümmer im Land Israel sagen: 'Abraham war auch nur ein Einzelner und nahm das Land in Besitz. Wir aber sind viele; uns gehört es also erst recht!'" },
      { number: 25, text: "Darum sag zu ihnen:So spricht Jahwe, der Herr: 'Ihr esst das Fleisch mit dem Blut, ihr blickt zu euren Götzen auf, ihr mordet – und dann wollt ihr das Land besitzen?" },
      { number: 26, text: "Ihr verlasst euch auf euer Schwert, tut gräuliche Dinge und schlaft mit den Frauen anderer Männer – und dann wollt ihr das Land besitzen?'" },
      { number: 27, text: "Sag ihnen Folgendes:'So wahr ich lebe', spricht Jahwe, der Herr, 'wer in den Ruinen haust, fällt unter dem Schwert, wer auf freiem Feld lebt, wird von wilden Tieren zerrissen, und wer auf Felsennester und in Höhlen geflohen ist, stirbt an der Pest!" },
      { number: 28, text: "Ich mache das Land zur Einöde, ich verwüste die Schutzwehr, auf die ihr so stolz seid. Die Berge Israels werden zu einer Wildnis, durch die niemand mehr wandert.'" },
      { number: 29, text: "Sie werden erkennen, dass ich bin, der ich bin – Jahwe, wenn ich das Land wegen ihrer abscheulichen Taten verwüste und zur Einöde mache.\"" },
      { number: 30, text: "\"Du Mensch, die Leute aus deinem Volk reden über dich. Sie stehen vor ihren Häusern zusammen und sagen zueinander: 'Kommt doch und lasst uns zum Propheten gehen und hören, was für ein Wort Jahwes herauskommt!'", heading: "Scheinheilige Zuhörer" },
      { number: 31, text: "Dann kommen sie zu dir, und du hast einen Volksauflauf. Sie setzen sich als mein Volk vor dich hin und hören deine Worte an, aber sie befolgen sie nicht. Sie tun so, als seien sie begierig danach, ihr Herz aber läuft ihrem Gewinn hinterher." },
      { number: 32, text: "Du bist ihnen wie einer, der mit schöner Stimme Liebeslieder singt und gut dazu spielen kann. So hören sie deine Reden an, nehmen sie aber nicht ernst." },
      { number: 33, text: "Wenn deine Worte dann aber eintreffen – und das wird mit Sicherheit geschehen –, werden sie erkennen, dass ein Prophet unter ihnen war.\"" },
    ] },
    { number: 34, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Die schlechten Hirten" },
      { number: 2, text: "\"Du Mensch, weissage gegen die Hirten Israels! Sprich zu ihnen:So spricht Jahwe, der Herr: 'Weh den Hirten Israels, die sich nur selbst versorgen! Müssen die Hirten nicht die Herde versorgen?" },
      { number: 3, text: "Ihr genießt die Milch, nehmt Wolle für eure Kleidung und schlachtet die besten Tiere, aber um die Herde kümmert ihr euch nicht." },
      { number: 4, text: "Den Schwachen habt ihr nicht geholfen, die Kranken nicht gesund gepflegt, gebrochene Glieder nicht geschient, versprengte Tiere nicht zurückgebracht und verloren gegangene nicht gesucht. Mit Härte und Gewalt habt ihr über sie geherrscht." },
      { number: 5, text: "Da verliefen sie sich, denn sie hatten ja keinen Hirten, und fielen Raubtieren zum Opfer. So zerstreuten sich" },
      { number: 6, text: "meine Schafe und irrten im ganzen Land umher, auf Bergen und Hügeln. Niemand fragte nach ihnen und niemand suchte sie.'" },
      { number: 7, text: "Darum ihr Hirten, hört das Wort Jahwes!" },
      { number: 8, text: "'So wahr ich lebe', spricht Jahwe, der Herr, 'so geht es nicht weiter! Meine Schafe wurden geraubt und von wilden Tieren gefressen, weil kein Hirt da war, denn meine Hirten haben nur für sich selbst gesorgt und nicht nach meinen Schafen gefragt.'" },
      { number: 9, text: "Darum hört das Wort Jahwes, ihr Hirten!" },
      { number: 10, text: "So spricht Jahwe, der Herr: 'Ich werde gegen die Hirten vorgehen und meine Schafe von ihnen zurückfordern. Ich setze sie ab. Sie dürfen meine Schafe nicht länger weiden. Sie sollen auch sich selbst nicht mehr weiden können. Meine Schafe reiße ich aus ihrem Rachen. Sie sollen ihnen nicht länger zum Fraß dienen.'\"" },
      { number: 11, text: "\"So spricht Jahwe, der Herr: 'Passt auf! Ich selbst werde jetzt nach meinen Schafen sehen und für sie sorgen.", heading: "Der gute Hirt" },
      { number: 12, text: "Wie ein Hirt seine Herde wieder zusammensucht, wenn sich die Schafe zerstreut haben, so will auch ich mich meiner Schafe annehmen. Ich hole sie aus allen Orten zurück, in die sie an jenem unheilvollen Tag versprengt worden sind." },
      { number: 13, text: "Ich führe sie aus den Völkern heraus, hole sie aus den Ländern zusammen und bringe sie in ihre Heimat zurück. Auf den Bergen Israels, in den Talgründen und an allen bewohnten Plätzen werde ich sie weiden lassen." },
      { number: 14, text: "Auf saftigen Wiesen lasse ich sie grasen, und auf den hohen Bergen Israels finden sie gute Weide- und Lagerplätze." },
      { number: 15, text: "Ich selbst will meine Schafe weiden und ruhen lassen, spricht Jahwe, der Herr." },
      { number: 16, text: "Die Verlorengegangenen will ich suchen, die Versprengten zurückbringen, die sich etwas gebrochen haben, will ich verbinden und die Kranken gesund pflegen, aber die Fetten und Starken werde ich beseitigen. Ich weide sie, wie es recht ist.'" },
      { number: 17, text: "Und zu euch, meinen Schafen, spricht Jahwe, der Herr: 'Passt auf! Ich werde zwischen Schaf und Schaf, zwischen Widdern und Böcken richten." },
      { number: 18, text: "Ist es euch nicht genug, eine so gute Weide abzugrasen? Müsst ihr auch noch die restliche Weide zerstampfen? Ihr trinkt das klare Wasser und trübt das restliche mit euren Hufen!" },
      { number: 19, text: "Meine Schafe sollen dann fressen, was eure Hufe zerstampft, und trinken, was sie verschmutzt haben?'" },
      { number: 20, text: "Darum spricht Jahwe, der Herr zu ihnen: 'Passt auf! Ich bin es, ich werde für Recht sorgen zwischen den fetten und mageren Tieren ." },
      { number: 21, text: "Weil ihr die Schwachen mit Seite und Schulter verdrängt und mit euren Hörnern gestoßen habt, bis ihr sie von der Herde weggetrieben hattet," },
      { number: 22, text: "will ich nun meinen Schafen zu Hilfe kommen. Sie sollen nicht länger eurer Willkür ausgeliefert sein. So werde ich für Recht zwischen den einzelnen Schafen sorgen.'\"" },
      { number: 23, text: "\"Dann werde ich einen einzigen Hirten über sie einsetzen, der sie weiden soll: meinen Diener David*. Ja, er wird sie weiden und ihr Hirt sein.", heading: "Das Reich des Friedens", footnotes: ["Diener David. Es wird ein Herrscher wie David sein, der auch aus seinem Geschlecht stammt, der Messias; siehe Psalm 89,4; Jeremia 23,5-6."] },
      { number: 24, text: "Ich selbst, Jahwe, werde ihr Gott sein, und mein Diener David wird der Fürst in ihrer Mitte sein. Ich, Jahwe, habe es gesagt!" },
      { number: 25, text: "Ich werde einen Bund des Friedens mit ihnen schließen und das Land von wilden Tieren befreien. Selbst in der Wüste können sie dann sicher wohnen und in den Wäldern schlafen." },
      { number: 26, text: "Ich werde sie und die ganze Umgebung meines Hügels segnen und den Regen fallen lassen zur rechten Zeit. Regengüsse des Segens werden es sein," },
      { number: 27, text: "so dass die Bäume und Felder reichen Ertrag bringen. Sie werden auf ihrem Grund und Boden sicher sein. Wenn ich die Stangen ihres Jochs zerbreche und sie aus der Gewalt ihrer Unterdrücker rette, werden sie erkennen, dass ich bin, der ich bin – Jahwe!" },
      { number: 28, text: "Sie werden nicht länger eine Beute der Völker sein und nicht länger von wilden Tieren gefressen werden. Nein, sie werden in Sicherheit wohnen, und niemand scheucht sie auf." },
      { number: 29, text: "Ich mache ihr Land zu einem berühmten Garten. Keiner von ihnen wird mehr verhungern; und den Spott der Völker werden sie nicht mehr ertragen müssen." },
      { number: 30, text: "Dann werden sie erkennen, dass ich, Jahwe, ihr Gott, bei ihnen bin, und sie, das Haus Israel, mein Volk sind, spricht Jahwe, der Herr." },
      { number: 31, text: "Ihr seid meine Herde, ihr Menschen seid die Herde, für die ich sorge, und ich bin euer Gott, spricht Jahwe, der Herr.\"" },
    ] },
    { number: 35, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Drohwort gegen das Bergland Edom" },
      { number: 2, text: "\"Du Mensch, wende dich gegen die Berge von Seïr und weissage gegen sie." },
      { number: 3, text: "Sag zu ihnen: So spricht Jahwe, der Herr:Pass auf, Bergland von Seïr*, gegen dich gehe ich vor! Ich werde dich meine Macht spüren lassen und mache dich zur Einöde, zu einem Bild des Schreckens.", footnotes: ["Bergland von Seïr. Siehe Hesekiel 25,8."] },
      { number: 4, text: "Deine Städte lege ich in Trümmer, und du selbst wirst Ödland sein. Du sollst erkennen, dass ich es bin – Jahwe!" },
      { number: 5, text: "Weil du in beständiger Feindschaft mit den Israeliten lebtest und sie erbarmungslos ans Messer geliefert hast, als das Unglück über sie hereinbrach und ihre Schuld das Ende herbeiführte," },
      { number: 6, text: "darum lasse ich dich bluten, so wahr ich lebe, spricht Jahwe, der Herr. Blut soll dich verfolgen! Weil du Blut vergossen hast ohne Scheu, soll Blut dich verfolgen!" },
      { number: 7, text: "Und das Gebirge Seïr mache ich zur Einöde, zu einem Bild des Schreckens, und rotte jeden aus, der dein Gebiet durchzieht." },
      { number: 8, text: "Deine Berge fülle ich mit Erschlagenen an. Auf deinen Hügeln, in Rinnen und in Tälern liegen dann vom Schwert Erschlagene." },
      { number: 9, text: "Zum ewigen Ödland mache ich dich. Niemand wird mehr in deinen Städten wohnen. Dann werdet ihr erkennen, dass ich es bin – Jahwe!" },
      { number: 10, text: "Weil du sagst: 'Die beiden Länder, Israel und Juda, gehören jetzt mir, und ich nehme sie in Besitz!', wo doch Jahwe dort war," },
      { number: 11, text: "darum, so wahr ich lebe, spricht Jahwe, der Herr: Mit dem gleichen leidenschaftlichen Zorn, mit dem du aus Hass gegen sie gewütet hast, werde ich gegen dich vorgehen, und wenn ich dich gerichtet habe, mich ihnen zu erkennen geben." },
      { number: 12, text: "Dann wirst du merken, dass ich, Jahwe, alle deine Lästerreden gehört habe. Du sagtest: 'Die Berge Israels sind verwüstet, ein gefundenes Fressen für uns!'" },
      { number: 13, text: "So habt ihr geprahlt und das Maul gegen mich aufgerissen. Ich habe es gehört." },
      { number: 14, text: "So spricht Jahwe, der Herr: Weil du dich über die Einöde freust, werde auch ich dich dazu machen!" },
      { number: 15, text: "Weil du dich freutest, dass Israels Besitz verwüstet war, werde auch ich dich zur Wüste machen; das Bergland von Seïr und ganz Edom soll zum Ödland werden. Dann wird man erkennen, dass ich es bin – Jahwe!\"" },
    ] },
    { number: 36, verses: [
      { number: 1, text: "\"Du Mensch, weissage über die Berge Israels! Sag: Ihr Berge Israels, hört das Wort Jahwes!", heading: "Verheißung für das Bergland Israel" },
      { number: 2, text: "So spricht Jahwe, der Herr: Weil die Feinde über euch sagen: 'Ha, die ewigen Höhen sind jetzt unser Besitz!'," },
      { number: 3, text: "weissage Folgendes: So spricht Jahwe, der Herr:Ja gerade deshalb, weil man euch verwüstet, weil man von allen Seiten nach euch geschnappt hat, so dass ihr jetzt Besitz der übrigen Völker seid, weil ihr ins Gerede gekommen und zum Gespött der Leute geworden seid," },
      { number: 4, text: "gerade deshalb hört das Wort Jahwes, ihr Berge Israels! So spricht Jahwe, der Herr, zu den Bergen und Hügeln, den Rinnen und Tälern, zu den verfallenen Ruinen und den verlassenen Städten, die von den Nachbarvölkern ausgeplündert und zum Spott geworden sind:" },
      { number: 5, text: "Mit Feuereifer habe ich gegen Edom und den Rest der Völker geredet, die sich voller Schadenfreude und Verachtung mein Land als Erbgut angeeignet und sein Weideland ausgeplündert haben." },
      { number: 6, text: "Weissage über das Land Israel und sage zu den Bergen und Hügeln, den Rinnen und Tälern:" },
      { number: 7, text: "So spricht Jahwe, der Herr: Ich selbst erhebe meine Hand und schwöre: 'Was eure Nachbarvölker euch angetan haben, wird auf sie selbst zurückfallen. Sie werden Schmach und Schande zu tragen haben!'" },
      { number: 8, text: "Doch ihr Berge Israels, ihr werdet wieder grünen und Frucht tragen, denn mein Volk kommt bald zurück." },
      { number: 9, text: "Passt auf, ich greife ein und wende mich euch zu! Dann ackert und sät man wieder auf euch." },
      { number: 10, text: "Ich werde die Menschen auf euch vermehren und zwar das ganze Volk Israel. Die Städte werden wieder bewohnt und die Ruinen aufgebaut sein." },
      { number: 11, text: "Menschen und Tiere lasse ich zahlreich werden; sie werden fruchtbar sein und sich vermehren. Ich mache euch bewohnt wie in früheren Zeiten und werde euch mehr Gutes tun als jemals zuvor. Dann werdet ihr erkennen, dass ich bin, der ich bin – Jahwe!" },
      { number: 12, text: "Ich lasse wieder Menschen auf euch gehen, nämlich mein Volk Israel. Die sollen euch als Erbgut besitzen. Und ihr werdet sie nie mehr kinderlos machen." },
      { number: 13, text: "So spricht Jahwe, der Herr: Weil sie zu euch Bergen Israels sagen: 'Du bist ein Land, das seine Bewohner verschlingt und deinem Volk die Kinder raubt!'," },
      { number: 14, text: "spricht Jahwe, der Herr: 'Das wird in Zukunft nicht mehr geschehen, du wirst niemand mehr verschlingen und dein Volk nicht mehr kinderlos machen!'" },
      { number: 15, text: "Ihr werdet nicht mehr anhören müssen, wie die Völker euch verhöhnen, ihr werdet ihren Spott nicht mehr ertragen müssen. Du wirst dein Volk nie mehr zum Stürzen bringen, spricht Jahwe, der Herr.\"" },
      { number: 16, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Erneuerung durch Gottes Geist" },
      { number: 17, text: "\"Du Mensch, als das Volk Israel noch in seinem Land wohnte, haben sie es durch ihr Tun und Treiben besudelt. Ihr Verhalten macht es unrein vor mir so wie die Monatsblutung eine Frau." },
      { number: 18, text: "Sie haben Blut im Land vergossen und es durch ihre Götzen besudelt. Da schüttete ich meinen Grimm über sie aus." },
      { number: 19, text: "Ich versprengte sie unter die Völker, zerstreute sie in fremde Länder. Ich bestrafte sie nach ihrem Tun und Treiben." },
      { number: 20, text: "Aber wohin sie auch kamen, brachten sie meinen heiligen Namen in Verruf, denn die Leute dort sagten: 'Das ist das Volk Jahwes, aber sie mussten aus seinem Land weg!'" },
      { number: 21, text: "Da tat es mir um meinen heiligen Namen leid, denn die Leute von Israel entweihten ihn, wohin sie auch kamen." },
      { number: 22, text: "Darum sage zum Haus Israel:So spricht Jahwe, der Herr: Ich mache es nicht wegen euch, ihr Leute von Israel, sondern ich greife wegen meines heiligen Namens ein, den ihr überall, wohin ihr unter den Völkern gekommen seid, in Verruf gebracht habt." },
      { number: 23, text: "Ich werde meinen großen Namen, den ihr unter den Völkern entweiht habt, wieder zu Ehren bringen. Und wenn ich mich vor den Augen der Völker an euch als heilig erweise, werden auch sie erkennen, dass ich es bin – Jahwe, spricht Jahwe, der Herr." },
      { number: 24, text: "Ich werde euch also aus den Völkern herausholen, euch aus allen Ländern einsammeln und euch auf euren Grund und Boden zurückbringen." },
      { number: 25, text: "Dann werde ich reines Wasser auf euch sprengen und euch so von allem Dreck und allen Götzen reinigen." },
      { number: 26, text: "Ich gebe euch ein neues Herz und einen neuen Geist: Das versteinerte Herz nehme ich aus eurer Brust und gebe euch ein lebendiges dafür." },
      { number: 27, text: "Ich lege meinen Geist in euch und bewirke, dass ihr meinen Gesetzen folgt und euch nach meinen Rechtsbestimmungen richtet." },
      { number: 28, text: "Ihr werdet in dem Land wohnen, das ich euren Vorfahren gegeben habe. Ihr werdet mein Volk sein, und ich, ich werde euer Gott sein!" },
      { number: 29, text: "Ich werde euch von allem Sündenschmutz befreien. Ich rufe das Korn herbei und lasse es wachsen und werde keine Hungersnot mehr über euch bringen." },
      { number: 30, text: "Ich vermehre die Früchte auf den Bäumen und den Ertrag der Felder, damit ihr von den anderen Völkern nicht mehr als Hungerleider verspottet werdet." },
      { number: 31, text: "Dann werdet ihr an euer böses Tun und Treiben von früher denken und vor euch selbst Ekel empfinden wegen eurer Sünden und Gräueltaten." },
      { number: 32, text: "Ich tue das nicht wegen euch, spricht Jahwe, der Herr, das sollt ihr wissen! Im Gegenteil: Ihr habt allen Grund, euch zu schämen, ihr Israeliten!" },
      { number: 33, text: "So spricht Jahwe, der Herr: Wenn ich euch von all eurer Schuld gereinigt habe, werde ich die Städte wieder bewohnt und die Ruinen aufgebaut sein lassen." },
      { number: 34, text: "Das verwüstete Land soll wieder bestellt werden und einem, der durchreist, nicht mehr als Einöde erscheinen." },
      { number: 35, text: "Dann wird man sagen: Dieses wüste Land ist wie der Garten Eden geworden, die verlassenen, verwüsteten und in Trümmern liegenden Städte sind bewohnt und gut befestigt." },
      { number: 36, text: "Dann werden die Völker, die um euch herum noch übrig geblieben sind, erkennen, dass ich, Jahwe, das Niedergerissene aufbaue und das Verwüstete neu bepflanze. Ich, Jahwe, habe es gesagt, und ich werde es auch tun!" },
      { number: 37, text: "So spricht Jahwe, der Herr: Ich werde den Leuten Israels auch diese Bitte noch erfüllen: Ich werde sie vermehren wie eine Herde Schafe." },
      { number: 38, text: "Die verödeten Städte werden so voller Menschen sein, wie Jerusalem zu seinen Festzeiten von Opferschafen wimmelt. Dann wird man erkennen, dass ich bin, der ich bin – Jahwe!\"" },
    ] },
    { number: 37, verses: [
      { number: 1, text: "Die Hand Jahwes legte sich auf mich. Er entführte mich im Geist ins Freie und setzte mich mitten in einer Talebene ab, die voller Menschenknochen lag.", heading: "Menschenknochen werden lebendig" },
      { number: 2, text: "Er führte mich rings um sie herum. Es waren unzählige, und alle waren völlig ausgetrocknet." },
      { number: 3, text: "Dann fragte er mich: \"Du Mensch, werden diese Knochen wohl wieder lebendig?\" – \"Mein Herr, Jahwe, du weißt es\", erwiderte ich." },
      { number: 4, text: "Da befahl er mir: \"Weissage über diese Knochen und ruf ihnen zu: 'Ihr vertrockneten Knochen, hört das Wort Jahwes!" },
      { number: 5, text: "So spricht Jahwe, der Herr, zu diesen Knochen: Passt auf, ich bringe Atem und Geist in euch, dass ihr lebt!" },
      { number: 6, text: "Ich lege Sehnen an euch, lasse Fleisch über euch wachsen und überziehe euch mit Haut. Dann gebe ich meinen Geist in euch, dass ihr lebt. Ihr sollt erkennen, dass ich bin, der ich bin – Jahwe!'\"" },
      { number: 7, text: "Ich weissagte, wie es mir befohlen war. Während ich das tat, entstand ein Geräusch, ja ein richtiges Getöse. Die Knochen rückten zusammen, Gebein an Gebein." },
      { number: 8, text: "Dann sah ich auf einmal, wie Sehnen und Muskeln darauf wuchsen und sich eine Haut darüber bildete. Doch es war noch kein Atem und kein Geist in ihnen." },
      { number: 9, text: "Da sagte er zu mir: \"Weissage dem Geist, Mensch, weissage und sprich zu dem Geist: 'So spricht Jahwe, der Herr: Komm von den vier Winden* her, du Lebensgeist, und hauche diese Erschlagenen an, dass Leben in sie kommt!'\"", footnotes: ["Winden. In diesem Kapitel steht das hebräische Wort ruach (siehe 1. Mose 1,2; 2,7), das gleichzeitig Geist, Lebensatem und Wind bedeutet. Die vier Winde meinen die vier Himmelsrichtungen."] },
      { number: 10, text: "Ich weissagte, wie es mir befohlen war. Da kam der Lebensgeist in sie, sie wurden lebendig und standen auf. Es war ein riesiges Heer." },
      { number: 11, text: "Er sagte zu mir: \"Du Mensch, diese Totenknochen sind das Volk Israel. Noch sagen sie: 'Unsere Knochen sind vertrocknet, unsere Hoffnung ist verloren, es ist aus mit uns!'" },
      { number: 12, text: "Darum weissage ihnen Folgendes: 'So spricht Jahwe, der Herr: Passt auf, ich öffne eure Gräber und hole euch, mein Volk, heraus und bringe euch ins Land Israel zurück!" },
      { number: 13, text: "Ihr werdet erkennen, dass ich es bin – Jahwe, wenn ich eure Gräber öffne und euch, mein Volk, heraushole." },
      { number: 14, text: "Ich gebe meinen Geist in euch, dass Leben in euch kommt, und setze euch in euer Land. Dann werdet ihr erkennen, dass ich, Jahwe, es gesagt und auch getan habe, spricht Jahwe.'\"" },
      { number: 15, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Israel und Juda wieder vereint" },
      { number: 16, text: "\"Du Mensch, nimm dir ein Stück Holz und schreibe darauf: 'Juda und die zu ihm gehörenden Leute von Israel'! Nimm ein zweites Stück Holz und schreibe darauf: 'Josef, Efraïm und das ganze Volk Israel, das zu ihm gehört'!" },
      { number: 17, text: "Dann halte beide zusammen, dass sie in deiner Hand wie ein einziges Stück Holz aussehen." },
      { number: 18, text: "Und wenn deine Landsleute dich fragen: 'Willst du uns nicht erklären, was das bedeuten soll?'," },
      { number: 19, text: "dann sag zu ihnen: 'So spricht Jahwe, der Herr: Seht, ich nehme das Holz Josefs, das für Efraïm und die Stämme Israels steht, die zu ihm gehören, und füge es mit dem Holz Judas zusammen, sodass sie in meiner Hand eins werden.'" },
      { number: 20, text: "Die Hölzer, auf die du geschrieben hast, sollst du vor ihren Augen in deiner Hand halten." },
      { number: 21, text: "Sag zu ihnen:'So spricht Jahwe, der Herr: Seht, ich hole die Israeliten aus den Völkern heraus, zu denen sie gehen mussten, und bringe sie von überall her in ihre Heimat zurück." },
      { number: 22, text: "Dort, auf den Bergen Israels, mache ich sie zu einem einzigen Volk unter einem einzigen König. Sie sollen nicht mehr zwei getrennte Völker und zwei getrennte Königreiche sein." },
      { number: 23, text: "Sie werden sich durch ihr böses Tun, ihre Götzen und Scheusale nicht mehr besudeln. Ich will ihnen Hilfe in ihren Wohnorten schaffen, wo sie gesündigt haben, und mache sie wieder rein. Sie sollen mein Volk sein, und ich, ich werde ihr Gott sein." },
      { number: 24, text: "Und mein Diener David* soll König über sie sein. So werden sie alle einen einzigen Hirten haben. Sie werden nach meinen Weisungen leben und meine Gebote befolgen.", footnotes: ["David. Siehe Hesekiel 34,23."] },
      { number: 25, text: "Sie werden in dem Land wohnen, das ich meinem Diener Jakob gegeben habe, wo auch ihre Vorfahren lebten, ihre Kinder und Enkel und alle kommenden Generationen. Und mein Diener David wird für immer über sie herrschen." },
      { number: 26, text: "Ich schließe einen Friedensbund mit ihnen. Es wird ein ewiger Bund sein. Ich werde sie sich vermehren lassen und lasse mein Heiligtum für immer in ihrer Mitte sein." },
      { number: 27, text: "Meine Wohnung wird über ihnen sein. Ich werde ihr Gott und sie werden mein Volk sein.*", footnotes: ["Wird im Neuen Testament von Paulus zusammen mit 3. Mose 26,12 nach der LXX zitiert: 2. Korinther 6,16."] },
      { number: 28, text: "Wenn dann mein Heiligtum für immer in ihrer Mitte ist, werden die Völker erkennen, dass ich es bin – Jahwe, der Israel heilig macht.'\"" },
    ] },
    { number: 38, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Der Herrscher Gog aus Magog" },
      { number: 2, text: "\"Du Mensch, wende dich gegen Gog* aus dem Land Magog*, gegen den Großfürsten* von Meschech und Tubal* und weissage Folgendes:", footnotes: ["Gog. Es sind verschiedene Identifikationen versucht worden, zum Beispiel mit Gyges, dem König von Lydien (um 600 v.Chr.) in Kleinasien. Wahrscheinlich steht der Name symbolisch für alle Völker der Endzeit, die Gott und seinem Volk feindlich gegenüberstehen.", "Magog. Nach Hesekiel 39,6 scheint es ein Volk zu sein, es könnte aber nach der hebräischen Vorsilbe (ma = Platz von) einfach nur Land des Gog heißen.", "Großfürsten. Andere übersetzen: Fürst von Rosch. Doch ein solcher Ort ist völlig unbekannt. Dass damit Russland gemeint sei, ist reine Spekulation. Das hebräische Rosch bedeutet: Kopf, Gipfel, Anführer. Von daher: Großfürst.", "Meschech und Tubal sind zwei anatolische Königreiche aus dem nördlichen Kleinasien zwischen dem Schwarzen und dem Kaspischen Meer (siehe Hesekiel 27,13; 1. Mose 10,2; 1. Chronik 1,5)."] },
      { number: 3, text: "So spricht Jahwe, der Herr: 'Du bekommst es mit mir zu tun, Gog aus dem Land Magog, du Großfürst von Meschech und Tubal!" },
      { number: 4, text: "Ich lenke dich herum, ich schlage dir Haken in deine Kinnlade und führe dich und dein ganzes großes Heer heraus, deine Pferde und Reiter, alle prächtig gekleidet und gut gerüstet mit Langschild, Rundschild und Schwert." },
      { number: 5, text: "Auch Söldner aus Persien, Nubien und Libyen mit Helm und Schild sind dabei," },
      { number: 6, text: "ebenso Gomer* und seine Schwadronen und Bet-Torgama* im äußersten Norden mit seinen Scharen. Viele Völker kommen mit dir.", footnotes: ["Gomer ist ein Volk, das am Nordufer des Schwarzen Meeres lebte und den Assyrern im 8. Jh. v.Chr. große Probleme bereitet hatte. Später drangen sie durch den Kaukasus nach Kleinasien vor und eroberten 644 v.Chr. auch Sardes.", "Bet-Torgama war wahrscheinlich die Hauptstadt des anatolischen Königreiches Kammanu, das aus hetitischen und assyrischen Quellen bekannt ist."] },
      { number: 7, text: "Rüste dich und halte dich mit deiner ganzen Heeresmacht bereit, die sich bei dir versammelt hat, und halte sie fest im Griff!" },
      { number: 8, text: "Es werden zwar noch viele Jahre vergehen, bis du den Befehl zum Abmarsch erhältst. Du sollst in ein Land kommen, das sich vom Krieg erholt hat, zu einem Volk, das aus vielen Nationen wieder zusammengeführt wurde und nun auf den Bergen Israels, die lange Zeit verödet waren, in Sicherheit wohnt." },
      { number: 9, text: "Du wirst wie ein Gewittersturm über sie kommen und wie eine Wolke das ganze Land mit deinen Truppen und Hilfsvölkern bedecken.'" },
      { number: 10, text: "So spricht Jahwe, der Herr: Zu der Zeit werden böse Gedanken in deinem Herzen aufsteigen, und du wirst einen boshaften Plan schmieden" },
      { number: 11, text: "und denken: 'Ich will ein ungeschütztes Land überfallen, will über friedliche Leute herfallen, die ruhig und sorglos leben und weder Mauern, noch Tore und Riegel haben.'" },
      { number: 12, text: "Du willst reiche Beute machen und über ein Volk herfallen, das aus fremden Völkern heimgekehrt ist und die zerstörten Orte neu besiedelt hat, das Herden und anderen Besitz erworben hat und den Nabel der Erde bewohnt." },
      { number: 13, text: "Dann werden Saba* und Dedan* dich fragen, auch die Händler und Kaufleute aus Tarschisch*: 'Kommst du, um Beute zu machen? Hast du deine Heere versammelt, um zu plündern, um Gold und Silber wegzuschleppen, Vieh und alles, was Wert hat? Willst du einen großen Fang machen?'", footnotes: ["Saba liegt in der südwestlichen Ecke von Arabien, dem heutigen Jemen.", "Dedan war eine zentralarabische Oase.", "Tarschisch war eine von Tyrus gegründete südspanische Küstenstadt."] },
      { number: 14, text: "Darum weissage, Mensch! Sage zu Gog: \"So spricht Jahwe, der Herr: 'Nicht wahr, dann, wenn mein Volk Israel in Sicherheit wohnt, wirst du es erfahren" },
      { number: 15, text: "und ziehst aus deinem Land im äußersten Norden heran, gefolgt von deinen Reiterheeren und einer riesigen Heeresmacht aus vielen Völkern." },
      { number: 16, text: "Du wirst gegen mein Volk Israel heranziehen und wie eine Wolke das ganze Land bedecken. Am Ende der bestimmten Zeit wird das geschehen. Dann lasse ich dich gegen mein Volk Israel heranziehen, damit die Völker mich erkennen, wenn ich mich an dir, Gog, als der Heilige erweise.'" },
      { number: 17, text: "So spricht Jahwe, der Herr: 'Du bist doch derjenige, von dem ich schon früher durch meine Diener, die Propheten Israels, jahrelang weissagen ließ, dass ich dich über sie bringen würde.'" },
      { number: 18, text: "Doch an dem Tag, an dem Gog in das Land Israel einfällt, spricht Jahwe, der Herr, steigt mir der Zorn in die Nase." },
      { number: 19, text: "Ich rede mit Eifer und Zorn und schwöre: An dem Tag wird das Land Israel von einem schweren Erdbeben heimgesucht." },
      { number: 20, text: "Menschen und Tiere werden vor mir zittern, selbst die Fische im Meer, die Vögel in der Luft und alles, was auf dem Erdboden kriecht. Berge reißen auseinander, Felsterrassen stürzen ein und jede Mauer bricht zusammen." },
      { number: 21, text: "Dann rufe ich mein ganzes Bergland zum Krieg gegen ihn auf, spricht Jahwe, der Herr. Dann zieht jeder gegen jeden das Schwert." },
      { number: 22, text: "Ich gehe ins Gericht mit ihm und richte ein Blutbad unter seinen Truppen an. Ich lasse die Pest und Wolkenbrüche über ihn kommen. Es wird Hagelsteine, Feuer und Schwefel auf ihn und seine Heere regnen und auf die vielen Völker, die mit ihm sind." },
      { number: 23, text: "So werde ich vor den Augen vieler Nationen meine Größe und Heiligkeit zeigen, damit sie erkennen, dass ich bin, der ich bin – Jahwe!\"" },
    ] },
    { number: 39, verses: [
      { number: 1, text: "\"Du Mensch, weissage Folgendes gegen Gog:So spricht Jahwe, der Herr: Pass auf, ich gehe gegen dich vor, Großfürst von Meschech und Tubal.", heading: "Der Untergang von Gog" },
      { number: 2, text: "Ich lenke dich herum und führe dich auf deinem Weg. Ich lasse dich vom äußersten Norden her kommen und bringe dich auf die Berge Israels." },
      { number: 3, text: "Dann schlage ich dir den Bogen aus der linken Hand und lasse deiner Rechten die Pfeile entfallen." },
      { number: 4, text: "Auf den Bergen Israels wirst du mit deinem riesigen Heer und allen Hilfsvölkern fallen. Ich werfe dich den Raubvögeln und den wilden Tieren zum Fraß vor." },
      { number: 5, text: "Auf freiem Feld wirst du fallen, denn ich habe es gesagt, spricht Jahwe, der Herr." },
      { number: 6, text: "Und ich lege Feuer an Magog und die Meeresländer, die sich in Sicherheit wiegen. Dann werden sie erkennen, dass ich es bin, Jahwe." },
      { number: 7, text: "Meinen heiligen Namen offenbare ich mitten in meinem Volk Israel, und nie mehr lasse ich meinen heiligen Namen entweihen. Die Völker werden erkennen, dass ich es bin, Jahwe, heilig in Israel." },
      { number: 8, text: "Passt auf, es kommt und wird geschehen, spricht Jahwe, der Herr. Das ist der Tag, von dem ich gesprochen habe." },
      { number: 9, text: "Dann werden die Einwohner der Städte Israels hinausziehen und die Waffen auflesen: Rund- und Langschilde, Bogen und Pfeile, Handkeulen und Lanzen. Sieben Jahre lang werden sie damit Feuer machen und heizen." },
      { number: 10, text: "Sie brauchen kein Holz mehr auf dem Feld zu sammeln oder im Wald zu schlagen. Sie werden mit den Waffen Feuer machen und so ihre Räuber berauben und ihre Plünderer plündern, spricht Jahwe, der Herr." },
      { number: 11, text: "An jenem Tag weise ich Gog und seiner ganzen lärmenden Menge ein Grab in Israel zu: die Schlucht der Durchreisenden, östlich vom Toten Meer. Das Grab wird jedem, der durchreisen will, den Weg versperren. Und die Stelle wird man nennen: 'Schlucht der lärmenden Menge Gogs'." },
      { number: 12, text: "Sieben Monate wird Israel brauchen, um die Gefallenen zu begraben und das Land zu reinigen." },
      { number: 13, text: "Das ganze Volk im Land wird beim Begraben helfen. Dadurch machen auch sie sich am Tag meiner Verherrlichung einen Namen, spricht Jahwe, der Herr." },
      { number: 14, text: "Und nach Ablauf der sieben Monate werden sie Männer beauftragen, die ständig durch das Land ziehen und alle begraben, die irgendwo im Land verstreut liegen geblieben sind, damit das Land rein wird." },
      { number: 15, text: "Wenn einer von ihnen irgendwo einen Menschenknochen entdeckt, kennzeichnet er die Stelle, damit die Totengräber kommen und ihn in der 'Schlucht der lärmenden Menge Gogs' begraben können." },
      { number: 16, text: "Auch eine Stadt namens Hamona, 'lärmende Menge', wird es geben. So werden sie das Land reinigen.\"" },
      { number: 17, text: "\"Und du, Mensch\", spricht Jahwe, der Herr, \"ruf den Raubvögeln und den wilden Tieren zu:Kommt her und versammelt euch, kommt von allen Seiten! Ich lade euch zum großen Opfermahl. Auf den Bergen Israels habe ich es für euch geschlachtet! Fresst Fleisch und trinkt Blut!" },
      { number: 18, text: "Fleisch von Helden dürft ihr fressen und Blut von den Fürsten der Erde dürft ihr trinken! Das sind die Schafböcke und Lämmer, die Ziegenböcke und Stiere, das ist das Mastvieh aus Baschan für euch." },
      { number: 19, text: "Fresst euch voll mit Fett und berauscht euch am Blut des Opfers, das ich für euch geschlachtet habe!" },
      { number: 20, text: "Sättigt euch an meinem Tisch mit Reit- und Wagenpferden, mit Helden und Kriegern, spricht Jahwe, der Herr.\"" },
      { number: 21, text: "\"So bringe ich meine Herrlichkeit unter die Völker, und alle Nationen werden sehen, wie ich mein Strafgericht vollstrecke und meine Macht an ihnen demonstriere.", heading: "Die Wiederherstellung Israels" },
      { number: 22, text: "Und die Israeliten werden erkennen, dass ich, Jahwe, ihr Gott bin, und sie werden das in Zukunft nie mehr vergessen." },
      { number: 23, text: "Die anderen Völker werden begreifen, dass mein Volk Israel wegen seiner Schuld in die Verbannung musste. Sie waren mir untreu geworden. Deshalb verbarg ich mein Gesicht vor ihnen und gab sie in die Gewalt ihrer Feinde, sodass sie alle unter dem Schwert fielen." },
      { number: 24, text: "Ich habe sie so behandelt, wie sie es durch ihre Beschmutzung und ihre Vergehen verdienten, und mein Gesicht vor ihnen verborgen." },
      { number: 25, text: "Jetzt aber – sagt Jahwe, der Herr – wende ich Jakobs Geschick. Ich erbarme mich über die Nachkommen Israels und setze mich eifersüchtig für meinen heiligen Namen ein." },
      { number: 26, text: "Nur an ihrer Schande und Untreue gegen mich werden sie noch tragen, wenn sie wieder sicher und ungestört in ihrem Land wohnen werden," },
      { number: 27, text: "und ich sie aus den Völkern zurückgebracht, sie aus den Ländern ihrer Feinde eingesammelt und mich vor den Augen vieler Völker als der Heilige erwiesen habe." },
      { number: 28, text: "Sie werden erkennen, dass ich, Jahwe, ihr Gott bin. Ich habe sie zwar unter fremde Völker verschleppt, aber nun habe ich sie wieder in ihrem Land versammelt und keinen von ihnen in der Fremde zurückgelassen." },
      { number: 29, text: "Ich werde mein Gesicht nie mehr vor ihnen verbergen, weil ich meinen Geist über die Israeliten ausgegossen habe, spricht Jahwe, der Herr.\"" },
    ] },
    { number: 40, verses: [
      { number: 1, text: "* Am Jahresanfang, am 10. April im 25. Jahr unserer Verbannung* – das war das 14. Jahr nach dem Fall der Stadt – legte Jahwe die Hand auf mich und brachte mich genau dorthin.", heading: "Der neue Tempel (40-43)\nDie Vision vom neuen Tempel", footnotes: ["Kapitel 40-48: Tempel. Siehe die Rekonstruktionszeichnung im Anhang.", "April. Wörtlich: am 10. des Monats. Es war das Jahr 573 v. Chr."] },
      { number: 2, text: "In göttlichen Visionen brachte er mich ins Land Israel und setzte mich auf einem sehr hohen Berg nieder. Auf dessen Südseite war so etwas wie eine Stadt zu sehen." },
      { number: 3, text: "Dorthin brachte er mich. Am Tor stand ein Mann, der aussah, als sei er aus Bronze. In seiner Hand hielt er eine Schnur aus Flachs und eine Messrute." },
      { number: 4, text: "Der Mann sagte zu mir: \"Du Mensch, mach deine Augen und Ohren auf und achte genau auf alles, was ich dir zeige. Denn dazu bist du hierher gebracht worden. Berichte dem Haus Israel alles, was du hier zu sehen bekommst.\"" },
      { number: 5, text: "Ich sah, dass der ganze Tempelbezirk von einer Mauer umschlossen war. Der Mann maß sie mit der Messrute in seiner Hand aus: eine Rute hoch, eine Rute dick. Die Messrute in seiner Hand war sechs Ellen lang, die Elle eine Handbreit länger als gewöhnlich gerechnet*.", heading: "Das Osttor zum äußeren Vorhof", footnotes: ["Weil die für eine Elle angegebenen Maße zwischen 44,42 und 52,45 cm schwanken, gehen wir für die meisten Umrechnungen von 50 cm aus. Dadurch werden auch die Proportionen deutlicher. Die Rute war demnach drei Meter lang."] },
      { number: 6, text: "Dann stieg der Mann die Stufen hinauf, die zum östlichen Toreingang führten, und maß die Torschwelle. Sie war drei Meter breit." },
      { number: 7, text: "Jede Nische für die Wächter im Tor war drei Meter lang und drei Meter breit. Die Pfeiler zwischen den Nischen waren zweieinhalb Meter dick. Die Schwelle der hinteren Toröffnung war, wie die der vorderen, 3,24 Meter breit." },
      { number: 8, text: "Dann maß er die Vorhalle des Tores zum Tempel hin. Sie war drei Meter tief" },
      { number: 9, text: "und vier Meter breit. Die Mauerstücke rechts und links am Ausgang waren einen Meter dick." },
      { number: 10, text: "Das Osttor hatte auf jeder Seite drei durch Pfeiler getrennte gleich große Nischen für die Wächter." },
      { number: 11, text: "Die lichte Weite der Toröffnung betrug fünf Meter und die ganze Torbreite sechseinhalb Meter." },
      { number: 12, text: "Die Nischen für die Wächter auf jeder Seite waren zum Durchgang hin mit einer Mauer von einem halben Meter Höhe abgeschlossen." },
      { number: 13, text: "Dann maß er die Breite des ganzen Tores. Vom Dachansatz der einen Nische bis zum Dachansatz der gegenüberliegenden waren es zwölfeinhalb Meter." },
      { number: 14, text: "Für die vorspringenden Wände, die auf die Pfeiler des Innenhofes zuliefen, machte er eine Länge von zehn Metern aus." },
      { number: 15, text: "Das ganze Torgebäude vom Vordereingang bis zu dem des Innenhofs maß 25 Meter." },
      { number: 16, text: "Die Nischen hatten gerahmte Fenster an den Außen- und Innenwänden. Auch die Vorhalle hatte ringsherum Fenster. Und die Mauerstücke am Torausgang waren mit Palmen verziert." },
      { number: 17, text: "Dann brachte er mich in den äußeren Vorhof. Dieser war ringsherum von 30 nebeneinander liegenden Räumen umgeben. Vor diesen Räumen war der Boden mit Steinplatten belegt.", heading: "Der äußere Vorhof" },
      { number: 18, text: "Der Plattenbelag reichte so weit in den Vorhof hinein wie die Torgebäude und lag tiefer als der innere Vorhof." },
      { number: 19, text: "Er maß den Abstand zwischen der Innenseite des unteren Tores bis zur Außenseite des höher gelegenen Innentores. Es waren 50 Meter. Nachdem die Ostseite ausgemessen war, gingen wir auf die Nordseite." },
      { number: 20, text: "Auch dort war ein Tor zum äußeren Vorhof. Seine Außenseite zeigte nach Norden. Er maß seine Länge und Breite.", heading: "Das Nordtor" },
      { number: 21, text: "Es hatte drei Nischen auf jeder Seite für die Wächter. Seine Pfeiler und die Vorhalle hatten die gleichen Maße wie das erste Tor. Es war 25 Meter lang und halb so breit." },
      { number: 22, text: "Vorhalle, Fenster und Palmen sahen genauso aus wie beim Osttor. Auf sieben Stufen stieg man zum Toreingang hinauf, und seine Vorhalle lag auf der Innenseite." },
      { number: 23, text: "Wie beim Osttor befand sich genau gegenüber ein Tor, das zum inneren Vorhof führte. Von Tor zu Tor waren es 50 Meter." },
      { number: 24, text: "Dann führte er mich auf die Südseite. Auch dort war ein Tor. Seine Vorhalle und das Mauerwerk hatten die gleichen Maße wie die anderen Tore.", heading: "Das Südtor" },
      { number: 25, text: "Auch die Fenster im Torgebäude und in der Vorhalle waren wie die anderen Fenster. Das Tor war 25 Meter lang und halb so breit." },
      { number: 26, text: "Auf sieben Stufen stieg man zum Toreingang hinauf, und seine Vorhalle lag auf der Innenseite. Die Mauerstücke rechts und links waren mit Palmen verziert." },
      { number: 27, text: "Auch hier hatte es als Gegenstück in 50 Metern Entfernung ein Tor zum inneren Vorhof." },
      { number: 28, text: "Dann führte er mich durch das Südtor in den inneren Vorhof. Es hatte die gleichen Maße wie die anderen Tore.", heading: "Die Tore zum inneren Vorhof" },
      { number: 29, text: "Die Nischen für die Wächter, die Mauervorsprünge und die Vorhalle waren wie dort. Auch dieses Tor und seine Vorhalle hatten ringsherum Fenster. Es war 25 Meter lang und halb so breit." },
      { number: 30, text: "Die Vorhallen rings um den Innenhof waren zwölfeinhalb Meter lang und zweieihalb Meter tief." },
      { number: 31, text: "Seine Vorhalle jedoch lag zum äußeren Vorhof hin. Seine Mauerstücke waren mit Palmen verziert, und acht Stufen bildeten den Aufgang." },
      { number: 32, text: "Dann brachte er mich in den inneren Vorhof auf die Ostseite und vermaß das dort gelegene Tor. Es hatte die gleichen Maße wie die anderen Tore." },
      { number: 33, text: "Die Nischen für die Wächter, seine Vorhalle und das Mauerwerk am Ausgang hatten die gleichen Maße. Auch dieses Tor und seine Vorhalle hatten ringsherum Fenster. Es war 25 Meter lang und halb so breit." },
      { number: 34, text: "Seine Vorhalle lag zum äußeren Vorhof hin. Seine Mauerstücke waren mit Palmen verziert und acht Stufen bildeten den Aufgang." },
      { number: 35, text: "Dann führte er mich zum Nordtor und maß es aus. Es war den anderen Toren gleich:" },
      { number: 36, text: "die Nischen für die Wächter, seine Vorhalle und das Mauerwerk am Ausgang und die Fenster ringsherum. Es war 25 Meter lang und halb so breit." },
      { number: 37, text: "Seine Vorhalle lag zum äußeren Vorhof hin. Seine beiden Mauerstücke waren mit Palmen verziert, und acht Stufen bildeten den Aufgang." },
      { number: 38, text: "Dort gab es einen Raum, dessen Türöffnung sich an den Mauervorsprüngen der Tore befand. Dort wusch man das Brandopfer ab.", heading: "Räume zur Vorbereitung der Opfer" },
      { number: 39, text: "In der Vorhalle selbst standen auf jeder Seite zwei Tische. Auf ihnen wurden die Tiere für das Brand-, Sünd- und Schuldopfer geschlachtet." },
      { number: 40, text: "An den beiden Außenwänden der Vorhalle rechts und links vom Eingang des Nordtores waren ebenfalls je zwei Tische aufgestellt." },
      { number: 41, text: "So standen auf jeder Seite des Tores vier Tische, also insgesamt acht, auf denen geschlachtet wurde." },
      { number: 42, text: "Die Tische für das Brandopfer waren aus Quadersteinen gebaut. Sie waren dreiviertel Meter lang, ebenso breit und einen halben Meter hoch. Auf sie wurde alles hingelegt, was man zum Schlachten der Opfertiere brauchte." },
      { number: 43, text: "Ringsherum waren acht Zentimeter lange Haken für das Opferfleisch befestigt, das auf die Tische kam." },
      { number: 44, text: "Im Innenhof neben dem Nord- und Südtor befanden sich je ein Raum, der sich zum Vorhof hin öffnete. Der eine war nach Süden hin offen, der andere nach Norden.", heading: "Räume für die Priester" },
      { number: 45, text: "Mein Führer sagte zu mir: \"Der Raum, der nach Süden schaut, ist für die Priester bestimmt, die für den Tempel zu sorgen haben," },
      { number: 46, text: "und der, der nach Norden offen ist, für die Priester, die am Altar Dienst tun. Das sind die Nachkommen Zadoks, also diejenigen Leviten, die in die Nähe Jahwes kommen dürfen, um ihm zu dienen.\"" },
      { number: 47, text: "Dann vermaß er den inneren Vorhof. Er war 50 Meter lang und 50 Meter breit. Vor dem Tempelhaus stand der Altar.", heading: "Das Tempelhaus" },
      { number: 48, text: "Nun führte er mich in die Vorhalle des Tempelhauses und maß sie aus. Das Mauerwerk rechts und links von ihrem Eingang war je zweieinhalb Meter dick. Das Eingangstor selbst war sieben Meter breit und die Mauervorsprünge je anderthalb Meter." },
      { number: 49, text: "Die Vorhalle war zehn Meter breit und sechs Meter tief. Zehn Stufen führten zu ihr hinauf. Vor den Mauerstücken auf beiden Seiten stand je eine Säule." },
    ] },
    { number: 41, verses: [
      { number: 1, text: "Dann führte er mich in den Tempelraum hinein und maß die Mauerstücke rechts und links. Sie waren drei Meter dick." },
      { number: 2, text: "Der Eingang selbst war fünf Meter breit. Die Mauerstücke auf beiden Seiten sprangen je zweieinhalb Meter vor. Er maß die Länge des Tempelraums. Es waren 20 Meter, seine Breite betrug 10 Meter." },
      { number: 3, text: "Dann ging er in den innersten Raum und maß das Mauerwerk am Eingang. Es war auf beiden Seiten einen Meter dick. Der Eingang selbst war drei Meter breit. Die Mauern auf beiden Seiten des Eingangs sprangen dreieinhalb Meter vor." },
      { number: 4, text: "Der Raum selbst war zehn Meter tief und zehn Meter breit. Als er ihn gemessen hatte, sagte er zu mir: \"Das ist das Höchstheilige.\"" },
      { number: 5, text: "Dann maß er die Seitenwände des Tempelhauses. Sie waren drei Meter dick. Um das Tempelhaus herum gab es einen Anbau von zwei Metern Breite." },
      { number: 6, text: "Er bestand aus drei Stockwerken mit je dreißig Kammern. Die Stockwerke waren auf der Innenseite nicht in der Mauer des Tempelhauses verankert, sondern ruhten auf den Mauerabsätzen an der Außenseite der Tempelwand." },
      { number: 7, text: "Weil die Tempelmauer nach oben hin zurücktrat, verbreiterte sich der Innenraum des Anbaus von Stockwerk zu Stockwerk. Im unteren war er am schmalsten, im oberen am breitesten." },
      { number: 8, text: "Ich sah eine Terrasse um das Haus herum laufen, die von den Unterbauten der Seitenkammern gebildet wurde und drei Meter hoch war." },
      { number: 9, text: "Die Außenwand des Anbaus selbst war nur zweieinhalb Meter dick. Zwischen den Seitenkammern des Tempelhauses" },
      { number: 10, text: "und den Räumen um das Tempelhaus herum war ein freigelassener Platz von zehn Metern Breite." },
      { number: 11, text: "Die Eingänge des Anbaus öffneten sich zur Terrasse hin, die ringsherum zweieinhalb Meter breit war." },
      { number: 12, text: "Hinter dem Tempelhaus, also in westlicher Richtung, stand in einem abgesonderten Bereich ein weiteres Gebäude. Es war 35 Meter tief und 45 Meter breit. Seine Außenmauer war zweieinhalb Meter dick." },
      { number: 13, text: "Nun maß er die ganze Tempelanlage aus. Das Tempelhaus war 50 Meter lang. Von seiner Rückseite über den unbebauten Streifen bis zur Rückseite des anderen Gebäudes waren es ebenfalls 50 Meter." },
      { number: 14, text: "Die Breite des Tempelhauses auf der Ostseite einschließlich des unbebauten Streifens betrug ebenfalls 50 Meter." },
      { number: 15, text: "Weiter maß er die Breite des Hintergebäudes. Es war einschließlich der Terrassenbauten auf beiden Seiten 50 Meter breit.Das Innere des Tempelhauses und seine Vorhalle" },
      { number: 16, text: "waren getäfelt, vom Boden bis hinauf zu den Fenstern. Diese hatten einen dreifach abgestuften Rahmen und konnten verschlossen werden." },
      { number: 17, text: "Oberhalb des Eingangs innen und außen und auf allen Wänden rings herum war die Täfelung in Felder eingeteilt," },
      { number: 18, text: "in die abwechselnd Cherubim und Palmen eingeschnitzt waren. Jeder Cherub hatte zwei Gesichter." },
      { number: 19, text: "Ihr Menschengesicht war der einen Palme zugewandt und ihr Löwengesicht der anderen." },
      { number: 20, text: "Vom Fußboden bis über die Tür hinauf waren die Cherubim und Palmen an allen Wänden zu sehen." },
      { number: 21, text: "Die Eingangstür zum Tempelraum hatte einen vierfach gestaffelten Rahmen. Vor dem Höchstheiligen aber stand etwas, das aussah wie" },
      { number: 22, text: "ein Altar aus Holz, anderthalb Meter hoch, einen Meter lang und ebenso breit. Seine Ecken, seine Wände und sein Sockel waren aus Holz. Der Mann sagte zu mir: \"Das ist der Tisch, der vor Jahwe steht.\"" },
      { number: 23, text: "Der Tempelraum und das Höchstheilige hatten je eine Doppeltür." },
      { number: 24, text: "Rechts und links waren hintereinander je zwei drehbare Türflügel angebracht." },
      { number: 25, text: "Wie die Wände waren auch die Türflügel mit Cherubim und Palmen verziert.Die Vorhalle hatte über ihrem Eingang ein Vordach aus Holz." },
      { number: 26, text: "Auch ihre Wände waren von gerahmten Fenstern durchbrochen und bis zum hölzernen Vordach mit Palmen verziert. Ebenso war es mit den Seitenkammern und ihren Dachbalken." },
    ] },
    { number: 42, verses: [
      { number: 1, text: "Dann führte er mich in den nördlichen Teil des Vorhofs hinaus. An der Nordseite des Gebäudes, das hinter dem Tempel lag, befand sich ein Bauwerk. Es stand vor diesem Gebäude und neben dem unbebauten Streifen.", heading: "Räume für die Priester" },
      { number: 2, text: "Der Bau war 50 Meter lang und 25 Meter breit." },
      { number: 3, text: "Er stand neben dem unbebauten zehn Meter breiten Streifen des inneren Vorhofs und dem Steinpflaster des äußeren Vorhofs und erhob sich in drei abgestuften Stockwerken." },
      { number: 4, text: "Auf der Nordseite, wo auch die Eingänge des Bauwerks waren, verlief ein fünf Meter breiter Gang. Zum inneren Vorhof führte ein Durchgang, einen halben Meter breit." },
      { number: 5, text: "Die oberen Räume waren schmaler als die unteren und mittleren, weil die Galerien ihnen einen Teil vom Raum wegnahmen," },
      { number: 6, text: "denn das Ganze war dreistöckig angelegt. Die Stockwerke hatten aber keine Säulen wie der Vorhof, deshalb wurden sie von unten nach oben immer kürzer." },
      { number: 7, text: "Eine Mauer von 25 Metern Länge begrenzte die Eingangsseite zum äußeren Vorhof hin." },
      { number: 8, text: "Da die Räume, die zum Vorhof hin zeigten, ebenfalls 25 Meter lang waren, war die ganze Mauer 50 Meter lang." },
      { number: 9, text: "Der Zugang zu den unteren Räumen lag im Osten, wenn man vom äußeren Vorhof aus hineinging." },
      { number: 10, text: "Auch auf der Südseite grenzte ein Bauwerk an die Mauer des äußeren Vorhofs." },
      { number: 11, text: "Und auch hier führte ein Gang an der Vorderseite des Gebäudes entlang. Der Bau glich in allem dem auf der Nordseite in Länge, Breite, Ausgängen und Eingängen," },
      { number: 12, text: "die hier nach Süden hin lagen. Auch hier gelangte man entlang der Schutzmauer von Osten her in das Gebäude, wenn man aus dem äußeren Vorhof kam." },
      { number: 13, text: "Der Mann sagte zu mir: \"Die Räume im nördlichen und südlichen Bau, die vor dem umfriedeten Platz liegen, sind als heilige Räume für die Priester bestimmt, die in der Nähe des Herrn ihren Dienst tun. Dort sollen sie ihre Anteile an den höchst heiligen Opfergaben essen. Dorthin sollen sie auch die höchst heiligen Gaben vom Speise-, Sünd- und Schuldopfer bringen, denn es ist ein heiliger Ort." },
      { number: 14, text: "Wenn die Priester im Heiligtum waren, sollen sie von dort nicht in den Vorhof hinausgehen, sondern die Gewänder, in denen sie ihren Dienst verrichtet haben, in diesen Räumen ablegen, denn die Gewänder sind heilig. Erst nachdem sie sich umgezogen haben, dürfen sie auf den Platz gehen, der auch für das Volk zugänglich ist.\"" },
      { number: 15, text: "Als er den inneren Tempelbezirk vermessen hatte, führte er mich durch das Osttor hinaus und vermaß den ganzen äußeren Umfang.", heading: "Der Tempelbezirk" },
      { number: 16, text: "Er benutzte die Messrute dazu. Die Ostseite war 250 Meter* lang.", footnotes: ["250 Meter. Der hebräische Text hat hier: 500 Ruten = 1,5 km. In der LXX fehlt die Maßeinheit, sodass man an dieser Stelle von 500 Ellen ausgehen sollte."] },
      { number: 17, text: "Auch die Nordseite war 250 Meter lang," },
      { number: 18, text: "ebenso die Südseite" },
      { number: 19, text: "und die Westseite." },
      { number: 20, text: "Er vermaß den Tempelbezirk nach allen vier Windrichtungen hin. Die Außenmauer des Tempelbezirks war 250 Meter lang und 250 Meter breit; sie sollte das Heilige vom Profanen trennen." },
    ] },
    { number: 43, verses: [
      { number: 1, text: "Dann führte er mich wieder zum Osttor.", heading: "Die Herrlichkeit Gottes kehrt in den Tempel zurück" },
      { number: 2, text: "Da kam von Osten her plötzlich Israels Gott in seiner Herrlichkeit heran. Es rauschte wie ein riesiger Wasserfall, und die Erde leuchtete von seiner Herrlichkeit." },
      { number: 3, text: "Es war dieselbe Erscheinung, die ich gesehen hatte, als er kam, um die Stadt zu vernichten, und dieselbe, die ich am Fluss Kebar gesehen hatte.* Da warf ich mich nieder auf mein Gesicht.", footnotes: ["gesehen hatte. Siehe Hesekiel 1,5-21; 8,4."] },
      { number: 4, text: "Die Herrlichkeit Jahwes zog durch das Osttor in den Tempel ein." },
      { number: 5, text: "Da hob mich der Geist hoch und brachte mich in den inneren Vorhof. Ich sah, dass die Herrlichkeit Jahwes das ganze Haus erfüllte." },
      { number: 6, text: "Der Mann, der mich geführt hatte, stand noch neben mir, da hörte ich jemand aus dem Haus zu mir reden." },
      { number: 7, text: "\"Du Mensch\", sagte er, \"hier ist der Ort, wo mein Thron steht, und der Ort, wo meine Füße stehen. Hier, mitten unter den Israeliten, will ich für immer wohnen. Nie mehr werden die Leute von Israel oder ihre Könige meinen Namen besudeln, weder durch ihre sexuelle Unmoral noch durch die Leichen ihrer Könige, die sie in meiner Nähe bestatten.*", footnotes: ["Nähe bestatten. Oder: ... durch die Leichen ihrer Melech-Opfer und ihre Kultkammern."] },
      { number: 8, text: "Sie haben ihre Paläste neben meinen Tempel gebaut und Tür an Tür mit mir gewohnt, sodass nur eine Wand zwischen uns war, und besudelten so meinen heiligen Namen durch ihre abscheulichen Taten. Deshalb habe ich sie in meinem Zorn vernichtet." },
      { number: 9, text: "Doch jetzt werden sie ihre sexuelle Unmoral und die Leichen ihrer Könige von mir fernhalten, und ich werde für immer unter ihnen wohnen." },
      { number: 10, text: "Du, Mensch, beschreibe den Leuten von Israel das Haus, das du gesehen hast. Wenn sie die Ausmaße dieses Plans verstehen, werden sie sich ihrer Sünden schämen." },
      { number: 11, text: "Und wenn sie sich all dessen schämen, was sie getan haben, dann schildere ihnen den Plan des Hauses in allen Einzelheiten, seine Einrichtung und Zugänge, all seine Anordnungen und Vorschriften. Zeichne es vor ihren Augen auf, damit sie alle Anordnungen und Vorschriften künftig genau befolgen." },
      { number: 12, text: "Das Gesetz für den Tempelbezirk lautet: Der gesamte Bezirk auf der Kuppe des Berges ist mir geweiht und heilig. Das ist das grundlegende Gesetz für den Tempel.\"" },
      { number: 13, text: "Der Altar hatte folgende Maße, die Elle eine Handbreit länger als gewöhnlich gerechnet*: Rings um den Altar war ein Graben, einen halben Meter breit und ebenso tief. Die gemauerte Einfassung an seinem Rand war 25 Zentimeter* breit. Der unterste Sockel", heading: "Der Brandopferaltar", footnotes: ["gerechnet. Siehe Hesekiel 40,5.", "25 Zentimeter. Wörtlich: eine Spanne = eine halbe Elle."] },
      { number: 14, text: "war vom Rand des Grabens an einen Meter hoch. Der nächste Sockel sprang einen halben Meter zurück und war zwei Meter hoch." },
      { number: 15, text: "Der Opferherd selbst war noch einmal zwei Meter hoch. An seinen Ecken ragten vier Hörner auf." },
      { number: 16, text: "Er war quadratisch gebaut mit einer Seitenlänge von sechs Metern." },
      { number: 17, text: "Der nächst untere Sockel war ebenfalls quadratisch. Er hatte eine Seitenlänge von sieben Metern und sprang um einen halben Meter vor. Das Gesims an seinem Rand war 25 Zentimeter breit. An der Ostseite führten Stufen zum Altar hinauf." },
      { number: 18, text: "Er sagte zu mir: \"Mensch, so spricht Jahwe, der Herr:Hier sind die Bestimmungen für den Tag, an dem der Altar fertiggestellt wird, damit man Brandopfer darauf opfern und Blut daran sprengen kann." },
      { number: 19, text: "Du sollst den Leviten aus der Nachkommenschaft Zadoks, den Priestern, die in meine Nähe kommen, um mir zu dienen, einen jungen Stier für das Sündopfer geben, spricht Jahwe, der Herr." },
      { number: 20, text: "Mit dessen Blut sollst du die vier Hörner des Altars, die vier Ecken seiner Einfassung und die Abgrenzung ringsum bestreichen. So sollst du den Altar von Sünde reinigen und Sühne für ihn erwirken." },
      { number: 21, text: "Dann nimmst du den Stier des Sündopfers und lässt ihn außerhalb des Tempelhauses an dem dafür bestimmten Platz verbrennen." },
      { number: 22, text: "Am zweiten Tag sollst du einen fehlerlosen Ziegenbock als Sündopfer bringen und den Altar von Sünde reinigen lassen, wie du es mit dem Stier getan hast." },
      { number: 23, text: "Wenn du das getan hast, sollst du einen jungen Stier und einen Schafbock vor mich bringen, beide ohne Fehler." },
      { number: 24, text: "Die Priester sollen Salz auf sie streuen und sie mir, Jahwe, als Opfer verbrennen." },
      { number: 25, text: "Sieben Tage lang sollst du täglich fehlerfreie Tiere bringen lassen: einen Ziegenbock, einen jungen Stier und einen Schafbock aus der Herde." },
      { number: 26, text: "Sieben Tage lang soll man Sühne für den Altar erwirken, ihn reinigen und weihen." },
      { number: 27, text: "Vom achten Tag an sollen die Priester eure Brand- und Freudenopfer* auf dem Altar zurichten. Dann werde ich euch gnädig annehmen, spricht Jahwe, der Herr.\"", footnotes: ["Beim Freudenopfer wurde im Gegensatz zum Brandopfer nur das Fett auf dem Altar verbrannt. Der größte Teil des Tieres durfte bei einer fröhlichen Opfermahlzeit gemeinsam mit Verwandten und Freunden verzehrt werden."] },
    ] },
    { number: 44, verses: [
      { number: 1, text: "Dann führte er mich zum äußeren Osttor des Heiligtums zurück. Es war verschlossen.", heading: "Der neue Gottesdienst (44-46)\nDas verschlossene Tor" },
      { number: 2, text: "Jahwe sagte zu mir: \"Dieses Tor soll verschlossen bleiben. Es darf nie geöffnet werden. Niemand darf hindurchgehen, nachdem Jahwe, der Gott Israels, auf diesem Weg in den Tempel eingezogen ist. Es muss geschlossen bleiben!" },
      { number: 3, text: "Der regierende Fürst allerdings darf darin sitzen, wenn er seine Opfermahlzeit vor Jahwe verzehrt. Er betritt es allerdings von der inneren Vorhalle aus und verlässt es wieder auf dem gleichen Weg.\"" },
      { number: 4, text: "Dann führte er mich durch das Nordtor an die Vorderseite des Tempelhauses. Da sah ich, wie die Herrlichkeit Jahwes das Haus erfüllte und fiel nieder auf mein Gesicht.", heading: "Vorschriften für die Leviten" },
      { number: 5, text: "Jahwe sagte zu mir: \"Du Mensch, sei mit ganzem Herzen dabei! Sieh genau hin und hör mir gut zu! Ich sage dir jetzt, was im Haus Jahwes zu beachten ist. Merk dir genau, wer dort hineingehen darf und wer nicht!" },
      { number: 6, text: "Sag zu diesen Rebellen, den Leuten von Israel:'So spricht Jahwe, der Herr: Lasst es nun endlich genug sein mit all euren Gräueln, ihr Israeliten!" },
      { number: 7, text: "Ihr habt Fremde in mein Heiligtum kommen lassen, die nicht nur am Körper, sondern auch am Herzen unbeschnitten waren. Sie standen dabei, wenn ihr mir meine Speise – Fett und Blut – dargebracht habt und schändeten dadurch mein Haus. So habt ihr zusätzlich zu all euren Gräueln auch noch meinen Bund gebrochen." },
      { number: 8, text: "Dann habt ihr sie sogar den Dienst in meinem Heiligtum verrichten lassen, anstatt ihn selber zu tun!" },
      { number: 9, text: "Darum spricht Jahwe, der Herr: Kein Fremder darf je in mein Heiligtum kommen, der am Körper und am Herzen unbeschnitten ist, keiner von den Fremden, die unter euch sind!" },
      { number: 10, text: "Sondern die Leviten, die sich von mir entfernt haben, als Israel in die Irre ging, die ihren Götzen nachliefen, die sollen ihre Schuld auf sich nehmen." },
      { number: 11, text: "Sie dürfen nur noch Torwächter an den Tempeltoren und Tempeldiener sein; sie sollen die Tiere für das Brand- und Freudenopfer schlachten und vor den Leuten bereitstehen, um sie zu bedienen." },
      { number: 12, text: "Weil sie für das Volk Götzenopfer dargebracht haben und so dem Haus Israel eine Schuldfalle geworden sind, habe ich meine Hand gegen sie erhoben, spricht Jahwe, der Herr, und lasse sie ihre Schuld büßen." },
      { number: 13, text: "Sie dürfen nicht mehr als Priester vor mich treten und in die Nähe der heiligen und höchst heiligen Dinge kommen, sondern müssen die Folgen ihrer abscheulichen Gräueltaten tragen." },
      { number: 14, text: "Ich mache sie zu Tempeldienern, damit sie alles erledigen, was im Tempel getan werden muss.'" },
      { number: 15, text: "'Aber die Priester, Leviten aus der Nachkommenschaft Zadoks, die mir in meinem Heiligtum treu gedient haben, als die Israeliten mich verließen und in die Irre gingen, sie sollen in meine Nähe kommen. Sie sollen vor mich hintreten, um mir das Fett und das Blut darzubringen, spricht Jahwe, der Herr.", heading: "Weisungen für die Priester" },
      { number: 16, text: "Sie dürfen in mein Heiligtum kommen und an meinen Tisch treten, um mir zu dienen." },
      { number: 17, text: "Und wenn sie durch die Tore des inneren Vorhofs gehen, sollen sie leinene Gewänder tragen. Sie dürfen keine Kleidung aus Wolle auf dem Körper haben, wenn sie ihren Dienst im inneren Vorhof verrichten." },
      { number: 18, text: "Sie sollen einen Kopfbund aus Leinen tragen und leinene Hosen anziehen. Sie dürfen keine Kleidung tragen, in der man schwitzt." },
      { number: 19, text: "Wenn sie dann in den äußeren Vorhof zum Volk hinausgehen wollen, müssen sie vorher die Gewänder, in denen sie den Dienst verrichtet haben, ausziehen und in ihren heiligen Räumen ablegen. Sie müssen andere Gewänder anziehen, damit sie das Volk durch diese Kleidung nicht mit dem Heiligen in Berührung bringen." },
      { number: 20, text: "Auch dürfen sie sich weder den Kopf kahl scheren noch die Haare frei wachsen lassen, sondern sollen ihr Haar kurz halten." },
      { number: 21, text: "Wenn die Priester zum Dienst in den inneren Vorhof hineingehen, dürfen sie vorher keinen Wein trinken." },
      { number: 22, text: "Sie dürfen keine Witwe und keine verstoßene Frau heiraten, sondern nur unberührte Mädchen aus dem Haus Israel. Die Witwe eines anderen Priesters allerdings dürfen sie heiraten." },
      { number: 23, text: "Sie sollen mein Volk unterweisen, damit es zwischen heilig und unheilig, rein und unrein unterscheiden lernt." },
      { number: 24, text: "Wenn es einen Rechtsstreit gibt, sollen sie nach meinen Bestimmungen Gericht halten. Sie müssen dafür sorgen, dass meine Gesetze und Ordnungen für die Festzeiten beachtet und meine Sabbate heilig gehalten werden." },
      { number: 25, text: "Sie dürfen nicht mit einem Toten in Berührung kommen und sich dadurch verunreinigen. Nur bei Vater oder Mutter, Sohn oder Tochter, Bruder oder unverheirateter Schwester dürfen sie unrein werden." },
      { number: 26, text: "Wenn der Priester sich dann aber wieder gereinigt hat, soll er noch sieben Tage zusätzlich warten," },
      { number: 27, text: "bevor er wieder den inneren Vorhof betritt. Und dann soll er zuerst ein Sündopfer für sich bringen, damit er wieder Dienst tun kann, spricht Jahwe, der Herr." },
      { number: 28, text: "Und was den Erbbesitz der Priester betrifft: Ich selbst bin ihr Besitz. Ihr sollt ihnen keinen Grundbesitz in Israel geben, denn ich bin ihr Eigentum." },
      { number: 29, text: "Sie bekommen ihren Teil vom Speis- und Schuldopfer. Und alles, was in Israel dem Bann verfallen ist, soll ihnen gehören." },
      { number: 30, text: "Das Beste von allen Erstlingsopfern und alle eure besonderen Gaben sollen den Priestern gehören. Auch das Beste von eurem Schrotmehl sollt ihr dem Priester geben, damit Segen auf deinem Haus ruht." },
      { number: 31, text: "Priester dürfen kein Fleisch essen, das von einem verendeten oder gerissenen Tier stammt, egal, ob Vogel, Wild oder Vieh.'\"" },
    ] },
    { number: 45, verses: [
      { number: 1, text: "\"Wenn ihr das Land als Erbbesitz verlost, sollt ihr eine Weihgabe für Jahwe vorwegnehmen, ein Stück Land, das ihm geweiht ist: zwölfeinhalb Kilometer lang und zehn Kilometer breit.", heading: "Die Aufteilung des Landes" },
      { number: 2, text: "Davon soll ein Stück von 250 Metern Länge und Breite direkt zum Heiligtum gehören mit einem Weidestreifen von 25 Metern Breite ringsherum." },
      { number: 3, text: "Mein Heiligtum soll als höchst heilige Stätte in der einen Hälfte des abgemessenen Stücks stehen, also in der Fläche von zwölfeinhalb Kilometern Länge und fünf Kilometern Breite." },
      { number: 4, text: "Diese Fläche soll den Priestern überlassen sein, die im Heiligtum, in Jahwes unmittelbarer Nähe, Dienst tun. Sie dürfen darauf ihre Häuser bauen, rings um meine hochheilige Stätte." },
      { number: 5, text: "Das andere Stück Land von zwölfeinhalb Kilometern Länge und fünf Kilometern Breite soll den Leviten gehören, die am Tempelhaus Dienst tun. Darauf können sie ihre Siedlungen bauen." },
      { number: 6, text: "Neben dem geweihten Gebiet sollt ihr der Stadt einen Grundbesitz von zwölfeinhalb Kilometern Länge und fünf Kilometern Breite geben. Hier können Menschen aus ganz Israel ihren Grundbesitz haben." },
      { number: 7, text: "Dem Fürsten soll das Land an der Seite der Weihgabe an das Heiligtum und dem Grundbesitz der Stadt gehören und zwar so weit nach Osten und Westen hin, wie der Landbesitz der einzelnen Stämme reicht." },
      { number: 8, text: "Nur dieses Stück Land soll sein Grundbesitz sein, damit meine Fürsten mein Volk nicht mehr unterdrücken, sondern das Land dem Volk Israel nach seinen Stämmen überlassen.\"" },
      { number: 9, text: "So spricht Jahwe, der Herr: \"Lasst es genug sein, ihr Fürsten von Israel! Beseitigt Unterdrückung und Gewalt! Sorgt für Recht und Gerechtigkeit! Hört auf, mein Volk von seinem Grund und Boden zu vertreiben, spricht Jahwe, der Herr!", heading: "Mahnung an die Fürsten" },
      { number: 10, text: "Verwendet richtige Waagen, richtiges Getreide- und richtiges Flüssigkeitsmaß." },
      { number: 11, text: "Das Getreidemaß Efa und das Bat für Flüssigkeiten sollen von derselben Größe sein. Als Norm für Hohlmaße gilt das Homer:* 1 Homer = 10 Efa = 10 Bat.", footnotes: ["1Homer = 220 Liter."] },
      { number: 12, text: "Bei den Gewichten soll ein Schekel 20 Gera* entsprechen, und 20 + 25 + 15 Schekel eine Mine* sein.", footnotes: ["1Gera = 0,6 Gramm; 1 Schekel = 11,5 Gramm.", "Eine Mine hat normalerweise 50 Schekel, hier 60, das heißt etwa 700 Gramm."] },
      { number: 13, text: "Folgende Abgaben sollt ihr entrichten: Von Weizen und Gerste je 16 Kilogramm pro Tonne," },
      { number: 14, text: "vom Olivenöl ein Prozent*", footnotes: ["ein Prozent. Die hebräischen Maßangaben zeigen, wie das praktisch messbar war: je ein Sechstel Efa auf den Homer; bzw. 1/10 Bat vom Kor. 10 Bat = 1 Homer = 1 Kor."] },
      { number: 15, text: "und vom Kleinvieh auf den gut bewässerten Weiden Israels ein Tier von 200. Alle Abgaben sind für die Speis-, Brand- und Freudenopfer bestimmt." },
      { number: 16, text: "Das ganze Volk des Landes ist zu dieser Abgabe an den Fürsten Israels verpflichtet." },
      { number: 17, text: "Doch der Fürst ist verantwortlich für die Brand-, Speis- und Trankopfer an den Festen: den Neumondtagen und Sabbaten und allen anderen Festen Israels. Er hat für die Sündopfer, die Speis-, Brand- und Freudenopfer zu sorgen, die für das Haus Israel Sühne bewirken.\"" },
      { number: 18, text: "So spricht Jahwe, der Herr: \"Am 1. April* sollst du einen fehlerlosen jungen Stier bringen, um das Heiligtum zu entsündigen.", heading: "Die großen Feste", footnotes: ["April Wörtlich: des 1. Monats."] },
      { number: 19, text: "Der Priester soll mit dem Blut dieses Sündopfers die Türpfosten des Tempelhauses bestreichen, die vier Ecken der Altareinfassung und die Pfosten des Osttors zum Innenhof." },
      { number: 20, text: "Am 7. April sollst du das wiederholen für den Israeliten, der unwissentlich oder unabsichtlich gesündigt hat, damit das Heiligtum entsündigt wird." },
      { number: 21, text: "Am 14. April sollt ihr das Passafest* feiern. Es ist ein Fest von sieben Tagen, an denen ungesäuerte Brotfladen gegessen werden sollen.", footnotes: ["Passa. Siehe 2. Mose 12-13."] },
      { number: 22, text: "Der Fürst hat an diesem Tag für sich selbst und für das ganze Volk einen Stier als Sündopfer darzubringen." },
      { number: 23, text: "Und an jedem Tag dieses Festes soll er Jahwe Brandopfer bringen: täglich sieben Stiere und sieben Schafböcke – fehlerfreie Tiere – und dazu täglich einen Ziegenbock." },
      { number: 24, text: "Als Speisopfer soll er 12 Kilogramm Mehl pro Stier und dreieinhalb Liter* Olivenöl pro Schafbock bereitstellen, 30 Prozent Ölanteil zur Mehlmenge*.", footnotes: ["dreieinhalb Liter. Hebräisch: 1 Hin. Flüssigkeitsmaß, etwa 3,5 Liter. 6 Hin = 1 Bat = 22 Liter.", "30 Prozent ... Mehlmenge. Wörtlich: Ein Hin Öl für das Efa."] },
      { number: 25, text: "Genau dasselbe soll er an dem Fest, das am 15. Oktober* beginnt, sieben Tage lang mit dem Sünd- und Brandopfer, dem Speisopfer und dem Öl machen.\"", footnotes: ["Oktober. Wörtlich: des 7. Monats."] },
    ] },
    { number: 46, verses: [
      { number: 1, text: "So spricht Jahwe, der Herr: \"Das Osttor des inneren Vorhofs soll die Woche über geschlossen bleiben, nur am Sabbat und am Neumondstag soll es geöffnet werden.", heading: "Die regelmäßigen Opfer" },
      { number: 2, text: "Der Fürst soll von außen her eintreten und an der Schwelle der Vorhalle zum Innenhof stehen bleiben. Von dort sieht er, wie die Priester sein Brand- und Freudenopfer darbringen. Dann soll er sich auf der Schwelle zur Anbetung niederwerfen und anschließend wieder hinausgehen. Das Tor soll erst am Abend geschlossen werden." },
      { number: 3, text: "Die Israeliten sollen an den Sabbaten und Neumondstagen Jahwe am äußeren Eingang dieses Tores anbeten." },
      { number: 4, text: "Das Brandopfer, das der Fürst Jahwe bringen lässt, soll am Sabbat aus sechs Lämmern und einem Schafbock bestehen, fehlerfreien Tieren." },
      { number: 5, text: "Das Speisopfer beträgt 12 Kilogramm Mehl pro Schafbock und bei den Lämmern, so viel er geben will, 30 Prozent Ölanteil zur Mehlmenge." },
      { number: 6, text: "Am Neumondstag soll das Opfer aus einem jungen Stier, sechs Lämmern und einem Schafbock bestehen, fehlerfreien Tieren." },
      { number: 7, text: "Das Speisopfer beträgt 12 Kilogramm Mehl pro Stier und Schafbock und bei den Lämmern, so viel er geben kann." },
      { number: 8, text: "Der Fürst soll durch das Osttor bis zu seinem Platz in der Vorhalle gehen und auf dem gleichen Weg wieder hinausgehen." },
      { number: 9, text: "Und wenn die Israeliten an den Festtagen kommen, um Jahwe anzubeten, sollen die, die durch das Nordtor kommen, wieder zum Südtor hinausgehen, und die durch das Südtor kommen, durch das Nordtor. Sie sollen den Vorhof immer durch das gegenüberliegende Tor wieder verlassen." },
      { number: 10, text: "Der Fürst soll mitten unter ihnen sein, wenn sie hineingehen und wenn sie herauskommen." },
      { number: 11, text: "An den Festtagen und während der großen Feste soll das Speisopfer 12 Kilogramm Mehl pro Stier und Schafbock betragen und bei den Lämmern, so viel er geben will, 30 Prozent Ölanteil zur Mehlmenge." },
      { number: 12, text: "Will der Fürst eine freiwillige Gabe für Jahwe bringen, ein Brand- oder Freudenopfer, dann soll man ihm das Osttor öffnen, und das Opfer soll so wie am Sabbat dargebracht werden. Wenn er wieder hinausgegangen ist, soll man das Tor schließen." },
      { number: 13, text: "Jeden Morgen muss Jahwe ein fehlerfreies einjähriges Lamm als Brandopfer dargebracht werden." },
      { number: 14, text: "Dazu jeden Morgen ein Speisopfer für Jahwe, das aus zwei Kilogramm Mehl und einem Liter Olivenöl besteht, das über das Mehl gegossen wird. Diese Ordnung gilt für immer." },
      { number: 15, text: "Jeden Morgen soll das Lamm, das Mehl und das Öl Jahwe als regelmäßiges Brandopfer dargebracht werden.\"" },
      { number: 16, text: "So spricht Jahwe, der Herr: \"Wenn der Fürst einem seiner Söhne etwas aus seinem Grundbesitz schenkt, geht es für immer in dessen Besitz über.", heading: "Der Grundbesitz des Fürsten" },
      { number: 17, text: "Schenkt er es aber einem seiner Beamten, dann gehört es diesem nur bis zum nächsten Erlassjahr, und kommt dann an den Fürsten zurück. Nur bei seinen Söhnen verbleibt es als Erbbesitz." },
      { number: 18, text: "Der Fürst darf sich nichts vom Grundbesitz des Volkes aneignen, er darf niemand mit Gewalt von seinem Grund und Boden verdrängen. Seine Söhne müssen ihren Teil aus seinem eigenen Grundbesitz bekommen, damit mein Volk nicht von seinem Grund und Boden verdrängt wird.\"" },
      { number: 19, text: "Dann brachte er mich durch den Eingang des Nordtors zu den dort gelegenen geheiligten Priesterzimmern. Ganz hinten, in westlicher Richtung, war ein besonderer Raum.", heading: "Die Opferküchen" },
      { number: 20, text: "Er sagte zu mir: \"Das ist der Ort, wo die Priester das Fleisch vom Schuld- und Sündopfer kochen, das ihnen zusteht. Hier backen sie auch ihr Brot aus dem Speisopfer, damit man es nicht in den äußeren Vorhof hinaustragen muss und das Volk mit dem Heiligen in Berührung kommt.\"" },
      { number: 21, text: "Dann führte er mich in den äußeren Vorhof hinaus und zeigte mir die vier Ecken des Hofes. In jeder Ecke war ein kleiner Hof." },
      { number: 22, text: "Jeder dieser Höfe war 20 Meter lang und 15 Meter breit." },
      { number: 23, text: "Und um jeden war eine Steinreihe mit Feuerstellen auf der Innenseite." },
      { number: 24, text: "Er sagte: \"Das sind die Küchen, wo die Tempeldiener das Fleisch für die Opfermahlzeit des Volkes kochen.\"" },
    ] },
    { number: 47, verses: [
      { number: 1, text: "Dann führte er mich zum Eingang des Tempels zurück und ich sah, wie unter der Türschwelle Wasser hervorquoll. Es kam an der Südseite des Tempels heraus und floss südlich am Altar vorbei nach Osten ab, denn die Vorderseite des Hauses war nach Osten gerichtet.", heading: "Das neue Land (47-48)\nEin Fluss aus dem Tempel" },
      { number: 2, text: "Dann führte er mich durch das Nordtor hinaus und ließ mich außen um die Anlage herumgehen zum äußeren Osttor. Rechts davon floss das Wasser hinaus." },
      { number: 3, text: "Als der Mann mit der Messschnur in der Hand nach Osten hinausging, maß er 500 Meter ab und ließ mich durch das Wasser hindurchgehen. Es reichte mir bis an die Knöchel." },
      { number: 4, text: "Dann maß er wieder 500 Meter ab und ließ mich durch das Wasser waten. Es reichte mir bis zu den Knien. Darauf maß er wieder 500 Meter ab und ließ mich durchwaten. Das Wasser ging mir bis an die Hüften." },
      { number: 5, text: "Als er noch einmal 500 Meter abgemessen hatte, war das Wasser zu einem Fluss geworden, den ich nicht mehr durchwaten konnte. Man hätte schwimmen müssen." },
      { number: 6, text: "\"Hast du das gesehen, Mensch?\", sagte er zu mir und führte mich zum Ufer zurück." },
      { number: 7, text: "Da sah ich auf beiden Seiten des Flusses sehr viele Bäume stehen." },
      { number: 8, text: "Er sagte zu mir: \"Das Wasser fließt immer weiter nach Osten in die Araba* hinunter und ergießt sich ins Tote Meer. Dort wird das salzige Wasser gesund werden.", footnotes: ["Als Araba wird der Jordangraben bezeichnet, der sich von Nord nach Süd durch ganz Israel bis nach Elat am Roten Meer zieht. Sein Boden ist zwischen 12,5 und 22,5 km breit und befindet sich fast überall unter der Höhe des Meersspiegels, am Toten Meer 394 Meter unter NN."] },
      { number: 9, text: "Überall wohin der Fluss kommt, bringt er Leben. Alle Tiere gedeihen – überhaupt alles, was sich regt. Das Tote Meer wimmelt von Fischen, weil sein Wasser gesund geworden ist." },
      { number: 10, text: "An seinem Ufer werden Fischer stehen. Von En-Gedi* bis En-Eglajim* breiten sie ihre Netze zum Trocknen aus. Fische jeder Art wird es dort wieder geben, zahlreich wie im Mittelmeer.", footnotes: ["En-Gedi (Ziegenquell) ist eine Oase etwa in der Mitte des Westufers vom Toten Meer. Heute ist es ein Naturschutzgebiet.", "En-Eglajim (Quelle der zwei Kälber) lag wahrscheinlich am Süd-Ende des Toten Meeres, einige identifizieren es auch mit Ain Feschcha in der Nähe von Qumran."] },
      { number: 11, text: "Nur die Sümpfe und Tümpel werden nicht gesund; sie bleiben dem Salz überlassen." },
      { number: 12, text: "Aber an beiden Ufern des Flusses werden Fruchtbäume wachsen, die das ganze Jahr über grün sind und immer Früchte tragen, jeden Monat frische. Das ist so, weil sie von Wasser getränkt werden, das aus dem Heiligtum fließt. Ihre Früchte dienen als Nahrung und ihre Blätter als Heilmittel." },
      { number: 13, text: "So spricht Jahwe, der Herr: \"Das ist die Grenze, innerhalb derer ihr das Land als Grundbesitz an die zwölf Stämme verteilen sollt, wobei Josef zwei Teile* erhält.", heading: "Die Grenzen des Landes", footnotes: ["zwei Teile. Die Nachkommen Josefs bildeten zwei Stämme: Efraïm und Manasse."] },
      { number: 14, text: "Jeder einzelne soll darin seinen Erbbesitz erhalten, denn ich habe es euren Vorfahren geschworen: Dieses Land soll euer Erbbesitz sein." },
      { number: 15, text: "Seine Grenze verläuft im Norden vom Mittelmeer in Richtung Hetlon bis man nach Zedad kommt," },
      { number: 16, text: "Hamat, Berota, Sibrajim, das zwischen dem Gebiet von Damaskus und Hamat liegt, Hazar-Enan an der Grenze des Hauran-Gebiets." },
      { number: 17, text: "Die Grenze läuft also vom Meer nach Hazar-Enan*, wobei die Gebiete, die Damaskus und Hamat gehören, nördlich davon bleiben. Das ist die Nordgrenze.", footnotes: ["Hazar-Enan. Der Ort liegt 120 km nordöstlich von Damaskus. Das beschriebene Gebiet umfasst einen Großteil des Libanon und Syrien, einschließlich von Damaskus."] },
      { number: 18, text: "Die Ostgrenze verläuft zwischen dem Hauran-Gebirge und Damaskus hindurch bis zum Jordan, der dann auch die Grenze zwischen Gilead und dem Land Israel bildet. Bis zum östlichen Meer hin sollt ihr sie messen." },
      { number: 19, text: "Die Südgrenze verläuft von Tamar* bis zum Streitwasser von Kadesch und folgt dann dem Bachtal* bis zum großen Meer.", footnotes: ["Tamar ist vielleicht mit Ein Husb identisch, 37 km südwestlich von der Südspitze des Toten Meeres.", "Bachtal. Das Wadi El Arisch, das die Grenze zu Ägypten bildete."] },
      { number: 20, text: "Die Westgrenze ist die Mittelmeerküste bis dorthin, wo man nach Hamat kommt.\"" },
      { number: 21, text: "\"Dieses Land sollt ihr unter die Stämme Israels verteilen.", heading: "Die Aufteilung des Landes" },
      { number: 22, text: "Ihr sollt es euren Familien als Grundbesitz verlosen und ebenso den Fremden, die unter euch leben und eine Familie gegründet haben. Sie sollen für euch wie Einheimische sein und sich genauso wie die Stämme Israels ihren Erbbesitz erlosen." },
      { number: 23, text: "Im Gebiet des Stammes, in dem sie leben, sollen sie ihren Anteil an Grundbesitz bekommen, spricht Jahwe, der Herr.\"" },
    ] },
    { number: 48, verses: [
      { number: 1, text: "\"Folgende Aufteilung ist für die einzelnen Stämme vorgesehen: Ganz im Norden liegt der Anteil des Stammes Dan. Die Grenze verläuft entlang dem Weg von Hetlon nach Hamat und Hazar-Enan. Das Gebiet von Damaskus bleibt dabei nördlich liegen. Dann verläuft die Grenze vom Osten wieder ganz nach Westen." },
      { number: 2, text: "Darunter liegt der Anteil des Gebietes von Ascher, ein Streifen von Ost nach West," },
      { number: 3, text: "darunter der von Naftali," },
      { number: 4, text: "dann der von Manasse," },
      { number: 5, text: "von Efraïm," },
      { number: 6, text: "von Ruben" },
      { number: 7, text: "und von Juda." },
      { number: 8, text: "An das Gebiet von Juda schließt sich nach Süden zu der zwölfeinhalb Kilometer breite Landstreifen von Ost nach West an, den ihr mir weihen sollt. Mitten darin liegt das Heiligtum." },
      { number: 9, text: "Das mir geweihte Stück misst in Ost-West-Richtung zwölfeinhalb Kilometer und in Nord-Süd-Richtung zehn Kilometer*.", footnotes: ["zehn Kilometer. 20.000 Ellen mit der LXX wie schon in Hesekiel 45,1. Die meisten hebräischen Manuskripte haben 10.000 Ellen = fünf Kilometer."] },
      { number: 10, text: "Es soll den Priestern gehören; in seiner Mitte liegt ja das Heiligtum Jahwes." },
      { number: 11, text: "Die Priester aus der Nachkommenschaft Zadoks, die sich nicht wie die Leviten von mir abwandten, als sich Israel von mir abwandte, sondern treu ihren Dienst versahen," },
      { number: 12, text: "sollen eine Sonderweihgabe von diesem mir geweihten Land erhalten, ein höchst heiliges Stück Land neben dem Gebiet der Leviten." },
      { number: 13, text: "Die Leviten haben daneben ein Gebiet von zwölfeinhalb Kilometern Länge und fünf Kilometern Breite zur Verfügung." },
      { number: 14, text: "Es darf nichts davon verkauft werden, denn es ist der Erstteil des Landes, der Jahwe gehört." },
      { number: 15, text: "Der Streifen von zweieinhalb Kilometern Breite, der längs der zwölfeinhalb übrig bleibt, ist kein geweihtes Land. Er soll der Stadt als Wohngebiet und Weideland dienen." },
      { number: 16, text: "Die Nordseite der Stadt ist 2.250 Meter lang, ebenso ihre Süd-, Ost- und Westseite," },
      { number: 17, text: "und sie ist ringsherum von einem 125 Meter breiten Streifen Weideland umgeben." },
      { number: 18, text: "Daran schließt sich nach Westen und Osten je ein fünf Kilometer langes Stück Land an, das an den geweihten Bezirk grenzt. Von seinem Ertrag sollen die, die in der Stadt arbeiten, leben." },
      { number: 19, text: "Es sind Menschen aus allen Stämmen Israels, die dieses Land bebauen werden." },
      { number: 20, text: "Die ganze Weihgabe zusammen mit dem Grundbesitz der Stadt ist ein Quadrat von zwölfeinhalb Kilometern Seitenlänge." },
      { number: 21, text: "Das Gebiet, das sich nach beiden Seiten an das geweihte Gebiet und den Grundbesitz der Stadt bis zur Ost- und Westgrenze anschließt, soll dem Fürsten gehören. Das geweihte Gebiet mit dem Heiligtum und dem Tempel liegt in seiner Mitte." },
      { number: 22, text: "Der Grundbesitz der Leviten und der Stadt liegen mitten in dem Gebiet, das dem Fürsten gehört, und beide zusammen liegen zwischen den Gebieten Judas und Benjamins." },
      { number: 23, text: "Nach Süden zu schließt sich also der Anteil des Gebiets von Benjamin an, ein Landstreifen in ganzer Breite von Ost nach West," },
      { number: 24, text: "daneben der Anteil von Simeon," },
      { number: 25, text: "der von Issachar," },
      { number: 26, text: "Sebulon," },
      { number: 27, text: "und Gad." },
      { number: 28, text: "Die Südgrenze des Stammesgebietes von Gad fällt mit der Landesgrenze zusammen. Sie verläuft von Tamar bis zum Haderwasser von Kadesch und folgt dann dem Bachtal bis zum großen Meer." },
      { number: 29, text: "Dieses Land sollt ihr den einzelnen Stämmen als Grundbesitz verlosen, das sind ihre Anteile, spricht Jahwe, der Herr.\"" },
      { number: 30, text: "\"Die Stadt hat folgende Ausgänge: Auf der Nordseite – sie ist 2.250 Meter lang –", heading: "Die heilige Stadt" },
      { number: 31, text: "sind es drei Tore, das Ruben-, das Juda- und das Levi-Tor. Sie sind alle nach den Stämmen Israels benannt." },
      { number: 32, text: "Auf der Ostseite befinden sich das Josef-, das Benjamin- und das Dan-Tor," },
      { number: 33, text: "auf der Südseite das Simeon-, das Issachar- und das Sebulon-Tor" },
      { number: 34, text: "und auf der Westseite das Gad-, das Ascher- und das Naftali-Tor." },
      { number: 35, text: "Der ganze Umfang der Stadt beträgt neun Kilometer. Ihr Name heißt künftig: 'Hier ist Jahwe'.\"" },
    ] },
  ],
};